        ExprKind::Binary { lhs, rhs, .. }
        | ExprKind::Is { lhs, rhs, .. }
        | ExprKind::Like {
            expr: lhs,
            pattern: rhs,
            ..
        } => expr_contains_agg(lhs) || expr_contains_agg(rhs),
        ExprKind::Unary { expr: inner, .. }
        | ExprKind::IsNull { expr: inner, .. }
        | ExprKind::Paren(inner) => expr_contains_agg(inner),
        _ => false,
    }

