                    }
                }
                None => Err(PlanError::UnsupportedSelectItem(format!(
                    "unknown function {name}"
                ))),
            },
            _ if expr_contains_agg(expr) => Ok(Item::AggExpr(expr.clone())),
            _ => Ok(Item::Expr(expr.clone())),
