                hidden = hidden.saturating_add(1);
                regs.len().saturating_sub(1)
            }
            (None, ..) => {
                return Err(PlanError::UnsupportedSelectItem(format!(
                    "ORDER BY {label}: in a grouped or aggregate query, only a SELECT-list column or aggregate can be sorted on"
                )))
            }
        }

match unnest_of(select) {
        Some((_, column)) => {
            with_unnest = schema
                .iter()
                .cloned()
                .chain(std::iter::once(column.to_string()))
                .collect();
            &with_unnest[..]
        }
        None => schema,
    }

match item {
            Item::Star => columns.extend(schema.iter().map(|name| ResultColumn::Expr {
                expr: crate::parser::ast::Expr {
                    kind: ExprKind::Column {
                        table: None,
                        catalog: None,
                        name: name.clone(),
                    },
                    span: crate::parser::Span::UNKNOWN,
                },
                alias: None,
            })),
            _ => columns.push(col.clone()),
        }

match &expr.kind {
        ExprKind::Binary {
            op: AstBinOp::Or, ..
        } => (AstBinOp::Or, AstBinOp::Eq, false),
        ExprKind::Binary {
            op: AstBinOp::And, ..
        } => (AstBinOp::And, AstBinOp::Ne, true),
        _ => return None,
    }

match &expr.kind {
        ExprKind::Paren(inner) => chain_operands(inner, join),
        ExprKind::Binary { op, lhs, rhs } if *op == join => {
            let mut operands = chain_operands(lhs, join);
            operands.extend(chain_operands(rhs, join));
            operands
        }
        _ => vec![expr],
    }

match op {
        AstBinOp::Add => MapOp::Add,
        AstBinOp::Sub => MapOp::Sub,
        AstBinOp::Mul => MapOp::Mul,
        AstBinOp::Div => MapOp::Div,
        AstBinOp::Eq => MapOp::Eq,
        AstBinOp::Ne => MapOp::Ne,
        AstBinOp::Lt => MapOp::Lt,
        AstBinOp::Le => MapOp::Le,
        AstBinOp::Gt => MapOp::Gt,
        AstBinOp::Ge => MapOp::Ge,
        AstBinOp::And => MapOp::And,
        AstBinOp::Or => MapOp::Or,
        AstBinOp::Concat => MapOp::Concat,
        // `parser::column`'s validator rejects every other operator
        // (bitwise/shift/modulo) before this module ever sees the query --
        // reaching here means an unvalidated `Select` was compiled
        // directly. Fall back to `Eq` rather than panicking.
        AstBinOp::BitAnd | AstBinOp::BitOr | AstBinOp::Shl | AstBinOp::Shr | AstBinOp::Mod => {
            MapOp::Eq
        }
    }

match op {
        Opcode::Map { dst, .. }
        | Opcode::Call { dst, .. }
        | Opcode::InList { dst, .. }
        | Opcode::Select { dst, .. } => Some(*dst),
        _ => None,
    }

match op {
        Opcode::Map { a, b, .. } => vec![*a, *b],
        Opcode::Call { args, .. } => args.to_vec(),
        Opcode::InList { src, .. } => vec![*src],
        Opcode::Select {
            cond, then, else_, ..
        } => {
            let mut reads = vec![*cond];
            for arm in [then, else_] {
                if arm.ops.is_empty() {
                    reads.push(arm.out);
                } else {
                    reads.extend(arm.inputs.iter().copied());
                }
            }
            reads
        }
        _ => Vec::new(),
    }

match rest {
        [only] => compile_expr(only, ctx),
        _ => compile_coalesce(rest, ctx),
    }

match &expr.kind {
        ExprKind::Column { .. } => match expr_column_name(expr) {
            Some(name) => ctx.load_column(&name),
            None => {
                let reg = ctx.alloc();
                ctx.push(Opcode::LoadConst {
                    reg,
                    value: Value::Null,
                });
                reg
            }
        },
        ExprKind::Literal(lit) => {
            let reg = ctx.alloc();
            ctx.push(Opcode::LoadConst {
                reg,
                value: literal_value(lit),
            });
            reg
        }
        // A scalar call (#307): compiled args feed `Opcode::Call`, which
        // dispatches into `crate::functions::call` at execution time.
        // `classify_item` already rejected any top-level SELECT-list call
        // this planner doesn't recognize; a call reached only through a
        // nested expression (inside `WHERE`, another call's argument, ...)
        // is not similarly validated -- an unknown name there resolves to
        // `Value::Null` at runtime ([`Opcode::Call`]'s own doc comment),
        // the same fallback every other out-of-subset shape in this
        // function gets.
        // `x ILIKE p`, which the column dialect parses as `ilike(x, p)`
        // (#679): a case-insensitive LIKE.
        ExprKind::FunctionCall {
            name,
            args: FunctionArgs::List(list),
            tail: None,
            ..
        } if name.eq_ignore_ascii_case("ilike") && list.len() == 2 => {
            let a = list.first().map_or(0, |e| compile_expr(e, ctx));
            let b = list.get(1).map_or(0, |e| compile_expr(e, ctx));
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: MapOp::Like {
                    negated: false,
                    nocase: true,
                },
                a,
                b,
            });
            dst
        }
        // A lowered `CASE` (#725): the condition, and the value where it
        // holds and where it does not, each computed only for its rows.
        ExprKind::FunctionCall {
            name,
            args: FunctionArgs::List(list),
            tail: None,
            ..
        } if name.eq_ignore_ascii_case(crate::functions::SELECT_FN) && list.len() == 3 => {
            let cond = list.first().map_or(0, |e| compile_expr(e, ctx));
            let then = branch_of(ctx, |ctx| list.get(1).map_or(0, |e| compile_expr(e, ctx)));
            let else_ = branch_of(ctx, |ctx| list.get(2).map_or(0, |e| compile_expr(e, ctx)));
            let dst = ctx.alloc();
            ctx.push(Opcode::Select {
                dst,
                cond,
                then,
                else_,
            });
            dst
        }
        // `COALESCE` and `IFNULL` (#725): the first non-NULL argument, the
        // later ones computed only for the rows that need them.
        ExprKind::FunctionCall {
            name,
            args: FunctionArgs::List(list),
            tail: None,
            ..
        } if crate::functions::is_branch_scalar(name, list.len()) => compile_coalesce(list, ctx),
        ExprKind::FunctionCall {
            distinct: _,
            name,
            args: FunctionArgs::List(list),
            tail,
        } if tail.as_deref().is_none_or(|t| t.over.is_none()) => {
            let arg_regs: Vec<usize> = list.iter().map(|a| compile_expr(a, ctx)).collect();
            let dst = ctx.alloc();
            ctx.push(Opcode::Call {
                dst,
                name: name.clone().into(),
                args: arg_regs.into(),
            });
            dst
        }
        ExprKind::Paren(inner) => compile_expr(inner, ctx),
        // `compile_semi_join` handles `IN (subquery)` itself and strips it
        // from `where_clause` before ever calling `compile` -- reaching
        // this arm means `IN (subquery)`/`EXISTS` was used via the regular
        // single-table path, which can't run a subquery. Compile to an
        // always-false predicate (no rows) rather than panicking.
        ExprKind::InSubquery { .. } | ExprKind::Exists { .. } => {
            let reg = ctx.alloc();
            ctx.push(Opcode::LoadConst {
                reg,
                value: Value::Bool(false),
            });
            reg
        }
        ExprKind::Binary { op, lhs, rhs } => {
            let a = compile_expr(lhs, ctx);
            let b = compile_expr(rhs, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: map_bin_op(*op),
                a,
                b,
            });
            dst
        }
        ExprKind::Like {
            expr: inner,
            pattern,
            glob,
            negated,
            ..
        } => {
            let a = compile_expr(inner, ctx);
            let b = compile_expr(pattern, ctx);
            let dst = ctx.alloc();
            let op = if *glob {
                MapOp::Glob { negated: *negated }
            } else {
                MapOp::Like {
                    negated: *negated,
                    nocase: false,
                }
            };
            ctx.push(Opcode::Map { dst, op, a, b });
            dst
        }
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Not,
            expr: inner,
        } => {
            let a = compile_expr(inner, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: MapOp::Not,
                a,
                b: a,
            });
            dst
        }
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Minus,
            expr: inner,
        } => {
            let a = compile_expr(inner, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: MapOp::Neg,
                a,
                b: a,
            });
            dst
        }
        // Unary `+` is a no-op.
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Plus,
            expr: inner,
        } => compile_expr(inner, ctx),
        ExprKind::Unary { expr: inner, .. } => compile_expr(inner, ctx),
        ExprKind::IsNull {
            expr: inner,
            negated,
        } => {
            let a = compile_expr(inner, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: if *negated {
                    MapOp::IsNotNull
                } else {
                    MapOp::IsNull
                },
                a,
                b: a,
            });
            dst
        }
        // `expr IS [NOT] NULL` may also parse as `Is{lhs, rhs: NULL
        // literal, negated}`.
        ExprKind::Is { lhs, rhs, negated }
            if matches!(rhs.kind, ExprKind::Literal(AstLiteral::Null)) =>
        {
            let a = compile_expr(lhs, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: if *negated {
                    MapOp::IsNotNull
                } else {
                    MapOp::IsNull
                },
                a,
                b: a,
            });
            dst
        }
        // Anything else is outside the validated batch subset -- fall
        // back to NULL rather than panicking.
        _ => {
            let reg = ctx.alloc();
            ctx.push(Opcode::LoadConst {
                reg,
                value: Value::Null,
            });
            reg
        }
    }

match expr_column_name(expr) {
            Some(name) => ctx.load_column(&name),
            None => {
                let reg = ctx.alloc();
                ctx.push(Opcode::LoadConst {
                    reg,
                    value: Value::Null,
                });
                reg
            }
        }

match unnest_prologue(select, &mut ctx)? {
        Some(rest) => {
            unnested = rest;
            &unnested
        }
        None => select,
    }

match item {
            Item::Agg(_, arg, filter, distinct) => {
                let base = arg.as_ref().map(|a| match a {
                    // `COUNT(DISTINCT x)`'s `x` becomes a group key, which
                    // `GroupReduce` overwrites with the groups' keys: it
                    // gets a register of its own, not one an aggregate or
                    // a real key also reads (#633).
                    AggArg::Column(name) if *distinct && ctx.post_unnest => {
                        // Columns were loaded before the unnest and cannot
                        // be loaded again; a copy keeps the key's own register.
                        let src = ctx.load_column(name);
                        let reg = ctx.alloc();
                        ctx.push_commented(
                            Opcode::Map {
                                dst: reg,
                                op: MapOp::Copy,
                                a: src,
                                b: src,
                            },
                            format!("r{reg} = {name} (COUNT DISTINCT key)"),
                        );
                        reg
                    }
                    AggArg::Column(name) if *distinct => {
                        let reg = ctx.alloc();
                        ctx.push_commented(
                            Opcode::LoadColumn {
                                reg,
                                column: name.clone().into(),
                            },
                            format!("r{reg} = {name} (COUNT DISTINCT key)"),
                        );
                        reg
                    }
                    AggArg::Column(name) => ctx.load_column(name),
                    AggArg::Expr(expr) => compile_expr(expr, &mut ctx),
                });
                agg_srcs.push(vec![mask_filtered_source(&mut ctx, base, filter.as_ref())]);
            }
            // #496: each nested aggregate call's own argument is resolved
            // here, pre-`Filter`, for the same reason `Item::Agg`'s is
            // above -- `compile`'s second pass only allocates registers
            // and `AggPart`s from these already-resolved sources, it
            // never loads a column itself.
            Item::AggExpr(expr) => {
                let srcs = agg_expr_calls(expr)
                    .into_iter()
                    .map(|call| agg_call_source(call, &mut ctx))
                    .collect::<Result<Vec<_>>>()?;
                agg_srcs.push(srcs);
            }
            // Plain projected columns are emitted (not aggregated). A
            // column the WHERE clause also reads must be loaded here for
            // the same reason as the keys above: a column first loaded
            // below the Filter keeps its full pre-filter length while the
            // filtered registers shrink, and Emit then indexes past the end
            // of the short ones. A projection-only column (not referenced
            // by WHERE) is deliberately left unloaded here -- it's loaded
            // by the second pass further down, after `Filter` is emitted
            // (ADR-0026, late materialization). `load_column` memoizes, so
            // either way the projection code further down reuses whichever
            // register this loop already created instead of emitting a
            // second LoadColumn.
            Item::Column(name) if group_by.is_empty() => {
                if where_columns.iter().any(|c| c == name) {
                    ctx.load_column(name);
                }
                agg_srcs.push(Vec::new());
            }
            Item::Expr(expr) if group_by.is_empty() => {
                let mut cols = Vec::new();
                collect_expr_columns(expr, &mut cols);
                for name in &cols {
                    if where_columns.iter().any(|c| c == name) {
                        ctx.load_column(name);
                    }
                }
                agg_srcs.push(Vec::new());
            }
            _ => agg_srcs.push(Vec::new()),
        }

match a {
                    // `COUNT(DISTINCT x)`'s `x` becomes a group key, which
                    // `GroupReduce` overwrites with the groups' keys: it
                    // gets a register of its own, not one an aggregate or
                    // a real key also reads (#633).
                    AggArg::Column(name) if *distinct && ctx.post_unnest => {
                        // Columns were loaded before the unnest and cannot
                        // be loaded again; a copy keeps the key's own register.
                        let src = ctx.load_column(name);
                        let reg = ctx.alloc();
                        ctx.push_commented(
                            Opcode::Map {
                                dst: reg,
                                op: MapOp::Copy,
                                a: src,
                                b: src,
                            },
                            format!("r{reg} = {name} (COUNT DISTINCT key)"),
                        );
                        reg
                    }
                    AggArg::Column(name) if *distinct => {
                        let reg = ctx.alloc();
                        ctx.push_commented(
                            Opcode::LoadColumn {
                                reg,
                                column: name.clone().into(),
                            },
                            format!("r{reg} = {name} (COUNT DISTINCT key)"),
                        );
                        reg
                    }
                    AggArg::Column(name) => ctx.load_column(name),
                    AggArg::Expr(expr) => compile_expr(expr, &mut ctx),
                }

match reused {
            Some(_) => Ok(None),
            None => agg_call_source(call, &mut ctx),
        }

match reused {
            Some((i, k)) => item_slots.get(*i).and_then(|slots| slots.get(*k)).copied(),
            None => {
                let ExprKind::FunctionCall { name, .. } = &call.kind else {
                    return Err(PlanError::Internal(
                        "agg_expr_calls returned a non-FunctionCall node".into(),
                    ));
                };
                let func = AggFunc::from_name(name).unwrap_or(AggFunc::Count);
                Some(push_aggregate(
                    func,
                    *src,
                    &mut aggs,
                    &mut agg_dst,
                    &mut agg_parts,
                    &mut emit_regs,
                    &mut ctx,
                ))
            }
        }

match offset {
            0 => format!("LIMIT {n}"),
            m => format!("LIMIT {n} OFFSET {m}"),
        }

match &j.table.kind {
            TableRefKind::Unnest { expr, column } => {
                Some((&**expr, column.as_deref().unwrap_or("unnest")))
            }
            _ => None,
        }

match item {
            Item::Agg(AggFunc::Count, Some(AggArg::Column(name)), filter, true) => {
                let func = if int_columns.contains(&name) {
                    AggFunc::ExactCountDistinct
                } else if str_columns.contains(&name) {
                    AggFunc::ExactCountDistinctStr
                } else {
                    return Item::Agg(AggFunc::Count, Some(AggArg::Column(name)), filter, true);
                };
                Item::Agg(func, Some(AggArg::Column(name)), filter, false)
            }
            other => other,
        }

match col {
        ResultColumn::Expr { expr, .. } => Some(expr),
        _ => None,
    }

match &expr.kind {
        ExprKind::InSubquery { .. } | ExprKind::Exists { .. } => true,
        ExprKind::Binary { lhs, rhs, .. }
        | ExprKind::Is { lhs, rhs, .. }
        | ExprKind::Like {
            expr: lhs,
            pattern: rhs,
            ..
        } => expr_has_subquery(lhs) || expr_has_subquery(rhs),
        ExprKind::Unary { expr: inner, .. }
        | ExprKind::IsNull { expr: inner, .. }
        | ExprKind::Paren(inner) => expr_has_subquery(inner),
        ExprKind::FunctionCall {
            args: FunctionArgs::List(list),
            ..
        } => list.iter().any(expr_has_subquery),
        _ => false,
    }

match name.split_once('.') {
        Some((table, column)) => (Some(table), column),
        None => (None, name),
    }

match prefix {
            None => from_columns.push(name.clone()),
            Some(p) if p == from_name => from_columns.push(name.clone()),
            Some(p) if p == join.table => join_columns.push(name.clone()),
            Some(_) => return Err(PlanError::UnknownColumn(name.clone())),
        }

match build_override {
        None => false,
        Some(name) if name == join.table => false,
        Some(name) if name == from_name => true,
        Some(_) => {
            return Err(PlanError::Internal(
                "compile_join_build_side: build_table names neither the \
                 FROM table nor the JOIN target"
                    .into(),
            ))
        }
    }

match build_source {
        BuildSourceKind::RowTable => Opcode::ScanSource(ScanSource::RowTable {
            table: Cow::Owned(build_table_name.to_string()),
            columns: build_columns
                .iter()
                .map(|n| Cow::Owned(split_qualified(n).1.to_string()))
                .collect(),
        }),
        BuildSourceKind::Stream => Opcode::ScanSource(ScanSource::Stream {
            handle: 0,
            columns: build_columns
                .iter()
                .map(|n| Cow::Owned(n.clone()))
                .collect(),
            #[cfg(feature = "vm-stream")]
            scope: None,
        }),
        BuildSourceKind::InMemory => {
            Opcode::ScanSource(ScanSource::InMemory(crate::vm::batch::Batch::default()))
        }
    }

match join.op {
        JoinOp::Inner => crate::vm::batch::JoinKind::Inner,
        JoinOp::Left => crate::vm::batch::JoinKind::Left,
        other => return Err(PlanError::UnsupportedJoinKind(other)),
    }

match fused {
        Some((fused_op, fused_output, trimmed_body)) => (
            Program::from_opcodes(probe_load.chain(std::iter::once(fused_op))),
            trimmed_body,
            Some(fused_output),
        ),
        None => (
            Program::from_opcodes(probe_load.chain(std::iter::once(Opcode::HashProbe {
                key_cols: vec![probe_key_reg].into(),
                table: 0,
                payload_dst: payload_dst.clone().into(),
                kind: join_kind,
            }))),
            body,
            None,
        ),
    }

match src {
            Some(reg) => Some(resolve_source(*reg)?),
            None => None,
        }

match prefix {
            None => None,
            Some(p) if p == from_name => None,
            Some(p) => joins.iter().position(|j| j.table == p),
        }

match prefix {
            None => Ok("from"),
            Some(p) if p == from_name => Ok("from"),
            Some(p) if p == join_table => Ok("join"),
            Some(_) => Err(PlanError::UnknownColumn(col.to_string())),
        }

match (left_owner, right_owner) {
            ("from", "join") => (&join.left_col, &join.right_col),
            ("join", "from") => (&join.right_col, &join.left_col),
            _ => {
                return Err(PlanError::UnknownColumn(format!(
                    "JOIN ON must equate the driving table to `{}`",
                    join.table
                )))
            }
        }

match join.op {
            JoinOp::Inner => crate::vm::batch::JoinKind::Inner,
            JoinOp::Left => crate::vm::batch::JoinKind::Left,
            other => return Err(PlanError::UnsupportedJoinKind(other)),
        }

match item {
            Item::Column(name) => push_needed(name, &mut needed),
            Item::Window(spec) => {
                if let Some(arg) = &spec.arg {
                    push_needed(arg, &mut needed);
                }
                for p in &spec.partition_by {
                    push_needed(p, &mut needed);
                }
                for (o, _) in &spec.order_by {
                    push_needed(o, &mut needed);
                }
            }
            Item::Agg(..) | Item::Star | Item::Expr(_) | Item::AggExpr(_) => {}
        }

match item {
            Item::Window(spec) => {
                let base = spec.arg.as_ref().map(|name| ctx.load_column(name));
                mask_filtered_source(&mut ctx, base, spec.filter.as_ref())
            }
            _ => None,
        }

match item {
            Item::Column(name) => emit_regs.push(column_reg(name)?),
            Item::Window(spec) => {
                let dst = next_reg;
                next_reg = next_reg.saturating_add(1);
                program.push(Instruction::with_comment(
                    Opcode::Window {
                        func: map_window_func(spec.func),
                        // Already resolved (and `FILTER`-masked, if any)
                        // above -- same register `column_reg(arg)` would
                        // give when there's no filter, since `needed`
                        // seeded `ctx`'s `column_regs`.
                        arg: *filtered_arg,
                        offset: spec.offset,
                        partition_by: spec
                            .partition_by
                            .iter()
                            .map(|p| column_reg(p))
                            .collect::<Result<Vec<_>>>()?
                            .into(),
                        order_by: spec
                            .order_by
                            .iter()
                            .map(|(o, desc)| Ok((column_reg(o)?, *desc)))
                            .collect::<Result<Vec<_>>>()?
                            .into(),
                        dst,
                    },
                    format!("r{dst} = {}", window_detail(spec)),
                ));
                emit_regs.push(dst);
            }
            Item::Agg(..) | Item::Star | Item::Expr(_) | Item::AggExpr(_) => {
                let reg = *null_reg.get_or_insert_with(|| {
                    let reg = next_reg;
                    next_reg = next_reg.saturating_add(1);
                    program.push(Instruction::new(Opcode::LoadConst {
                        reg,
                        value: Value::Null,
                    }));
                    reg
                });
                emit_regs.push(reg);
            }
        }

match item {
            Item::Column(_) | Item::Expr(_) => &mut next_key,
            Item::Agg(_, _, _, true) => &mut distinct_slot,
            Item::Agg(..) | Item::AggExpr(_) => &mut next_agg,
            Item::Star | Item::Window(_) => return Vec::new(),
        }

let Some(AstExpr {
            kind: ExprKind::InSubquery { expr, subquery, .. },
            ..
        }) = &select.where_clause

match src {
        Some(s) => format!("{func:?}({s})"),
        None => format!("{func:?}"),
    }

match op {
        Opcode::LoadColumn { reg, column } => format!("reg={reg} column={column}"),
        Opcode::LoadConst { reg, value } => format!("reg={reg} value={value}"),
        Opcode::Map { dst, op, a, b } => format!("dst={dst} op={op:?} a={a} b={b}"),
        Opcode::Filter { predicate } => format!("predicate=r{predicate}"),
        Opcode::Reduce { func, src, dst } => {
            format!("dst={dst} {}", render_agg_pair(*func, *src))
        }
        Opcode::GroupReduce {
            group_by,
            aggs,
            agg_dst,
        } => {
            let aggs: Vec<String> = aggs
                .iter()
                .map(|(func, src)| render_agg_pair(*func, *src))
                .collect();
            format!(
                "group_by={group_by:?} aggs=[{}] agg_dst={agg_dst:?}",
                aggs.join(", ")
            )
        }
        Opcode::HashBuild {
            key_cols,
            payload_cols,
            table,
        } => format!("key_cols={key_cols:?} payload_cols={payload_cols:?} table={table}"),
        Opcode::HashProbe {
            key_cols,
            table,
            payload_dst,
            kind,
        } => format!("key_cols={key_cols:?} table={table} payload_dst={payload_dst:?} kind={kind:?}"),
        Opcode::Unnest { src, dst } => format!("src={src} dst={dst}"),
        Opcode::HashProbeGroupReduce {
            key_cols,
            table,
            kind,
            group_by,
            aggs,
            agg_dst,
        } => {
            let aggs: Vec<String> = aggs
                .iter()
                .map(|(func, src)| match src {
                    Some(s) => format!("{func:?}({s:?})"),
                    None => format!("{func:?}"),
                })
                .collect();
            format!(
                "key_cols={key_cols:?} table={table} kind={kind:?} group_by={group_by:?} aggs=[{}] agg_dst={agg_dst:?}",
                aggs.join(", ")
            )
        }
        Opcode::Window {
            func,
            arg,
            offset,
            partition_by,
            order_by,
            dst,
        } => format!(
            "dst={dst} func={func:?} arg={arg:?} offset={offset:?} partition_by={partition_by:?} order_by={order_by:?}"
        ),
        Opcode::Scan => String::new(),
        Opcode::ScanSource(source) => render_scan_source(source),
        Opcode::Emit { registers } => format!("registers={registers:?}"),
        Opcode::NextSegment { loop_start } => format!("loop_start={loop_start}"),
        Opcode::Halt => String::new(),
        Opcode::Combine {
            agg_parts,
            num_group_keys,
            distinct,
            output_order,
            project,
        } => {
            let mut operands =
                format!("agg_parts={agg_parts:?} num_group_keys={num_group_keys} distinct={distinct}");
            if !output_order.is_empty() {
                operands = format!("{operands} output_order={output_order:?}");
            }
            if !project.is_empty() {
                let steps: Vec<String> = project
                    .iter()
                    .map(|op| format!("{} {}", op.name(), render_operands(op)))
                    .collect();
                operands = format!("{operands} project=[{}]", steps.join("; "));
            }
            operands
        }
        Opcode::Sort { keys, hidden } => format!("keys={keys:?} hidden={hidden}"),
        Opcode::Limit { n, offset } => format!("n={n} offset={offset}"),
        Opcode::Call { dst, name, args } => format!("dst={dst} name={name} args={args:?}"),
        // The item count, not the items: a list of a hundred ids would
        // drown the plan.
        Opcode::InList {
            dst,
            src,
            list,
            negated,
        } => format!("dst={dst} src={src} items={} negated={negated}", list.len()),
        Opcode::Select {
            dst,
            cond,
            then,
            else_,
        } => {
            let arm = |b: &Branch| format!("r{}[{} ops]", b.out, b.ops.len());
            format!("dst={dst} cond={cond} then={} else={}", arm(then), arm(else_))
        }
    }

match src {
                    Some(s) => format!("{func:?}({s:?})"),
                    None => format!("{func:?}"),
                }

match source {
        ScanSource::RowTable { table, columns } => {
            format!("row table={table} columns={columns:?}")
        }
        #[cfg(feature = "vm-stream")]
        ScanSource::Stream {
            handle,
            columns,
            scope,
        } => format!("stream handle={handle} columns={columns:?} scope={scope:?}"),
        #[cfg(not(feature = "vm-stream"))]
        ScanSource::Stream { handle, columns } => {
            format!("stream handle={handle} columns={columns:?}")
        }
        ScanSource::InMemory(batch) => format!("in-memory rows={}", batch.num_rows),
    }

match classify_item(item) {
        Ok(Item::Column(name)) => name,
        Ok(Item::Star) => "*".to_string(),
        Ok(Item::Agg(func, Some(AggArg::Column(col)), _, true)) => {
            format!("{}(DISTINCT {col})", agg_func_name(func))
        }
        Ok(Item::Agg(func, Some(AggArg::Expr(expr)), _, true)) => {
            format!(
                "{}(DISTINCT {})",
                agg_func_name(func),
                expr_to_string(&expr)
            )
        }
        Ok(Item::Agg(func, arg, _, _)) => match arg {
            Some(AggArg::Column(col)) => format!("{}({col})", agg_func_name(func)),
            Some(AggArg::Expr(expr)) => {
                format!("{}({})", agg_func_name(func), expr_to_string(&expr))
            }
            None => format!("{}(*)", agg_func_name(func)),
        },
        Ok(Item::Window(spec)) => format!("{}()", window_func_name(spec.func)),
        Ok(Item::Expr(expr) | Item::AggExpr(expr)) => expr_to_string(&expr),
        Err(_) => String::new(),
    }

match arg {
            Some(AggArg::Column(col)) => format!("{}({col})", agg_func_name(func)),
            Some(AggArg::Expr(expr)) => {
                format!("{}({})", agg_func_name(func), expr_to_string(&expr))
            }
            None => format!("{}(*)", agg_func_name(func)),
        }

match &expr.kind {
        // A `Column` always carries a name; `expr_column_name` is `None`
        // only for non-column kinds, which this arm excludes. Plan text.
        ExprKind::Column { .. } => expr_column_name(expr).unwrap_or_default(),
        ExprKind::Literal(lit) => literal_to_string(lit),
        ExprKind::Paren(inner) => expr_to_string(inner),
        ExprKind::Binary { op, lhs, rhs } => {
            format!(
                "{} {} {}",
                expr_to_string(lhs),
                bin_op_str(*op),
                expr_to_string(rhs)
            )
        }
        ExprKind::InSubquery { expr, subquery, .. } => {
            // Plan text only: the real compile reports a missing alias as
            // `PlanError::Internal`; here it just renders as "".
            let from = subquery
                .from
                .as_ref()
                .and_then(|f| table_name(f).ok())
                .unwrap_or_default();
            format!("{} IN (SELECT ... FROM {from})", expr_to_string(expr))
        }
        ExprKind::Exists { subquery, negated } => {
            // Plan text only: the real compile reports a missing alias as
            // `PlanError::Internal`; here it just renders as "".
            let from = subquery
                .from
                .as_ref()
                .and_then(|f| table_name(f).ok())
                .unwrap_or_default();
            format!(
                "{}EXISTS (SELECT ... FROM {from})",
                if *negated { "NOT " } else { "" }
            )
        }
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Not,
            expr: inner,
        } => format!("NOT {}", expr_to_string(inner)),
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Minus,
            expr: inner,
        } => format!("-{}", expr_to_string(inner)),
        ExprKind::Unary { expr: inner, .. } => expr_to_string(inner),
        ExprKind::IsNull { expr, negated } => {
            format!(
                "{} IS {}NULL",
                expr_to_string(expr),
                if *negated { "NOT " } else { "" }
            )
        }
        ExprKind::Is { lhs, rhs, negated }
            if matches!(rhs.kind, ExprKind::Literal(AstLiteral::Null)) =>
        {
            format!(
                "{} IS {}NULL",
                expr_to_string(lhs),
                if *negated { "NOT " } else { "" }
            )
        }
        _ => String::new(),
    }

match &expr.kind {
        ExprKind::Column { .. } => {
            if let Some(name) = expr_column_name(expr) {
                push_unique(out, name);
            }
        }
        ExprKind::Literal(_) => {}
        ExprKind::Paren(inner) => collect_expr_columns(inner, out),
        ExprKind::Binary { lhs, rhs, .. } => {
            collect_expr_columns(lhs, out);
            collect_expr_columns(rhs, out);
        }
        ExprKind::InSubquery { expr, .. } => collect_expr_columns(expr, out),
        ExprKind::Exists { .. } => {}
        ExprKind::Unary { expr: inner, .. } => collect_expr_columns(inner, out),
        ExprKind::IsNull { expr, .. } => collect_expr_columns(expr, out),
        ExprKind::Is { lhs, .. } => collect_expr_columns(lhs, out),
        ExprKind::Like { expr, pattern, .. } => {
            collect_expr_columns(expr, out);
            collect_expr_columns(pattern, out);
        }
        // A scalar call's (#307) column references are its arguments' --
        // needed so a bare (non-`GROUP BY`) `SELECT json_extract(msg, ...)`
        // pre-loads `msg` before `Filter`, same as any other expression.
        ExprKind::FunctionCall {
            args: FunctionArgs::List(list),
            ..
        } => {
            for arg in list {
                collect_expr_columns(arg, out);
            }
        }
        _ => {}
    }

match item {
            Item::Column(name) => push_unique(&mut out, name.clone()),
            Item::Star => {}
            Item::Agg(_, arg, filter, _) => {
                match arg {
                    Some(AggArg::Column(name)) => push_unique(&mut out, name.clone()),
                    Some(AggArg::Expr(expr)) => collect_expr_columns(expr, &mut out),
                    None => {}
                }
                if let Some(f) = filter {
                    let mut cols = Vec::new();
                    collect_expr_columns(f, &mut cols);
                    for name in cols {
                        push_unique(&mut out, name);
                    }
                }
            }
            Item::Window(spec) => {
                if let Some(arg) = &spec.arg {
                    push_unique(&mut out, arg.clone());
                }
                for name in &spec.partition_by {
                    push_unique(&mut out, name.clone());
                }
                for (name, _) in &spec.order_by {
                    push_unique(&mut out, name.clone());
                }
                if let Some(f) = &spec.filter {
                    collect_expr_columns(f, &mut out);
                }
            }
            Item::Expr(expr) | Item::AggExpr(expr) => collect_expr_columns(expr, &mut out),
        }

match arg {
                    Some(AggArg::Column(name)) => push_unique(&mut out, name.clone()),
                    Some(AggArg::Expr(expr)) => collect_expr_columns(expr, &mut out),
                    None => {}
                }

match op {
                Opcode::InList { list, negated, .. } => Some((list.to_vec(), *negated)),
                _ => None,
            }

match op {
                Opcode::LoadColumn { column, .. } => Some(column.to_string()),
                _ => None,
            }

match op {
                Opcode::Combine { agg_parts, .. } => Some(agg_parts.to_vec()),
                _ => None,
            }

match self {
            EmitError::Parse(e) => write!(f, "{e}"),
            EmitError::Unsupported(what) => write!(f, "codegen does not support {what} yet"),
            EmitError::Plan(e) => write!(f, "{e}"),
        }

match c {
        ResultColumn::Expr {
            expr:
                AstExpr {
                    kind: ExprKind::FunctionCall { tail, .. },
                    ..
                },
            ..
        } => matches!(tail.as_deref(), Some(t) if t.over.is_some()),
        _ => false,
    }

match &select.where_clause {
        Some(AstExpr {
            kind:
                ExprKind::InSubquery {
                    expr,
                    subquery,
                    negated: false,
                },
            ..
        }) if matches!(expr.kind, ExprKind::Column { .. }) => Some(subquery),
        _ => None,
    }

match &from.first.kind {
        TableRefKind::Name(name) => Ok(name),
        // The grammar requires the alias; emitting `""` as a table name
        // would produce a program that can never bind a file (db-core#232).
        TableRefKind::Subquery(_) => from
            .first
            .alias
            .as_deref()
            .ok_or(EmitError::Unsupported("a FROM subquery without an alias")),
        TableRefKind::Unnest { .. } => {
            Err(EmitError::Unsupported("UNNEST as the first FROM entry"))
        }
    }

match &term.kind {
        ExprKind::Column {
            table: None, name, ..
        } => select.columns.iter().any(|col| match col {
            ResultColumn::Expr {
                expr,
                alias: Some(alias),
            } => alias == name && !is_bare_column(expr, name),
            _ => false,
        }),
        _ => false,
    }

match col {
            ResultColumn::Expr {
                expr,
                alias: Some(alias),
            } => alias == name && !is_bare_column(expr, name),
            _ => false,
        }

match &instruction.comment {
            Some(comment) => {
                let _ = writeln!(
                    out,
                    "    {}, // {}",
                    render_opcode(&instruction.opcode),
                    comment.replace('\n', " ")
                );
            }
            None => {
                let _ = writeln!(out, "    {},", render_opcode(&instruction.opcode));
            }
        }

match kind {
        HiddenPart::Sum => "Sum".to_string(),
        HiddenPart::Count => "Count".to_string(),
        HiddenPart::Min => "Min".to_string(),
        HiddenPart::Max => "Max".to_string(),
    }

match op {
        AggOperand::Slot(i) => format!("AggOperand::Slot({i})"),
        AggOperand::Avg(sum, count) => format!("AggOperand::Avg({sum}, {count})"),
        AggOperand::Literal(f) => format!("AggOperand::Literal({f:?})"),
    }

match s {
        Some(s) => format!("Some({}.to_string())", rust_str_literal(s)),
        None => "None".to_string(),
    }

match kind {
        TableRefKind::Name(name) => {
            format!("TableRefKind::Name({}.to_string())", rust_str_literal(name))
        }
        TableRefKind::Subquery(select) => {
            format!(
                "TableRefKind::Subquery(Box::new({}))",
                render_select(select)
            )
        }
        TableRefKind::Unnest { expr, column } => {
            let column = column.as_ref().map_or("None".to_string(), |c| {
                format!("Some({}.to_string())", rust_str_literal(c))
            });
            format!(
                "TableRefKind::Unnest {{ expr: Box::new({}), column: {column} }}",
                render_expr(expr)
            )
        }
    }

match constraint {
        JoinConstraint::On(expr) => format!("JoinConstraint::On({})", render_expr(expr)),
        JoinConstraint::Using(cols) => format!(
            "JoinConstraint::Using(vec![{}])",
            cols.iter()
                .map(|c| format!("{}.to_string()", rust_str_literal(c)))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    }

match col {
        ResultColumn::Star => "ResultColumn::Star".to_string(),
        ResultColumn::TableStar { table } => format!(
            "ResultColumn::TableStar {{ table: {}.to_string() }}",
            rust_str_literal(table)
        ),
        ResultColumn::Expr { expr, alias } => format!(
            "ResultColumn::Expr {{ expr: {}, alias: {} }}",
            render_expr(expr),
            render_option_str(alias.as_deref())
        ),
    }

match kind {
        ExprKind::Literal(lit) => format!("ExprKind::Literal({})", render_literal(lit)),
        ExprKind::Column {
            table,
            catalog,
            name,
        } => format!(
            "ExprKind::Column {{ table: {}, catalog: {}, name: {}.to_string() }}",
            render_option_str(table.as_deref()),
            render_option_str(catalog.as_deref()),
            rust_str_literal(name)
        ),
        ExprKind::FunctionCall {
            name,
            distinct,
            args,
            tail,
        } => format!(
            "ExprKind::FunctionCall {{ name: {}.to_string(), distinct: {distinct}, args: {}, tail: {} }}",
            rust_str_literal(name),
            render_function_args(args),
            match tail {
                // `range` (#308) is stream-only: `codegen::batch` never
                // plans a call carrying one (rejected upstream, same as
                // `Select::scope`), so this emits a literal `None` rather
                // than rendering `t.range` at all.
                Some(t) => format!(
                    "Some(Box::new(FunctionTail {{ filter: {}, over: {}, range: None }}))",
                    match &t.filter {
                        Some(f) => format!("Some({})", render_expr(f)),
                        None => "None".to_string(),
                    },
                    match &t.over {
                        Some(w) => format!("Some({})", render_window_def(w)),
                        None => "None".to_string(),
                    }
                ),
                None => "None".to_string(),
            }
        ),
        ExprKind::Unary { op, expr } => {
            format!("ExprKind::Unary {{ op: UnaryOp::{}, expr: Box::new({}) }}", render_unary_op(*op), render_expr(expr))
        }
        ExprKind::Binary { op, lhs, rhs } => format!(
            "ExprKind::Binary {{ op: BinaryOp::{}, lhs: Box::new({}), rhs: Box::new({}) }}",
            render_binary_op(*op),
            render_expr(lhs),
            render_expr(rhs)
        ),
        ExprKind::Is { lhs, rhs, negated } => format!(
            "ExprKind::Is {{ lhs: Box::new({}), rhs: Box::new({}), negated: {negated} }}",
            render_expr(lhs),
            render_expr(rhs)
        ),
        ExprKind::IsNull { expr, negated } => format!(
            "ExprKind::IsNull {{ expr: Box::new({}), negated: {negated} }}",
            render_expr(expr)
        ),
        ExprKind::Paren(inner) => format!("ExprKind::Paren(Box::new({}))", render_expr(inner)),
        ExprKind::InSubquery {
            expr,
            subquery,
            negated,
        } => format!(
            "ExprKind::InSubquery {{ expr: Box::new({}), subquery: Box::new({}), negated: {negated} }}",
            render_expr(expr),
            render_select(subquery)
        ),
        ExprKind::Exists { subquery, negated } => format!(
            "ExprKind::Exists {{ subquery: Box::new({}), negated: {negated} }}",
            render_select(subquery)
        ),
        // Not part of the batch planner's validated subset -- `generate`
        // never plans a query containing these, so no renderer feeds
        // this arm today. Not a feature gap to silently paper over: once
        // a real caller needs one of these, this arm should become a
        // real render, not before.
        ExprKind::Param(_)
        | ExprKind::Between { .. }
        | ExprKind::In { .. }
        | ExprKind::Like { .. }
        | ExprKind::Case { .. }
        | ExprKind::Cast { .. }
        | ExprKind::Collate { .. }
        | ExprKind::Subquery(_)
        | ExprKind::InSubqueryMulti { .. } => {
            // Rendered as a `compile_error!` in the *generated* source, so
            // if a planner ever does feed one of these here the consumer's
            // build fails loudly with the exact shape -- rather than this
            // emitter panicking (an `unreachable!` the qualified subset
            // forbids) or silently emitting a fake rendering.
            format!(
                "compile_error!(\"db-core emit does not yet render {}\")",
                format!("{kind:?}").replace('"', "'")
            )
        }
    }

match op {
        UnaryOp::Not => "Not",
        UnaryOp::Plus => "Plus",
        UnaryOp::Minus => "Minus",
        UnaryOp::BitNot => "BitNot",
    }

match op {
        Opcode::LoadColumn { reg, column } => format!(
            "Opcode::LoadColumn {{ reg: {reg}, column: std::borrow::Cow::Borrowed({}) }}",
            rust_str_literal(column)
        ),
        Opcode::LoadConst { reg, value } => format!(
            "Opcode::LoadConst {{ reg: {reg}, value: {} }}",
            render_value(value)
        ),
        Opcode::Map { dst, op, a, b } => format!(
            "Opcode::Map {{ dst: {dst}, op: MapOp::{}, a: {a}, b: {b} }}",
            render_map_op(*op)
        ),
        Opcode::Filter { predicate } => format!("Opcode::Filter {{ predicate: {predicate} }}"),
        Opcode::Reduce { func, src, dst } => format!(
            "Opcode::Reduce {{ func: AggFunc::{}, src: {}, dst: {dst} }}",
            render_agg_func(*func),
            render_option_usize(*src)
        ),
        Opcode::GroupReduce {
            group_by,
            aggs,
            agg_dst,
        } => {
            let group_by = render_usize_slice(group_by);
            let agg_dst = render_usize_slice(agg_dst);
            let aggs: Vec<String> = aggs
                .iter()
                .map(|(f, s)| {
                    format!(
                        "(AggFunc::{}, {})",
                        render_agg_func(*f),
                        render_option_usize(*s)
                    )
                })
                .collect();
            format!("Opcode::GroupReduce {{ group_by: std::borrow::Cow::Borrowed(&{group_by}), aggs: std::borrow::Cow::Borrowed(&[{}]), agg_dst: std::borrow::Cow::Borrowed(&{agg_dst}) }}", aggs.join(", "))
        }
        Opcode::Scan => "Opcode::Scan".to_string(),
        Opcode::Emit { registers } => format!(
            "Opcode::Emit {{ registers: std::borrow::Cow::Borrowed(&{}) }}",
            render_usize_slice(registers)
        ),
        Opcode::NextSegment { loop_start } => {
            format!("Opcode::NextSegment {{ loop_start: {loop_start} }}")
        }
        Opcode::Halt => "Opcode::Halt".to_string(),
        Opcode::Combine {
            agg_parts,
            num_group_keys,
            distinct,
            output_order,
            project,
        } => {
            let parts: Vec<String> = agg_parts.iter().map(render_agg_part).collect();
            let project: Vec<String> = project.iter().map(render_opcode).collect();
            format!(
                "Opcode::Combine {{ agg_parts: std::borrow::Cow::Borrowed(&[{}]), num_group_keys: {num_group_keys}, distinct: {distinct}, output_order: std::borrow::Cow::Borrowed(&{}), project: std::borrow::Cow::Borrowed(&[{}]) }}",
                parts.join(", "),
                render_usize_slice(output_order),
                project.join(", "),
            )
        }
        Opcode::Sort { keys, hidden } => {
            let keys: Vec<String> = keys.iter().map(|(c, d)| format!("({c}, {d})")).collect();
            format!(
                "Opcode::Sort {{ keys: std::borrow::Cow::Borrowed(&[{}]), hidden: {hidden} }}",
                keys.join(", ")
            )
        }
        Opcode::Limit { n, offset } => format!("Opcode::Limit {{ n: {n}, offset: {offset} }}"),
        Opcode::InList {
            dst,
            src,
            list,
            negated,
        } => {
            let list: Vec<String> = list.iter().map(render_value).collect();
            format!(
                "Opcode::InList {{ dst: {dst}, src: {src}, list: std::borrow::Cow::Borrowed(&[{}]), negated: {negated} }}",
                list.join(", ")
            )
        }
        Opcode::Select {
            dst,
            cond,
            then,
            else_,
        } => {
            let arm = |b: &Branch| {
                let ops: Vec<String> = b.ops.iter().map(render_opcode).collect();
                format!(
                    "(&[{}], {}, &{})",
                    ops.join(", "),
                    b.out,
                    render_usize_slice(&b.inputs)
                )
            };
            format!(
                "Opcode::select({dst}, {cond}, {}, {})",
                arm(then),
                arm(else_)
            )
        }
        // No caller-side planner emits these three yet -- the join/semi-
        // join/window bypass shapes ([`render_joined`]/
        // [`render_semi_join`]/[`render_windowed`]) still reconstruct a
        // `Select` literal instead of a `const PROGRAM` for those cases
        // (see this module's top doc comment), so no flat program this
        // module renders contains them. Not a feature gap to silently
        // paper over with a fake rendering: once a real planner starts
        // emitting these, this arm should become a real render_*
        // implementation at that point, not before.
        Opcode::HashBuild { .. }
        | Opcode::HashProbe { .. }
        | Opcode::Unnest { .. }
        | Opcode::HashProbeGroupReduce { .. }
        | Opcode::Window { .. }
        | Opcode::Call { .. }
        | Opcode::ScanSource { .. } => {
            // Same `compile_error!`-in-generated-source strategy as
            // `render_expr_kind`'s unsupported arm: loud at the consumer's
            // build, no panic here.
            format!(
                "compile_error!(\"db-core emit does not yet render {}\")",
                format!("{op:?}").replace('"', "'")
            )
        }
    }

match value {
        Value::Int(v) => format!("Value::Int({v})"),
        Value::Float(v) => format!("Value::Float({v:?})"),
        Value::Bool(v) => format!("Value::Bool({v})"),
        Value::Str(v) => format!(
            "Value::Str(std::borrow::Cow::Borrowed({}))",
            rust_str_literal(v)
        ),
        Value::Null => "Value::Null".to_string(),
        // Programs hold literals only; a map or list is only ever column
        // data.
        Value::Map(_) | Value::List(_) | Value::Bytes(_) => "Value::Null".to_string(),
        Value::Decimal { unscaled, scale } => {
            format!("Value::Decimal {{ unscaled: {unscaled}, scale: {scale} }}")
        }
    }

match self {
            JoinColumnsError::AmbiguousColumn { name, tables } => write!(
                f,
                "ambiguous column name: {name} (in {}); qualify it with its table",
                tables.join(", ")
            ),
            JoinColumnsError::UnknownStarTable(table) => {
                write!(f, "unknown table in {table}.*: {table}")
            }
            JoinColumnsError::Plan(e) => e.fmt(f),
        }

match c {
            ResultColumn::Star => columns.extend(all.iter().filter(|e| !e.merged).map(item)),
