match &expr.kind {
        ExprKind::Literal(_)
        | ExprKind::Param(_)
        | ExprKind::Column { .. }
        | ExprKind::Subquery(_)
        | ExprKind::Exists { .. } => expr.kind.clone(),
        ExprKind::FunctionCall {
            name,
            distinct,
            args,
            tail,
        } => ExprKind::FunctionCall {
            name: name.clone(),
            distinct: *distinct,
            args: match args {
                FunctionArgs::Star => FunctionArgs::Star,
                FunctionArgs::List(list) => {
                    FunctionArgs::List(list.iter().map(&mut *f).collect::<Result<_, _>>()?)
                }
            },
            tail: tail.clone(),
        },
        ExprKind::Unary { op, expr: inner } => ExprKind::Unary {
            op: *op,
            expr: boxed(f, inner)?,
        },
        ExprKind::Binary { op, lhs, rhs } => ExprKind::Binary {
            op: *op,
            lhs: boxed(f, lhs)?,
            rhs: boxed(f, rhs)?,
        },
        ExprKind::Is { lhs, rhs, negated } => ExprKind::Is {
            lhs: boxed(f, lhs)?,
            rhs: boxed(f, rhs)?,
            negated: *negated,
        },
        ExprKind::IsNull {
            expr: inner,
            negated,
        } => ExprKind::IsNull {
            expr: boxed(f, inner)?,
            negated: *negated,
        },
        ExprKind::Between {
            expr: inner,
            lo,
            hi,
            negated,
        } => ExprKind::Between {
            expr: boxed(f, inner)?,
            lo: boxed(f, lo)?,
            hi: boxed(f, hi)?,
            negated: *negated,
        },
        ExprKind::In {
            expr: inner,
            list,
            negated,
        } => ExprKind::In {
            expr: boxed(f, inner)?,
            list: list.iter().map(&mut *f).collect::<Result<_, _>>()?,
            negated: *negated,
        },
        ExprKind::Like {
            expr: inner,
            pattern,
            glob,
            negated,
            escape,
        } => ExprKind::Like {
            expr: boxed(f, inner)?,
            pattern: boxed(f, pattern)?,
            glob: *glob,
            negated: *negated,
            escape: escape.as_deref().map(|e| boxed(f, e)).transpose()?,
        },
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => ExprKind::Case {
            operand: operand.as_deref().map(|e| boxed(f, e)).transpose()?,
            whens: whens
                .iter()
                .map(|(w, t)| Ok((f(w)?, f(t)?)))
                .collect::<Result<_, CodegenError>>()?,
            else_: else_.as_deref().map(|e| boxed(f, e)).transpose()?,
        },
        ExprKind::Cast {
            expr: inner,
            type_name,
        } => ExprKind::Cast {
            expr: boxed(f, inner)?,
            type_name: type_name.clone(),
        },
        ExprKind::Collate {
            expr: inner,
            collation,
        } => ExprKind::Collate {
            expr: boxed(f, inner)?,
            collation: collation.clone(),
        },
        ExprKind::Paren(inner) => ExprKind::Paren(boxed(f, inner)?),
        ExprKind::InSubquery {
            expr: inner,
            subquery,
            negated,
        } => ExprKind::InSubquery {
            expr: boxed(f, inner)?,
            subquery: subquery.clone(),
            negated: *negated,
        },
        ExprKind::InSubqueryMulti {
            exprs,
            subquery,
            negated,
        } => ExprKind::InSubqueryMulti {
            exprs: exprs.iter().map(&mut *f).collect::<Result<_, _>>()?,
            subquery: subquery.clone(),
            negated: *negated,
        },
    }

match args {
                FunctionArgs::Star => FunctionArgs::Star,
                FunctionArgs::List(list) => {
                    FunctionArgs::List(list.iter().map(&mut *f).collect::<Result<_, _>>()?)
                }
            }

