            Some(NamedColumn::Offset(abs, _)) => Ok(JoinOrderTarget::Offset(abs)),
            Some(NamedColumn::Expr(named)) => column_or_expr_target(strip_collate(&named), scope),
            None => column_or_expr_target(expr, scope),
