                .as_ref()
                .map(|c| super::join_order::referenced_binding_indices(c, &bindings))
                .unwrap_or_default()
                .into_iter()
                .chain(std::iter::once(step.table))
                .filter_map(|i| pos_of.get(i).copied())
                .max()
                .ok_or_else(|| CodegenError::Internal {
                    reason: format!(
                        "join step for table {} references no known level",
                        step.table
