match resolve_joined_group_terms(select, &full_scope)? {
        Some(select) => {
            resolved = select;
            &resolved
        }
        None => select,
    }

match acc {
            Some(prev) => Expr {
                kind: ExprKind::Binary {
                    op: BinaryOp::And,
                    lhs: Box::new(prev),
                    rhs: Box::new(eq),
