                        alias: Some(alias), ..
                    } if alias.eq_ignore_ascii_case(name) => return Ok(Some(position)),
                    ResultColumn::Expr { .. } => position = position.saturating_add(1),
                    // A single-table SELECT: `*` is the whole schema.
                    ResultColumn::Star | ResultColumn::TableStar { .. } => {
                        position = position.saturating_add(star);
                    }
                }

match named_output(&term.expr, select, visible, schema.columns.len())? {
            Some(index) => index,
            None => {
                columns.push(ResultColumn::Expr {
                    expr: term.expr.clone(),
                    alias: None,
                });
                hidden = hidden.saturating_add(1);
                visible.saturating_add(hidden).saturating_sub(1)
            }
        }

match col {
            ResultColumn::Star | ResultColumn::TableStar { .. } => {
                for name in &schema.columns {
                    out.push(ResultColumnPlan::Column(name.clone()));
                }
            }
            ResultColumn::Expr { expr, .. } => out.push(ResultColumnPlan::Expr(expr.clone())),
        }

match col {
            ResultColumnPlan::Column(name) => schema
                .columns
                .iter()
                .position(|c| c == name)
                .and_then(|idx| schema.column_collations.get(idx).copied())
                .unwrap_or(Collation::Binary),
            ResultColumnPlan::Expr(expr) => {
                collation_of(expr).unwrap_or_else(|| match &order_by::strip_collate(expr).kind {
                    ExprKind::Column { name, .. } => schema
                        .columns
                        .iter()
                        .position(|c| c == name)
                        .and_then(|idx| schema.column_collations.get(idx).copied())
                        .unwrap_or(Collation::Binary),
                    _ => Collation::Binary,
                })
            }
        }

match col {
            ResultColumn::Star => {
                for (i, binding) in scope.tables.iter().enumerate() {
                    let suppressed = dedup_star.get(i);
                    for (idx, name) in binding.schema.columns.iter().enumerate() {
                        if !suppressed.is_some_and(|s| s.contains(&name.to_ascii_lowercase())) {
                            out.push(declared(binding, idx));
                        }
                    }
                }
            }
            ResultColumn::TableStar { table } => {
                if let Some(binding) = scope.tables.iter().find(|b| b.matches_qualifier(table)) {
                    out.extend((0..binding.schema.columns.len()).map(|idx| declared(binding, idx)));
                }
            }
            ResultColumn::Expr { expr, .. } => {
                out.push(expr_collation(scope, expr).unwrap_or(Collation::Binary));
            }
        }

match col {
            ResultColumnPlan::Column(name) => {
                let idx =
                    column_index(schema, name).ok_or_else(|| CodegenError::UnknownColumn {
                        name: (*name).to_string(),
                    })?;
                let r = reg.alloc();
                if pseudo && is_rowid_field(schema, idx) {
                    // `cursor` is a post-`ORDER BY` `OpenPseudo` re-read
                    // of an already-materialized record (see
                    // `compile_sorted_scan`'s pass 1), not a live table
                    // cursor — there is no rowid to fetch via
                    // `Opcode::Rowid` (it isn't a table cursor at all).
                    // Pass 1 built this record via `emit_column_read`
                    // against the *real* cursor, which already resolved
                    // the rowid alias into an ordinary field at this
                    // same position — so a plain `Column` read recovers
                    // it here.
                    em.emit(Instruction::new(
                        Opcode::Column,
                        cursor,
                        i32::try_from(idx).map_err(|_| CodegenError::Unsupported {
                            reason: format!("column index {idx} does not fit in a P2 operand"),
                        })?,
                        r,
                    ));
                } else {
                    // Must go through `emit_column_read`, not a bare
                    // `Column`: this is the `*` / `tbl.*` expansion path, and
                    // an `INTEGER PRIMARY KEY` column is a NULL placeholder
                    // in the record. Emitting `Column` here is why
                    // `SELECT * FROM t` answered NULL for the rowid alias
                    // while `SELECT id FROM t` (which routes through
                    // `compile_value`) answered correctly.
                    emit_column_read(em, schema, cursor, idx, r)?;
                }
                r
            }
            ResultColumnPlan::Expr(expr) => {
                // A bare `name`/`tbl.name` reference — e.g. plain
                // `SELECT id FROM t ORDER BY id` — compiles as an `Expr`
                // here, not the `Column` variant above (that one is
                // reserved for `*`/`tbl.*` expansion), so it needs the
                // same pseudo-cursor rowid-alias special case: `Rowid`
                // only works against a real table cursor, and `cursor`
                // here may be the post-`ORDER BY` pseudo cursor instead.
                // A compound expression that merely *references* the
                // rowid alias (`id + 1`) isn't covered by this — falls
                // through to `compile_value`, matching this crate's
                // existing register-reuse limitations for compound
                // result-column expressions.
                if let ExprKind::Column {
                    name,
                    table: None,
                    catalog: None,
                } = &expr.kind
                {
                    let pseudo_rowid_idx = pseudo
                        .then(|| column_index(schema, name))
                        .flatten()
                        .filter(|idx| is_rowid_field(schema, *idx));
                    if let Some(idx) = pseudo_rowid_idx {
                        let r = reg.alloc();
                        em.emit(Instruction::new(
                            Opcode::Column,
                            cursor,
                            i32::try_from(idx).map_err(|_| CodegenError::Unsupported {
                                reason: format!("column index {idx} does not fit in a P2 operand"),
                            })?,
                            r,
                        ));
                        r
                    } else {
                        compile_value(
                            em,
                            reg,
                            expr_scope.get_or_insert_with(|| {
                                record_scope(schema, cursor, pseudo, catalog)
                            }),
                            expr,
                        )?
                    }
                } else {
                    compile_value(
                        em,
                        reg,
                        expr_scope
                            .get_or_insert_with(|| record_scope(schema, cursor, pseudo, catalog)),
                        expr,
                    )?
                }
            }
        }

let ExprKind::Column {
                    name,
                    table: None,
                    catalog: None,
                } = &expr.kind

match parse_select(sql) {
            ParseOutcome::Accepted(s) => *s,
            other => panic!("expected {sql:?} to parse as a SELECT, got {other:?}"),
        }

match &expr.kind {
        ExprKind::Subquery(subquery) => {
            crate::codegen::row::subquery::subquery_hoistable(subquery, scope)
        }
        ExprKind::Unary { expr: e, .. }
        | ExprKind::Cast { expr: e, .. }
        | ExprKind::Collate { expr: e, .. }
        | ExprKind::Paren(e) => is_constant_operand(e, scope),
        ExprKind::Binary { lhs, rhs, .. } => {
            is_constant_operand(lhs, scope) && is_constant_operand(rhs, scope)
        }
        _ => is_supported_operand(expr),
    }

match &expr.kind {
        ExprKind::Literal(Literal::Integer(_) | Literal::Float(_)) => matches!(
            column_affinity,
            Affinity::Integer | Affinity::Real | Affinity::Numeric
        ),
        ExprKind::Literal(Literal::Str(_)) => matches!(column_affinity, Affinity::Text),
        // #695: no affinity ever converts a BLOB operand, on either side
        // of the comparison, so its raw bytes already compare correctly
        // (memcmp, after every other storage class) against whatever the
        // index holds.
        ExprKind::Literal(Literal::Blob(_)) => true,
        // #280: a bind parameter's storage class is genuinely unknowable
        // here, so it's passed through uncheckable, same accepted risk
        // as `Param` above. A subquery/arithmetic-composed constant
        // operand (only reachable via `is_constant_operand`, never
        // `is_supported_operand` alone) is the same kind of unknowable
        // at compile time -- its runtime value's storage class isn't
        // fixed by its shape the way a literal's is -- so it gets the
        // same pass-through rather than a coercion this file doesn't
        // implement yet (no VM opcode applies column affinity to an
        // already-computed register; see #280's follow-up).
        ExprKind::Param(_)
        | ExprKind::Subquery(_)
        | ExprKind::Unary { .. }
        | ExprKind::Cast { .. }
        | ExprKind::Collate { .. }
        | ExprKind::Paren(_)
        | ExprKind::Binary { .. } => true,
        _ => false,
    }

match col {
            ResultColumn::Expr {
                expr:
                    Expr {
                        kind:
                            ExprKind::Column {
                                table: None,
                                catalog: None,
                                name,
                            },
                        ..
                    },
                ..
            } => Some(name.as_str()),
            _ => None,
        }

match op {
        BinaryOp::Gt | BinaryOp::Ge | BinaryOp::Lt | BinaryOp::Le => {}
        _ => return None,
    }

match &expr.kind {
        ExprKind::Literal(Literal::Integer(i)) => Value::Integer(*i),
        ExprKind::Literal(Literal::Float(f)) => Value::Real(*f),
        ExprKind::Literal(Literal::Str(s)) => Value::Text(s.as_str().into()),
        ExprKind::Literal(Literal::Blob(b)) => Value::Blob(b.as_slice().into()),
        ExprKind::Paren(inner) => return bound_value(inner, affinity),
        ExprKind::Unary {
            op: UnaryOp::Minus,
            expr: inner,
        } => match &inner.kind {
            ExprKind::Literal(Literal::Integer(i)) => Value::Integer(i.checked_neg()?),
            ExprKind::Literal(Literal::Float(f)) => Value::Real(-f),
            _ => return None,
        },
        _ => return None,
    }

match &inner.kind {
            ExprKind::Literal(Literal::Integer(i)) => Value::Integer(i.checked_neg()?),
            ExprKind::Literal(Literal::Float(f)) => Value::Real(-f),
            _ => return None,
        }

match &where_expr.kind {
        ExprKind::Like {
            expr,
            pattern,
            glob,
            negated: false,
            escape: None,
        } => {
            let col_name = where_col(expr)?;
            let ExprKind::Literal(Literal::Str(pattern_str)) = &pattern.kind else {
                return None;
            };
            like_literal_prefix(pattern_str, *glob)?;
            let index_position = find_leading_index(schema, col_name)?;
            if column_affinity(schema, col_name) != Affinity::Text {
                return None;
            }
            Some(index_position)
        }
        ExprKind::In {
            expr,
            list,
            negated: false,
        } => {
            if list.is_empty() || !list.iter().all(is_supported_operand) {
                return None;
            }
            let col_name = where_col(expr)?;
            let index_position = find_leading_index(schema, col_name)?;
            let affinity = column_affinity(schema, col_name);
            if !list
                .iter()
                .all(|v| operand_matches_column_affinity(v, affinity))
            {
                return None;
            }
            Some(index_position)
        }
        _ => as_forward_comparison(where_expr).and_then(
            |(col_name, operand, inclusive, is_lower)| {
                if !is_constant_operand(operand, &scope) {
                    return None;
                }
                let index_position = find_leading_index(schema, col_name)?;
                let affinity = column_affinity(schema, col_name);
                if !operand_matches_column_affinity(operand, affinity) {
                    return None;
                }
                if !forward_seek_wins(
                    schema,
                    index_position,
                    operand,
                    inclusive,
                    is_lower,
                    covering,
                    stats,
                ) {
                    return None;
                }
                Some(index_position)
            },
        ),
    }

match &where_expr.kind {
        ExprKind::Like {
            expr,
            pattern,
            glob,
            negated: false,
            escape: None,
        } => {
            let col_name = where_col(expr)?;
            let ExprKind::Literal(Literal::Str(pattern_str)) = &pattern.kind else {
                return None;
            };
            like_literal_prefix(pattern_str, *glob)?;
            let index_position = find_leading_index(schema, col_name)?;
            let index = schema.indexes.get(index_position)?;
            if column_affinity(schema, col_name) != Affinity::Text {
                return None;
            }
            Some(format!(
                "SEARCH {table_display} USING INDEX {} ({col_name}>? AND {col_name}<?)",
                index.name
            ))
        }
        ExprKind::In {
            expr,
            list,
            negated: false,
        } => {
            if list.is_empty() || !list.iter().all(is_supported_operand) {
                return None;
            }
            let col_name = where_col(expr)?;
            let index_position = find_leading_index(schema, col_name)?;
            let index = schema.indexes.get(index_position)?;
            let affinity = column_affinity(schema, col_name);
            if !list
                .iter()
                .all(|v| operand_matches_column_affinity(v, affinity))
            {
                return None;
            }
            Some(format!(
                "SEARCH {table_display} USING INDEX {} ({col_name}=?)",
                index.name
            ))
        }
        _ => as_forward_comparison(where_expr).and_then(
            |(col_name, operand, inclusive, is_lower)| {
                if !is_constant_operand(operand, &scope) {
                    return None;
                }
                let index_position = find_leading_index(schema, col_name)?;
                let index = schema.indexes.get(index_position)?;
                let affinity = column_affinity(schema, col_name);
                if !operand_matches_column_affinity(operand, affinity) {
                    return None;
                }
                if !forward_seek_wins(
                    schema,
                    index_position,
                    operand,
                    inclusive,
                    is_lower,
                    covering,
                    stats,
                ) {
                    return None;
                }
                // Real sqlite3 collapses inclusive and exclusive into the
                // same `(col>?)` / `(col<?)` wording (see
                // `try_compile_forward_comparison_seek`'s doc) --
                // `inclusive` only matters to the compiled walk's
                // dup-skip / stop check, not to this report.
                let op = if is_lower { '>' } else { '<' };
                Some(format!(
                    "SEARCH {table_display} USING INDEX {} ({col_name}{op}?)",
                    index.name
                ))
            },
        ),
    }

match &where_expr.kind {
        ExprKind::Between {
            expr,
            lo,
            hi,
            negated: false,
        } => Some((expr, lo, hi, false)),
        ExprKind::Binary {
            op: BinaryOp::Eq,
            lhs,
            rhs,
        } => {
            let (col, lit) = if where_col(lhs).is_some() {
                (lhs.as_ref(), rhs.as_ref())
            } else if where_col(rhs).is_some() {
                (rhs.as_ref(), lhs.as_ref())
            } else {
                return None;
            };
            Some((col, lit, lit, true))
        }
        _ => None,
    }

match &expr.kind {
        ExprKind::Binary {
            op: BinaryOp::And,
            lhs,
            rhs,
        } => {
            let mut all = conjuncts(lhs);
            all.extend(conjuncts(rhs));
            all
        }
        _ => vec![expr],
    }

let ExprKind::Between {
            expr,
            lo,
            hi,
            negated: false,
        } = &conjunct.kind

match terms.get(i) {
        Some((_, _, _, Term::Lower(inclusive) | Term::Upper(inclusive))) => *inclusive,
        _ => true,
    }

match parse_select(sql) {
            ParseOutcome::Accepted(s) => *s,
            other => panic!("expected {sql:?} to parse as a SELECT, got {other:?}"),
        }

match parse_update(sql) {
            ParseOutcome::Accepted(u) => *u,
            other => panic!("expected {sql:?} to parse as an UPDATE, got {other:?}"),
        }

match parse_create_table(&schema.sql) {
        ParseOutcome::Accepted(create) => Arc::new(*create),
        ParseOutcome::Unsupported { message, .. } | ParseOutcome::Invalid { message, .. } => {
            return Err(CodegenError::Unsupported {
                reason: format!("could not recover constraints from schema DDL: {message}"),
            })
        }
    }

match source {
        ColumnSource::Expr(expr) => compile_value(
            em,
            reg,
            &crate::codegen::row::Scope::single(schema, cursor),
            expr,
        ),
        ColumnSource::Reg(src) => {
            let dest = reg.alloc();
            em.emit(Instruction::new(Opcode::Copy, *src, dest, 0));
            Ok(dest)
        }
    }

match &insert.columns {
        Some(names) => {
            let mut out = Vec::with_capacity(names.len());
            for name in names {
                let idx = column_index(schema, name)
                    .ok_or_else(|| CodegenError::UnknownColumn { name: name.clone() })?;
                out.push(idx);
            }
            out
        }
        None => (0..schema.columns.len()).collect(),
    }

match select_schemas {
            Some([single]) => select_result_column_count(select, single),
            Some(joined) if joined.len() > 1 => {
                let Some(from) = &select.from else {
                    return Err(CodegenError::NoFromClause);
                };
                let table_refs: Vec<&TableRef> = std::iter::once(&from.first)
                    .chain(from.joins.iter().map(|j| &j.table))
                    .collect();
                select_result_column_count_joined(select, joined, &table_refs)?
            }
            Some(_) | None => {
                return Err(CodegenError::Unsupported {
                    reason: "INSERT ... SELECT: the SELECT's FROM table schema(s) were not \
                             resolved"
                        .to_string(),
                })
            }
        }

match &insert.source {
        InsertSource::Values(rows) => {
            for values in rows {
                compile_row(
                    &mut em,
                    &mut reg,
                    schema,
                    &check_schema,
                    &plans,
                    &table_checks,
                    &target_columns,
                    |pos| values.get(pos).cloned().map(ColumnSource::Expr),
                    rowid_alias,
                    action,
                    &handlers,
                    &updates,
                    without_rowid_key.as_deref(),
                    is_autoincrement,
                )?;
            }
        }
        InsertSource::DefaultValues => {
            compile_row(
                &mut em,
                &mut reg,
                schema,
                &check_schema,
                &plans,
                &table_checks,
                &target_columns,
                |_pos| None,
                rowid_alias,
                action,
                &handlers,
                &updates,
                without_rowid_key.as_deref(),
                is_autoincrement,
            )?;
        }
        InsertSource::Select(select) => {
            // Re-checked (rather than trusted from the validation above)
            // so this arm never needs an infallible unwrap.
            let Some(select_schemas) = select_schemas else {
                return Err(CodegenError::Unsupported {
                    reason: "INSERT ... SELECT: the SELECT's FROM table schema(s) were not \
                             resolved"
                        .to_string(),
                });
            };
            // The select's source-table scan needs cursor numbers of its
            // own, distinct from this INSERT's target-table/index
            // cursors above — offset above the last index cursor
            // (`open_index_cursors` uses `FIRST_INDEX_CURSOR..
            // FIRST_INDEX_CURSOR+schema.indexes.len()`).
            let select_table_cursor =
                FIRST_INDEX_CURSOR.saturating_add(i32::try_from(schema.indexes.len()).unwrap_or(0));
            let end_label = em.new_label();
            let mut sink = |em: &mut Emitter, reg: &mut RegAlloc, first: i32, count: i32| {
                let count = usize::try_from(count).map_err(|_| CodegenError::Internal {
                    reason: format!("INSERT ... SELECT produced a negative column count {count}"),
                })?;
                compile_row(
                    em,
                    reg,
                    schema,
                    &check_schema,
                    &plans,
                    &table_checks,
                    &target_columns,
                    |pos| {
                        (pos < count)
                            .then(|| first.saturating_add(i32::try_from(pos).unwrap_or(i32::MAX)))
                            .map(ColumnSource::Reg)
                    },
                    rowid_alias,
                    action,
                    &handlers,
                    &updates,
                    without_rowid_key.as_deref(),
                    is_autoincrement,
                )
            };
            if select_schemas.len() > 1 {
                // #250: the SELECT's FROM clause has a JOIN — drive the
                // same nested-loop join scan `compile_select_joined`
                // uses, with cursor numbers offset above this INSERT's
                // own cursors (`compile_select_joined_scan` opens every
                // source-table cursor itself, unlike the single-table
                // `compile_select_scan` path below, which expects its
                // one cursor already open).
                // `select_schemas` doubles as the full catalog for a
                // subquery-in-FROM to resolve its own inner FROM table(s)
                // against (#257) — narrower than `compile_select_joined`'s
                // own full-database catalog, so `INSERT ... SELECT` with
                // both a JOIN and a FROM-subquery whose own table isn't
                // among the SELECT's joined tables isn't supported yet.
                compile_select_joined_scan(
                    &mut em,
                    &mut reg,
                    select,
                    select_schemas,
                    select_schemas,
                    select_table_cursor,
                    end_label,
                    &std::collections::HashMap::new(),
                    &mut sink,
                )?;
            } else {
                let Some(select_schema) = select_schemas.first() else {
                    return Err(CodegenError::Unsupported {
                        reason: "INSERT ... SELECT: the SELECT's FROM table schema was not \
                                 resolved"
                            .to_string(),
                    });
                };
                let select_cursors = ScanCursors {
                    table: select_table_cursor,
                    sort: select_table_cursor.saturating_add(1),
                    pseudo: select_table_cursor.saturating_add(2),
                    distinct: select_table_cursor.saturating_add(3),
                };
                let select_root_page = valid_table_root_page(select_schema)?;
                em.emit(Instruction::new(
                    Opcode::OpenRead,
                    select_cursors.table,
                    select_root_page,
                    0,
                ));
                compile_select_scan(
                    &mut em,
                    &mut reg,
                    select,
                    &std::rc::Rc::new(select_schema.clone()),
                    select_cursors,
                    end_label,
                    std::slice::from_ref(select_schema),
                    &crate::codegen::row::planner::Stats::default(),
                    &mut sink,
                )?;
            }
            em.place(end_label);
        }
    }

match constraint {
                ColumnConstraint::NotNull => plan.not_null = true,
                // NULL on the rowid-alias column means "assign a fresh
                // rowid", not a constraint violation, so its implicit
                // NOT NULL is deliberately not enforced.
                ColumnConstraint::PrimaryKey { .. } => {
                    if rowid_alias != Some(idx) {
                        plan.not_null = true;
                    }
                }
                ColumnConstraint::Default(
                    DefaultValue::Literal(expr) | DefaultValue::Paren(expr),
                ) => {
                    plan.default = Some(expr.clone());
                }
                ColumnConstraint::Check { expr, name, body } => plan
                    .checks
                    .push((expr.clone(), check_label(schema, name.as_deref(), *body))),
                ColumnConstraint::Unique | ColumnConstraint::Collate(_) => {}
            }

match rowid_alias {
            Some(idx) => {
                let explicit = value_source_at(idx).filter(
                    |source| !matches!(source, ColumnSource::Expr(e) if is_null_literal(e)),
                );
                match explicit {
                    Some(source) => {
                        let r = compile_column_source(em, reg, schema, TABLE_CURSOR, &source)?;
                        // `DO UPDATE` needs the new row's other values (for
                        // `excluded`), so its probe waits until they exist.
                        if let Some(Handler::Update(_)) = handlers.rowid {
                            rowid_probe_deferred = true;
                        } else {
                            let no_conflict = em.new_label();
                            let seek_addr =
                                em.emit(Instruction::new(Opcode::SeekRowid, TABLE_CURSOR, 0, r));
                            em.patch_p2(seek_addr, no_conflict);
                            let pk_action = if let Some(Handler::Skip) = handlers.rowid {
                                ConflictAction::Ignore
                            } else {
                                action
                            };
                            emit_pk_conflict(em, reg, pk_action, row_skip, schema, idx)?;
                            em.place(no_conflict);
                        }
                        r
                    }
                    None => {
                        let r = reg.alloc();
                        emit_new_rowid(em, r, schema, is_autoincrement);
                        r
                    }
                }
            }
            None => {
                let r = reg.alloc();
                emit_new_rowid(em, r, schema, is_autoincrement);
                r
            }
        }

match explicit {
                    Some(source) => {
                        let r = compile_column_source(em, reg, schema, TABLE_CURSOR, &source)?;
                        // `DO UPDATE` needs the new row's other values (for
                        // `excluded`), so its probe waits until they exist.
                        if let Some(Handler::Update(_)) = handlers.rowid {
                            rowid_probe_deferred = true;
                        } else {
                            let no_conflict = em.new_label();
                            let seek_addr =
                                em.emit(Instruction::new(Opcode::SeekRowid, TABLE_CURSOR, 0, r));
                            em.patch_p2(seek_addr, no_conflict);
                            let pk_action = if let Some(Handler::Skip) = handlers.rowid {
                                ConflictAction::Ignore
                            } else {
                                action
                            };
                            emit_pk_conflict(em, reg, pk_action, row_skip, schema, idx)?;
                            em.place(no_conflict);
                        }
                        r
                    }
                    None => {
                        let r = reg.alloc();
                        emit_new_rowid(em, r, schema, is_autoincrement);
                        r
                    }
                }

match &chosen {
