                let Some((n2, sz2)) = payload_size(z, j) else {
                    return add(j, 1);
                };
                let next = add(add(j, n2), sz2);
                if next > k {
                    return add(j, 1);
                }
                if x == J_OBJECT && cnt & 1 == 0 {
                    let t = at(z, j) & 0x0f;
                    if !(J_TEXT..=J_TEXTRAW).contains(&t) {
                        return add(j, 1);
                    }
                }
                let sub = validity_check(z, j, next, depth.saturating_add(1));
                if sub != 0 {
                    return sub;
                }
                cnt = add(cnt, 1);
                j = next;
            }
            if x == J_OBJECT && cnt & 1 != 0 {
                return add(j, 1);
            }
            0
        }
        _ => fail,
    }

