            }
            ParseError::Unexpected { message, span } => {
                write!(
                    f,
                    "unexpected token at {}:{}: {message}",
                    span.line, span.column
                )
            }
            ParseError::Unsupported { message, span } => {
                write!(f, "unsupported at {}:{}: {message}", span.line, span.column)
