        ExprKind::Column {
            table: None,
            catalog: None,
            name,
        } => Ok(name.clone()),
        ExprKind::Column {
            table: Some(table),
            catalog: None,
            name,
        } => Ok(format!("{table}.{name}")),
        ExprKind::Column {
            catalog: Some(_), ..
        } => Err(unsupported(expr.span, "catalog-qualified column".into())),
