        // before or regardless of alias resolution), but walked here too
        // so a `Select` this module validates is never left half-resolved.
        ExprKind::Between {
            expr: inner,
            lo,
            hi,
            ..
        } => {
            resolve_expr_aliases(inner, aliases);
            resolve_expr_aliases(lo, aliases);
            resolve_expr_aliases(hi, aliases);
        }
        ExprKind::In {
            expr: inner, list, ..
        } => {
            resolve_expr_aliases(inner, aliases);
            for e in list {
                resolve_expr_aliases(e, aliases);
            }
        }
        ExprKind::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            resolve_expr_aliases(inner, aliases);
            resolve_expr_aliases(pattern, aliases);
            if let Some(e) = escape {
                resolve_expr_aliases(e, aliases);
            }
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            if let Some(o) = operand {
                resolve_expr_aliases(o, aliases);
            }
            for (cond, result) in whens {
                resolve_expr_aliases(cond, aliases);
                resolve_expr_aliases(result, aliases);
            }
            if let Some(e) = else_ {
                resolve_expr_aliases(e, aliases);
            }
        }
        ExprKind::Cast { expr: inner, .. } | ExprKind::Collate { expr: inner, .. } => {
            resolve_expr_aliases(inner, aliases)
        }
        ExprKind::Literal(_)
        | ExprKind::Param(_)
        | ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubqueryMulti { .. } => {}
    }

match &mut expr.kind {
        ExprKind::FunctionCall { args, tail, .. } => {
            if let FunctionArgs::List(list) = args {
                for e in list {
                    lower_in_between_expr(e)?;
                }
            }
            if let Some(tail) = tail {
                if let Some(filter) = &mut tail.filter {
                    lower_in_between_expr(filter)?;
                }
                if let Some(window_def) = &mut tail.over {
                    for e in &mut window_def.partition_by {
                        lower_in_between_expr(e)?;
                    }
                    for term in &mut window_def.order_by {
                        lower_in_between_expr(&mut term.expr)?;
                    }
                }
            }
        }
        ExprKind::Unary { expr: inner, .. }
        | ExprKind::IsNull { expr: inner, .. }
        | ExprKind::Paren(inner)
        | ExprKind::InSubquery { expr: inner, .. }
        | ExprKind::Cast { expr: inner, .. }
        | ExprKind::Collate { expr: inner, .. } => lower_in_between_expr(inner)?,
        ExprKind::Binary { lhs, rhs, .. } | ExprKind::Is { lhs, rhs, .. } => {
            lower_in_between_expr(lhs)?;
            lower_in_between_expr(rhs)?;
        }
        ExprKind::Between {
            expr: inner,
            lo,
            hi,
            ..
        } => {
            lower_in_between_expr(inner)?;
            lower_in_between_expr(lo)?;
            lower_in_between_expr(hi)?;
        }
        ExprKind::In {
            expr: inner, list, ..
        } => {
            lower_in_between_expr(inner)?;
            for e in list {
                lower_in_between_expr(e)?;
            }
        }
        ExprKind::Like {
            expr: inner,
            pattern,
            escape,
            ..
        } => {
            lower_in_between_expr(inner)?;
            lower_in_between_expr(pattern)?;
            if let Some(e) = escape {
                lower_in_between_expr(e)?;
            }
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
