                lower_in_between_expr(o)?;
            }
            for (cond, result) in whens {
                lower_in_between_expr(cond)?;
                lower_in_between_expr(result)?;
            }
            if let Some(e) = else_ {
                lower_in_between_expr(e)?;
            }
        }
        ExprKind::Column { .. }
        | ExprKind::Literal(_)
        | ExprKind::Param(_)
        | ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubqueryMulti { .. } => {}
    }

let ExprKind::In {
            expr: subject,
            list,
            negated,
        } = kind

let ExprKind::Between {
            expr: subject,
            lo,
            hi,
            negated,
        } = kind

let ExprKind::Case {
            operand,
            whens,
            else_,
        } = kind

let ExprKind::FunctionCall {
        name,
        args: FunctionArgs::List(list),
        tail: None,
        ..
    } = &mut expr.kind

match &operand {
            Some(operand) => AstExpr {
                span: cond.span,
                kind: ExprKind::Binary {
                    op: AstBinOp::Eq,
                    lhs: Box::new(operand.clone()),
                    rhs: Box::new(cond),
                },
            },
            None => cond,
        }

match &expr.kind {
        ExprKind::Binary {
            op: AstBinOp::Eq,
            lhs,
            rhs,
        } => Ok((column_name(lhs)?, column_name(rhs)?)),
        _ => Err(unsupported(expr.span, "JOIN ON must be col = col".into())),
    }

match args {
        FunctionArgs::Star => {
            if !name.eq_ignore_ascii_case("COUNT") {
                return Err(unsupported(span, "only COUNT supports (*)".into()));
            }
            Ok(())
        }
        FunctionArgs::List(list) => match list.as_slice() {
            [one] => validate_aggregate_arg(one),
            _ => Err(unsupported(
                span,
                "an aggregate takes exactly one column or *".into(),
            )),
        },
    }

match list.as_slice() {
            [one] => validate_aggregate_arg(one),
            _ => Err(unsupported(
                span,
                "an aggregate takes exactly one column or *".into(),
            )),
        }

match &expr.kind {
        ExprKind::Column { .. } => column_name(expr).map(|_| ()),
        ExprKind::FunctionCall { name, .. } if is_known_agg_name(name) => Err(unsupported(
            expr.span,
            format!("nested aggregate: {name} inside an aggregate argument"),
        )),
        _ => validate_expr(&mut expr.clone(), false),
    }

match (&shape, args) {
        (WindowShape::Niladic, FunctionArgs::List(list)) if list.is_empty() => {}
        (WindowShape::Niladic, _) => {
            return Err(unsupported(span, format!("{name} takes no arguments")))
        }
        (WindowShape::CountLike, FunctionArgs::Star) => {}
        (_, FunctionArgs::Star) => return Err(unsupported(span, "only COUNT supports (*)".into())),
        (WindowShape::LagLead, FunctionArgs::List(list)) => match list.as_slice() {
            [one] => {
                column_name(one)?;
            }
            [one, offset_expr] => {
                column_name(one)?;
                if !matches!(offset_expr.kind, ExprKind::Literal(AstLiteral::Integer(_))) {
                    return Err(unsupported(offset_expr.span, "non-integer offset".into()));
                }
            }
            _ => return Err(unsupported(span, format!("{name} takes 1 or 2 arguments"))),
        },
        (_, FunctionArgs::List(list)) => match list.as_slice() {
            [one] => {
                column_name(one)?;
            }
            _ => {
                return Err(unsupported(
                    span,
                    "a window function takes exactly one column or *".into(),
                ))
            }
        },
    }

match list.as_slice() {
            [one] => {
                column_name(one)?;
            }
            [one, offset_expr] => {
                column_name(one)?;
                if !matches!(offset_expr.kind, ExprKind::Literal(AstLiteral::Integer(_))) {
                    return Err(unsupported(offset_expr.span, "non-integer offset".into()));
                }
            }
            _ => return Err(unsupported(span, format!("{name} takes 1 or 2 arguments"))),
        }

match list.as_slice() {
            [one] => {
                column_name(one)?;
            }
            _ => {
                return Err(unsupported(
                    span,
                    "a window function takes exactly one column or *".into(),
                ))
            }
        }

match col {
        ResultColumn::Star | ResultColumn::TableStar { .. } => Ok(()),
        // `alias` (#307) only renames this column's output header; it
        // doesn't change how `expr` itself validates below.
        ResultColumn::Expr { expr, alias: _ } => match &expr.kind {
            ExprKind::Column { .. } => column_name(expr).map(|_| ()),
            // #788: a numeric scalar takes any expression, aggregates
            // included, so it validates as one (the strict
            // column-or-literal check below is for the extract functions).
            ExprKind::FunctionCall {
                name,
                args,
                tail: None,
                ..
            } if crate::functions::takes_any_expression(name, arg_count(args)) => {
                validate_expr(expr, true)
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                tail,
            } if matches!(tail.as_deref(), Some(t) if t.over.is_some()) => {
                if *distinct {
                    return Err(unsupported(
                        expr.span,
                        "DISTINCT inside a window function".into(),
                    ));
                }
                // The guard above makes the `else` unreachable; a typed
                // error keeps it total without an `expect` (db-core#231).
                let Some(window_def) = tail.as_deref().and_then(|t| t.over.as_ref()) else {
                    return Err(unsupported(
                        expr.span,
                        "window function call without an OVER clause".into(),
                    ));
                };
                validate_window_call(expr.span, name, args, window_def)
            }
            // A range-vector call (#308, ADR 0018 §Opcodes): stream-only,
            // like `SINCE`/`UNTIL` -- `codegen::batch`/`codegen::row`
            // reject a `Select` whose only column carries a `RANGE` tail
            // just as they reject one carrying `Select::scope`, so this
            // validator only needs to accept the shape, not decide which
            // engine may run it.
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                tail,
            } if matches!(tail.as_deref(), Some(t) if t.range.is_some()) => {
                if *distinct {
                    return Err(unsupported(
                        expr.span,
                        "DISTINCT inside a range-vector call".into(),
                    ));
                }
                // Range-vector functions (`count_over_time`, ...) only
                // exist behind `vm-stream` -- a consumer built without
                // it (column-rs's `vm-batch`-only build, per this
                // Cargo.toml's own feature-isolation comment) can't
                // execute one regardless of its name, so reject
                // unconditionally rather than pulling `vm::stream` in
                // just to validate a name it will never run. Each `cfg`
                // arm below produces the whole match arm's result, so
                // exactly one compiles -- no unreachable-code fallthrough.
                #[cfg(not(feature = "vm-stream"))]
                {
                    Err(unsupported(
                        expr.span,
                        format!("range-vector function {name}: requires the vm-stream feature"),
                    ))
                }
                #[cfg(feature = "vm-stream")]
                {
                    if crate::vm::stream::RangeAggFunc::from_name(name).is_none() {
                        return Err(unsupported(
                            expr.span,
                            format!("unknown range-vector function {name}"),
                        ));
                    }
                    match args {
                        FunctionArgs::Star => Ok(()),
                        FunctionArgs::List(list) => match list.as_slice() {
                            [] => Ok(()),
                            [arg] => match &arg.kind {
                                ExprKind::Column { .. } => column_name(arg).map(|_| ()),
                                _ => Err(unsupported(
                                    arg.span,
                                    format!("{name}(...): argument must be a bare column"),
                                )),
                            },
                            _ => Err(unsupported(
                                expr.span,
                                format!("{name}(...) takes at most one argument"),
                            )),
                        },
                    }
                }
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                ..
            } if is_known_agg_name(name) => {
                validate_distinct(expr.span, name, *distinct, args)?;
                validate_aggregate_call(expr.span, name, args)
            }
            // A scalar call (#307) is validated like any other expression,
            // its arguments included: `l[-1]`, `f(g(x))` (#826).
            _ => validate_expr(expr, true),
        },
    }

match &expr.kind {
            ExprKind::Column { .. } => column_name(expr).map(|_| ()),
            // #788: a numeric scalar takes any expression, aggregates
            // included, so it validates as one (the strict
            // column-or-literal check below is for the extract functions).
            ExprKind::FunctionCall {
                name,
                args,
                tail: None,
                ..
            } if crate::functions::takes_any_expression(name, arg_count(args)) => {
                validate_expr(expr, true)
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                tail,
            } if matches!(tail.as_deref(), Some(t) if t.over.is_some()) => {
                if *distinct {
                    return Err(unsupported(
                        expr.span,
                        "DISTINCT inside a window function".into(),
                    ));
                }
                // The guard above makes the `else` unreachable; a typed
                // error keeps it total without an `expect` (db-core#231).
                let Some(window_def) = tail.as_deref().and_then(|t| t.over.as_ref()) else {
                    return Err(unsupported(
                        expr.span,
                        "window function call without an OVER clause".into(),
                    ));
                };
                validate_window_call(expr.span, name, args, window_def)
            }
            // A range-vector call (#308, ADR 0018 §Opcodes): stream-only,
            // like `SINCE`/`UNTIL` -- `codegen::batch`/`codegen::row`
            // reject a `Select` whose only column carries a `RANGE` tail
            // just as they reject one carrying `Select::scope`, so this
            // validator only needs to accept the shape, not decide which
            // engine may run it.
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                tail,
            } if matches!(tail.as_deref(), Some(t) if t.range.is_some()) => {
                if *distinct {
                    return Err(unsupported(
                        expr.span,
                        "DISTINCT inside a range-vector call".into(),
                    ));
                }
                // Range-vector functions (`count_over_time`, ...) only
                // exist behind `vm-stream` -- a consumer built without
                // it (column-rs's `vm-batch`-only build, per this
                // Cargo.toml's own feature-isolation comment) can't
                // execute one regardless of its name, so reject
                // unconditionally rather than pulling `vm::stream` in
                // just to validate a name it will never run. Each `cfg`
                // arm below produces the whole match arm's result, so
                // exactly one compiles -- no unreachable-code fallthrough.
                #[cfg(not(feature = "vm-stream"))]
                {
                    Err(unsupported(
                        expr.span,
                        format!("range-vector function {name}: requires the vm-stream feature"),
                    ))
                }
                #[cfg(feature = "vm-stream")]
                {
                    if crate::vm::stream::RangeAggFunc::from_name(name).is_none() {
                        return Err(unsupported(
                            expr.span,
                            format!("unknown range-vector function {name}"),
                        ));
                    }
                    match args {
                        FunctionArgs::Star => Ok(()),
                        FunctionArgs::List(list) => match list.as_slice() {
                            [] => Ok(()),
                            [arg] => match &arg.kind {
                                ExprKind::Column { .. } => column_name(arg).map(|_| ()),
                                _ => Err(unsupported(
                                    arg.span,
                                    format!("{name}(...): argument must be a bare column"),
                                )),
                            },
                            _ => Err(unsupported(
                                expr.span,
                                format!("{name}(...) takes at most one argument"),
                            )),
                        },
                    }
                }
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                ..
            } if is_known_agg_name(name) => {
                validate_distinct(expr.span, name, *distinct, args)?;
                validate_aggregate_call(expr.span, name, args)
            }
            // A scalar call (#307) is validated like any other expression,
            // its arguments included: `l[-1]`, `f(g(x))` (#826).
            _ => validate_expr(expr, true),
        }

match args {
                        FunctionArgs::Star => Ok(()),
                        FunctionArgs::List(list) => match list.as_slice() {
                            [] => Ok(()),
                            [arg] => match &arg.kind {
                                ExprKind::Column { .. } => column_name(arg).map(|_| ()),
                                _ => Err(unsupported(
                                    arg.span,
                                    format!("{name}(...): argument must be a bare column"),
                                )),
                            },
                            _ => Err(unsupported(
                                expr.span,
                                format!("{name}(...) takes at most one argument"),
                            )),
                        },
                    }

match list.as_slice() {
                            [] => Ok(()),
                            [arg] => match &arg.kind {
                                ExprKind::Column { .. } => column_name(arg).map(|_| ()),
                                _ => Err(unsupported(
                                    arg.span,
                                    format!("{name}(...): argument must be a bare column"),
                                )),
                            },
                            _ => Err(unsupported(
                                expr.span,
                                format!("{name}(...) takes at most one argument"),
                            )),
                        }

match &arg.kind {
                                ExprKind::Column { .. } => column_name(arg).map(|_| ()),
                                _ => Err(unsupported(
                                    arg.span,
                                    format!("{name}(...): argument must be a bare column"),
                                )),
                            }

match &expr.kind {
        ExprKind::FunctionCall { name, .. } if is_known_agg_name(name) => true,
        ExprKind::FunctionCall {
            args: FunctionArgs::List(list),
            ..
        } => list.iter().any(expr_contains_agg),
        ExprKind::Binary { lhs, rhs, .. }
        | ExprKind::Is { lhs, rhs, .. }
        | ExprKind::Like {
            expr: lhs,
            pattern: rhs,
            ..
        } => expr_contains_agg(lhs) || expr_contains_agg(rhs),
        ExprKind::Unary { expr: inner, .. }
        | ExprKind::IsNull { expr: inner, .. }
        | ExprKind::Paren(inner) => expr_contains_agg(inner),
        _ => false,
    }

match &expr.kind {
        ExprKind::Column { .. } => {
            let name = column_name(expr)?;
            (!group_by.contains(&name)).then_some(name)
        }
        ExprKind::FunctionCall { name, .. } if is_known_agg_name(name) => None,
        ExprKind::FunctionCall {
            args: FunctionArgs::List(list),
            ..
        } => {
            for arg in list {
                if let Some(name) = ungrouped_column(arg, group_by)? {
                    return Ok(Some(name));
                }
            }
            None
        }
        ExprKind::Binary { lhs, rhs, .. }
        | ExprKind::Is { lhs, rhs, .. }
        | ExprKind::Like {
            expr: lhs,
            pattern: rhs,
            ..
        } => match ungrouped_column(lhs, group_by)? {
            Some(name) => Some(name),
            None => ungrouped_column(rhs, group_by)?,
        },
        ExprKind::Unary { expr: inner, .. }
        | ExprKind::IsNull { expr: inner, .. }
        | ExprKind::Paren(inner) => ungrouped_column(inner, group_by)?,
        _ => None,
    }

match ungrouped_column(lhs, group_by)? {
            Some(name) => Some(name),
            None => ungrouped_column(rhs, group_by)?,
        }

match col {
        ResultColumn::Star | ResultColumn::TableStar { .. } => ItemKind::Star,
        ResultColumn::Expr { expr, .. } => match &expr.kind {
            // A catalog-qualified column is rejected here with its span,
            // not folded into an empty name that the GROUP BY check would
            // then compare against (db-core#232).
            ExprKind::Column { .. } => {
                column_name(expr)?;
                ItemKind::Column
            }
            ExprKind::FunctionCall { tail, .. } if matches!(tail.as_deref(), Some(t) if t.over.is_some()) => {
                ItemKind::Window
            }
            // A scalar call (#307) is a computed expression, not an
            // aggregate -- `is_known_agg_name` is the real distinction
            // `validate_result_column` already draws for the same call.
            ExprKind::FunctionCall { name, .. } if is_known_agg_name(name) => ItemKind::Agg,
            _ if expr_contains_agg(expr) => ItemKind::Agg,
            _ => ItemKind::Expr,
        },
    }

match &expr.kind {
            // A catalog-qualified column is rejected here with its span,
            // not folded into an empty name that the GROUP BY check would
            // then compare against (db-core#232).
            ExprKind::Column { .. } => {
                column_name(expr)?;
                ItemKind::Column
            }
            ExprKind::FunctionCall { tail, .. } if matches!(tail.as_deref(), Some(t) if t.over.is_some()) => {
                ItemKind::Window
            }
            // A scalar call (#307) is a computed expression, not an
            // aggregate -- `is_known_agg_name` is the real distinction
            // `validate_result_column` already draws for the same call.
            ExprKind::FunctionCall { name, .. } if is_known_agg_name(name) => ItemKind::Agg,
            _ if expr_contains_agg(expr) => ItemKind::Agg,
            _ => ItemKind::Expr,
        }

match &mut expr.kind {
        ExprKind::Literal(_) => Ok(()),
        ExprKind::Column {
            catalog: Some(_), ..
        } => Err(unsupported(expr.span, "catalog-qualified column".into())),
        ExprKind::Column { .. } => Ok(()),
        ExprKind::Unary {
            op: UnaryOp::Not | UnaryOp::Minus | UnaryOp::Plus,
            expr: inner,
        } => validate_expr(inner, allow_agg),
        ExprKind::Unary { op, .. } => Err(unsupported(expr.span, format!("unary operator {op:?}"))),
        // `expr IS [NOT] NULL` may parse as `Is{lhs, rhs: NULL literal,
        // negated}` instead of the dedicated `IsNull` node.
        ExprKind::Is { lhs, rhs, .. }
            if matches!(rhs.kind, ExprKind::Literal(AstLiteral::Null)) =>
        {
            validate_expr(lhs, allow_agg)
        }
        ExprKind::Binary { op, lhs, rhs } => {
            ast_binop_allowed(*op, expr.span)?;
            validate_expr(lhs, allow_agg)?;
            validate_expr(rhs, allow_agg)
        }
        ExprKind::IsNull { expr: inner, .. } => validate_expr(inner, allow_agg),
        ExprKind::Like {
            expr: inner,
            pattern,
            escape: None,
            ..
        } => {
            validate_expr(inner, allow_agg)?;
            validate_expr(pattern, allow_agg)
        }
        ExprKind::Like {
            escape: Some(_), ..
        } => Err(unsupported(expr.span, "LIKE ... ESCAPE".into())),
        ExprKind::Paren(inner) => validate_expr(inner, allow_agg),
        ExprKind::InSubquery {
            expr: inner,
            subquery,
            negated: false,
        } => {
            // The planner compiles `x IN (SELECT ...)` as a per-row semi-
            // join; an aggregate on its left would be evaluated per row
            // and never merged.
            validate_expr(inner, false)?;
            validate_select(subquery)
        }
        ExprKind::InSubquery { negated: true, .. } => {
            Err(unsupported(expr.span, "NOT IN (SELECT ...)".into()))
        }
        ExprKind::Exists { subquery, .. } => validate_select(subquery),
        // #496: an aggregate composed with arithmetic (`SUM(x) * 2`,
        // `SUM(x) + SUM(y)`, `SUM(x) / COUNT(*)`) is only valid where an
        // aggregate itself is valid (a `SELECT`-list expression), not
        // inside `WHERE` or another aggregate's argument -- `allow_agg`
        // distinguishes the two, both of which reach `validate_expr`.
        ExprKind::FunctionCall {
            name,
            distinct,
            args,
            tail: None,
        } if allow_agg && is_known_agg_name(name) => {
            if *distinct {
                return Err(unsupported(
                    expr.span,
                    "DISTINCT inside an aggregate".into(),
                ));
            }
            validate_aggregate_call(expr.span, name, args)
        }
        ExprKind::FunctionCall { name, .. } if is_known_agg_name(name) => Err(unsupported(
            expr.span,
            format!("aggregate function {name} not allowed here"),
        )),
        // #827: a list literal's elements. db-core's lists hold strings,
        // so `[1, 2]` is refused rather than turned into `['1', '2']`
        // (which would then sort `'10'` before `'9'`).
        ExprKind::FunctionCall {
            name,
            args: FunctionArgs::List(args),
            tail: None,
            ..
        } if name.eq_ignore_ascii_case("list_value") => args
            .iter()
            .find(|a| {
                !matches!(
                    a.kind,
                    ExprKind::Literal(AstLiteral::Str(_) | AstLiteral::Null)
                )
            })
            .map_or(Ok(()), |a| {
                Err(unsupported(
                    a.span,
                    "a list holds string literals or NULL (db-core lists are lists of strings)"
                        .into(),
                ))
            }),
        // A scalar function (json_extract, the map functions of #621...)
        // anywhere an expression is: `WHERE map_get_ci(h, 'host') = 'x'`.
        ExprKind::FunctionCall {
            name,
            distinct: false,
            args: FunctionArgs::List(args),
            tail: None,
        } if is_known_scalar_function(name, args.len()) => {
            check_literal_args(name, args)?;
            // Only a numeric or branching scalar may wrap an aggregate
            // (#788, #725).
            let allow = allow_agg && crate::functions::takes_any_expression(name, args.len());
            args.iter_mut().try_for_each(|a| validate_expr(a, allow))
        }
        other => Err(unsupported(
            expr.span,
            format!("unsupported expression form {other:?}"),
        )),
    }

match &mut from_clause.first.kind {
            TableRefKind::Name(name) => name.clone(),
            TableRefKind::Subquery(subselect) => {
                let Some(alias) = from_clause.first.alias.clone() else {
                    return Err(unsupported(
                        from_clause.first.span,
                        "a subquery in FROM requires an alias".into(),
                    ));
                };
                validate_select(subselect)?;
                alias
            }
            TableRefKind::Unnest { .. } => {
                return Err(unsupported(
                    from_clause.first.span,
                    "UNNEST needs a table before it in FROM".into(),
                ))
            }
        }

match &mut j.table.kind {
                TableRefKind::Name(table) => table.clone(),
                TableRefKind::Subquery(_) => {
                    return Err(unsupported(j.table.span, "subquery in JOIN".into()))
                }
                TableRefKind::Unnest { expr, column } => {
                    unnests = unnests.saturating_add(1);
                    if unnests > 1 {
                        return Err(unsupported(j.table.span, "more than one UNNEST".into()));
                    }
                    if j.op != JoinOp::Cross || j.constraint.is_some() {
                        return Err(unsupported(
                            j.table.span,
                            "UNNEST takes a comma or CROSS JOIN, no ON".into(),
                        ));
                    }
                    if matches!(expr.kind, ExprKind::Literal(_)) {
                        return Err(unsupported(
                            j.table.span,
                            "UNNEST of a literal: it expands a list column".into(),
                        ));
                    }
                    unnest_alias.clone_from(&j.table.alias);
                    if column.is_none() {
                        *column = Some(UNNEST_COLUMN.to_string());
                    }
                    continue;
                }
            }

match &j.constraint {
                Some(JoinConstraint::On(expr)) => {
                    extract_equi_join(expr)?;
                }
                // `USING (a, b)` hashes on `a` and filters on the rest after
                // the join (#771), which an outer join cannot do: its
                // unmatched rows would be dropped.
                Some(JoinConstraint::Using(columns))
                    if matches!((j.op == JoinOp::Inner, columns.len()), (false, 2..)) =>
                {
                    return Err(unsupported(
                        j.table.span,
                        "USING with several columns is supported on an INNER JOIN only".into(),
                    ))
                }
                Some(JoinConstraint::Using(_)) => {}
                None if j.op == JoinOp::Cross => {}
                None => return Err(unsupported(j.table.span, "join without ON".into())),
            }

