match outcome {
            ParseOutcome::Accepted(_) => {}
            other => panic!("expected accepted for {src:?}, got {other:?}"),
        }

match outcome {
            ParseOutcome::Unsupported { .. } => {}
            other => panic!("expected unsupported for {src:?}, got {other:?}"),
        }

match outcome {
            ParseOutcome::Invalid { .. } => {}
            other => panic!("expected invalid for {src:?}, got {other:?}"),
        }

match parse_explain("EXPLAIN UPDATE t SET a = 1 WHERE b = 2") {
            ParseOutcome::Accepted(explain) => {
                assert!(!explain.query_plan);
                assert!(matches!(explain.body, ExplainBody::Update(_)));
            }
            other => panic!("expected accepted, got {other:?}"),
        }

match parse_explain("EXPLAIN DELETE FROM t WHERE b = 2") {
            ParseOutcome::Accepted(explain) => {
                assert!(!explain.query_plan);
                assert!(matches!(explain.body, ExplainBody::Delete(_)));
            }
            other => panic!("expected accepted, got {other:?}"),
        }

match &self.peek().kind {
            TokenKind::Eof => Ok(()),
            TokenKind::Keyword(Keyword::UNION)
            | TokenKind::Keyword(Keyword::INTERSECT)
            | TokenKind::Keyword(Keyword::EXCEPT) => {
                self.unsupported("compound SELECT (UNION/INTERSECT/EXCEPT) not yet supported")
            }
            other => {
                let tok = other.clone();
                Err(ParseFail::Invalid {
                    message: format!("unexpected trailing token {tok:?}"),
                    span: self.peek().span,
                })
            }
        }

match self.peek().kind.clone() {
            // SQLite accepts a string literal wherever an identifier is
            // required (`CREATE TABLE 't'(...)`, as FTS5 writes its shadow
            // tables) -- "a string constant used as an identifier" in its
            // keyword docs. Only positions that *require* a name reach here,
            // so expression-position strings still parse as literals.
            TokenKind::Identifier(name) | TokenKind::String(name) => {
                let span = self.advance_span();
                Ok((name, span))
            }
            _ => {
                let tok = self.peek().clone();
                Err(ParseFail::Invalid {
                    message: format!("expected identifier, found {:?}", tok.kind),
                    span: tok.span,
                })
            }
        }

match tok.kind {
            TokenKind::Integer(v) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Integer(v)),
                    span: tok.span,
                })
            }
            TokenKind::Float(v) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Float(v)),
                    span: tok.span,
                })
            }
            TokenKind::String(s) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Str(s)),
                    span: tok.span,
                })
            }
            TokenKind::Blob(b) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Blob(*b)),
                    span: tok.span,
                })
            }
            TokenKind::Null => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Null),
                    span: tok.span,
                })
            }
            TokenKind::True => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::True),
                    span: tok.span,
                })
            }
            TokenKind::False => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::False),
                    span: tok.span,
                })
            }
            TokenKind::Keyword(Keyword::CURRENT_TIME)
            | TokenKind::Keyword(Keyword::CURRENT_DATE)
            | TokenKind::Keyword(Keyword::CURRENT_TIMESTAMP) => {
                self.unsupported("CURRENT_TIME/CURRENT_DATE/CURRENT_TIMESTAMP not yet supported")
            }
            _ => self.invalid("expected literal value after DEFAULT"),
        }

match self.peek().kind.clone() {
            TokenKind::Identifier(text) if text.eq_ignore_ascii_case("wal") => {
                let span = self.advance_span();
                Ok((PragmaJournalMode::Wal, span))
            }
            TokenKind::Keyword(Keyword::DELETE) => {
                let span = self.advance_span();
                Ok((PragmaJournalMode::Delete, span))
            }
            _ => self.unsupported("unsupported journal_mode value (only WAL/DELETE are supported)"),
        }

match self.peek().kind.clone() {
            TokenKind::Identifier(text) if text.eq_ignore_ascii_case("off") => {
                Ok((PragmaSynchronous::Off, self.advance_span()))
            }
            TokenKind::Identifier(text) if text.eq_ignore_ascii_case("normal") => {
                Ok((PragmaSynchronous::Normal, self.advance_span()))
            }
            // `FULL` is a reserved keyword (used in `FULL [OUTER] JOIN`),
            // never tokenized as a plain identifier -- same reason
            // `journal_mode`'s `DELETE` value needs its own keyword
            // match arm rather than falling out of `identifier()`.
            TokenKind::Keyword(Keyword::FULL) => Ok((PragmaSynchronous::Full, self.advance_span())),
            TokenKind::Integer(0) => Ok((PragmaSynchronous::Off, self.advance_span())),
            TokenKind::Integer(1) => Ok((PragmaSynchronous::Normal, self.advance_span())),
            TokenKind::Integer(2) => Ok((PragmaSynchronous::Full, self.advance_span())),
            _ => self.unsupported(
                "unsupported synchronous value (only OFF/NORMAL/FULL/0/1/2 are supported)",
            ),
        }

match self.peek().kind.clone() {
            TokenKind::Integer(n) if n >= 0 => {
                self.advance();
                u64::try_from(n).unwrap_or(0)
            }
            other => {
                return Err(ParseFail::Invalid {
                    message: format!("expected a non-negative integer, found {other:?}"),
                    span: start,
                });
            }
        }

match &unit_tok.kind {
            TokenKind::Identifier(name) => match_scope_unit(name).ok_or_else(|| {
                ParseFail::Invalid {
                    message: format!(
                        "unknown SINCE/UNTIL unit '{name}' (expected s/sec/seconds, m/min/minutes, h/hour/hours, d/day/days, lines, or b/kb/mb/gb/bytes)"
                    ),
                    span: unit_tok.span,
                }
            })?,
            other => {
                return Err(ParseFail::Invalid {
                    message: format!("expected a SINCE/UNTIL unit, found {other:?}"),
                    span: unit_tok.span,
                });
            }
        }

match self.peek().kind.clone() {
                TokenKind::Eq => {
                    self.advance();
                    let rhs = self.binary_expr(1)?;
                    bin(BinaryOp::Eq, lhs, rhs)
                }
                TokenKind::Ne => {
                    self.advance();
                    let rhs = self.binary_expr(1)?;
                    bin(BinaryOp::Ne, lhs, rhs)
                }
                TokenKind::Keyword(Keyword::IS) => {
                    self.advance();
                    let negated = self.eat_kw(Keyword::NOT);
                    let rhs = self.binary_expr(1)?;
                    let span = join_span(lhs.span, rhs.span);
                    Expr {
                        kind: ExprKind::Is {
                            lhs: Box::new(lhs),
                            rhs: Box::new(rhs),
                            negated,
                        },
                        span,
                    }
                }
                TokenKind::Keyword(Keyword::ISNULL) => {
                    let end = self.advance_span();
                    let span = join_span(lhs.span, end);
                    Expr {
                        kind: ExprKind::IsNull {
                            expr: Box::new(lhs),
                            negated: false,
                        },
                        span,
                    }
                }
                TokenKind::Keyword(Keyword::NOTNULL) => {
                    let end = self.advance_span();
                    let span = join_span(lhs.span, end);
                    Expr {
                        kind: ExprKind::IsNull {
                            expr: Box::new(lhs),
                            negated: true,
                        },
                        span,
                    }
                }
                TokenKind::Keyword(Keyword::BETWEEN) => {
                    self.advance();
                    let (lo, hi) = self.between_tail()?;
                    let span = join_span(lhs.span, hi.span);
                    Expr {
                        kind: ExprKind::Between {
                            expr: Box::new(lhs),
                            lo: Box::new(lo),
                            hi: Box::new(hi),
                            negated: false,
                        },
                        span,
                    }
                }
                TokenKind::Keyword(Keyword::IN) => {
                    self.advance();
                    self.in_tail(lhs, false)?
                }
                TokenKind::Keyword(Keyword::LIKE)
                | TokenKind::Keyword(Keyword::GLOB)
                | TokenKind::Ilike => self.like_op(lhs, false)?,
                TokenKind::Keyword(Keyword::NOT) => match self.peek_at(1).kind.clone() {
                    TokenKind::Null => {
                        self.advance();
                        let end = self.advance_span();
                        let span = join_span(lhs.span, end);
                        Expr {
                            kind: ExprKind::IsNull {
                                expr: Box::new(lhs),
                                negated: true,
                            },
                            span,
                        }
                    }
                    TokenKind::Keyword(Keyword::BETWEEN) => {
                        self.advance();
                        self.advance();
                        let (lo, hi) = self.between_tail()?;
                        let span = join_span(lhs.span, hi.span);
                        Expr {
                            kind: ExprKind::Between {
                                expr: Box::new(lhs),
                                lo: Box::new(lo),
                                hi: Box::new(hi),
                                negated: true,
                            },
                            span,
                        }
                    }
                    TokenKind::Keyword(Keyword::IN) => {
                        self.advance();
                        self.advance();
                        self.in_tail(lhs, true)?
                    }
                    TokenKind::Keyword(Keyword::LIKE)
                    | TokenKind::Keyword(Keyword::GLOB)
                    | TokenKind::Ilike => {
                        self.advance();
                        self.like_op(lhs, true)?
                    }
                    _ => break,
                },
                _ => break,
            }

match self.peek_at(1).kind.clone() {
                    TokenKind::Null => {
                        self.advance();
                        let end = self.advance_span();
                        let span = join_span(lhs.span, end);
                        Expr {
                            kind: ExprKind::IsNull {
                                expr: Box::new(lhs),
                                negated: true,
                            },
                            span,
                        }
                    }
                    TokenKind::Keyword(Keyword::BETWEEN) => {
                        self.advance();
                        self.advance();
                        let (lo, hi) = self.between_tail()?;
                        let span = join_span(lhs.span, hi.span);
                        Expr {
                            kind: ExprKind::Between {
                                expr: Box::new(lhs),
                                lo: Box::new(lo),
                                hi: Box::new(hi),
                                negated: true,
                            },
                            span,
                        }
                    }
                    TokenKind::Keyword(Keyword::IN) => {
                        self.advance();
                        self.advance();
                        self.in_tail(lhs, true)?
                    }
                    TokenKind::Keyword(Keyword::LIKE)
                    | TokenKind::Keyword(Keyword::GLOB)
                    | TokenKind::Ilike => {
                        self.advance();
                        self.like_op(lhs, true)?
                    }
                    _ => break,
                }

match self.tokens.get(idx) {
                Some(t) => &t.kind,
                None => return false,
            }

match kind {
                TokenKind::Eof => return false,
                TokenKind::LParen => depth = depth.saturating_add(1),
                TokenKind::RParen => {
                    if depth == 0 {
                        let after_in = matches!(
                            self.tokens.get(idx.saturating_add(1)).map(|t| &t.kind),
                            Some(TokenKind::Keyword(Keyword::IN))
                        );
                        let after_not_in = matches!(
                            self.tokens.get(idx.saturating_add(1)).map(|t| &t.kind),
                            Some(TokenKind::Keyword(Keyword::NOT))
                        ) && matches!(
                            self.tokens.get(idx.saturating_add(2)).map(|t| &t.kind),
                            Some(TokenKind::Keyword(Keyword::IN))
                        );
                        return saw_top_comma && (after_in || after_not_in);
                    }
                    depth = depth.saturating_sub(1);
                }
                TokenKind::Comma if depth == 0 => saw_top_comma = true,
                _ => {}
            }

match self.expr_list() {
            Ok(list) => list,
            Err(_) => {
                self.pos = start_pos;
                return Ok(None);
            }
        }

match op {
            TokenKind::Ilike => self.ilike_tail(lhs, negated),
            _ => self.like_tail(lhs, op == TokenKind::Keyword(Keyword::GLOB), negated),
        }

match this.peek().kind {
                TokenKind::Plus => Some(UnaryOp::Plus),
                TokenKind::Minus => Some(UnaryOp::Minus),
                TokenKind::BitNot => Some(UnaryOp::BitNot),
                _ => None,
            }

match &self.peek().kind {
            TokenKind::Integer(v) => {
                let v = *v;
                let span = self.advance_span();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Integer(v)),
                    span,
                })
            }
            TokenKind::Float(v) => {
                let v = *v;
                let span = self.advance_span();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Float(v)),
                    span,
                })
            }
            TokenKind::String(s) => {
                let s = s.clone();
                let span = self.advance_span();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Str(s)),
                    span,
                })
            }
            TokenKind::Blob(b) => {
                let b = (**b).clone();
                let span = self.advance_span();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Blob(b)),
                    span,
                })
            }
            TokenKind::Null => {
                let span = self.advance_span();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Null),
                    span,
                })
            }
            TokenKind::True => {
                let span = self.advance_span();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::True),
                    span,
                })
            }
            TokenKind::False => {
                let span = self.advance_span();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::False),
                    span,
                })
            }
            TokenKind::Param(p) => {
                let kind = match p.as_ref() {
                    Param::Anonymous => ParamKind::Anonymous,
                    Param::Numbered(n) => ParamKind::Numbered(*n),
                    Param::Colon(s) => ParamKind::Colon(s.clone()),
                    Param::At(s) => ParamKind::At(s.clone()),
                    Param::Dollar(s) => ParamKind::Dollar(s.clone()),
                };
                let span = self.advance_span();
                Ok(Expr {
                    kind: ExprKind::Param(kind),
                    span,
                })
            }
            TokenKind::Keyword(Keyword::CURRENT_TIME)
            | TokenKind::Keyword(Keyword::CURRENT_DATE)
            | TokenKind::Keyword(Keyword::CURRENT_TIMESTAMP) => {
                self.unsupported("CURRENT_TIME/CURRENT_DATE/CURRENT_TIMESTAMP not yet supported")
            }
            TokenKind::Keyword(Keyword::CASE) => self.case_expr(),
            TokenKind::Keyword(Keyword::CAST) => self.cast_expr(),
            TokenKind::Keyword(Keyword::EXISTS) => {
                let start = self.advance_span();
                self.exists_tail(start, false)
            }
            TokenKind::Identifier(name) => {
                let name = name.clone();
                let start = self.advance_span();
                if matches!(self.peek().kind, TokenKind::LParen) {
                    return self.function_call(name, start);
                }
                let mut parts = vec![name];
                while matches!(self.peek().kind, TokenKind::Dot) && parts.len() < 3 {
                    self.advance();
                    let (part, _) = self.identifier()?;
                    parts.push(part);
                }
                let end = self
                    .tokens
                    .get(self.pos.saturating_sub(1))
                    .map_or(start, |t| t.span);
                let span = join_span(start, end);
                // Exactly one, two or three parts (db-core#232): the old
                // wildcard arm also matched `a.b.c.d`, silently dropping
                // the trailing parts, and `unwrap_or_default()` could
                // mint an empty identifier. Moved out of `parts` by
                // value (db-core#486: `parts.as_slice()` forced a
                // `.clone()` of every identifier `String` here -- a
                // second heap copy on top of the one `self.identifier()`/
                // the `Identifier(name)` match already produced --
                // instead of just moving the `String`s `parts` already
                // owns.
                let len = parts.len();
                let mut parts = parts.into_iter();
                let kind = match len {
                    1..=3 => {
                        let catalog = if len == 3 { parts.next() } else { None };
                        let table = if len >= 2 { parts.next() } else { None };
                        let Some(name) = parts.next() else {
                            return self
                                .invalid("a column reference has at most three dotted parts");
                        };
                        ExprKind::Column {
                            catalog,
                            table,
                            name,
                        }
                    }
                    _ => return self.invalid("a column reference has at most three dotted parts"),
                };
                Ok(Expr { kind, span })
            }
            // SQLite treats most keywords as usable function names when
            // followed by `(` (e.g. `replace(...)`, `glob(...)`) — only
            // the handful matched above (CASE/CAST/EXISTS/CURRENT_*)
            // are true reserved words in expression position.
            TokenKind::Keyword(kw) if matches!(self.peek_at(1).kind, TokenKind::LParen) => {
                let kw = *kw;
                let span = self.advance_span();
                self.function_call(format!("{kw:?}"), span)
            }
            TokenKind::LParen => {
                let start = self.advance_span();
                if self.at_kw(Keyword::SELECT) {
                    let subquery = self.parse_select_stmt()?;
                    if matches!(
                        self.peek().kind,
                        TokenKind::Keyword(Keyword::UNION)
                            | TokenKind::Keyword(Keyword::INTERSECT)
                            | TokenKind::Keyword(Keyword::EXCEPT)
                    ) {
                        return self.unsupported(
                            "compound SELECT (UNION/INTERSECT/EXCEPT) not yet supported",
                        );
                    }
                    let end = self.expect_punct(TokenKind::RParen, "')' to close subquery")?;
                    let span = join_span(start, end);
                    return Ok(Expr {
                        kind: ExprKind::Subquery(Box::new(subquery)),
                        span,
                    });
                }
                let inner = self.expr()?;
                let end = self.expect_punct(TokenKind::RParen, "')' to close expression")?;
                let span = join_span(start, end);
                Ok(Expr {
                    kind: ExprKind::Paren(Box::new(inner)),
                    span,
                })
            }
            TokenKind::LBracket => self.list_literal(),
            other => Err(ParseFail::Invalid {
                message: format!("expected column or expression, found {other:?}"),
                span: self.peek().span,
            }),
        }

match len {
                    1..=3 => {
                        let catalog = if len == 3 { parts.next() } else { None };
                        let table = if len >= 2 { parts.next() } else { None };
                        let Some(name) = parts.next() else {
                            return self
                                .invalid("a column reference has at most three dotted parts");
                        };
                        ExprKind::Column {
                            catalog,
                            table,
                            name,
                        }
                    }
                    _ => return self.invalid("a column reference has at most three dotted parts"),
                }

match self.peek().kind.clone() {
            TokenKind::Integer(v) => {
                self.advance();
                Ok(v.to_string())
            }
            other => {
                let span = self.peek().span;
                Err(ParseFail::Invalid {
                    message: format!("expected number, found {other:?}"),
                    span,
                })
            }
        }

match &e.kind {
        ExprKind::Unary { expr, .. }
        | ExprKind::IsNull { expr, .. }
        | ExprKind::Cast { expr, .. }
        | ExprKind::Collate { expr, .. }
        | ExprKind::Paren(expr)
        | ExprKind::InSubquery { expr, .. } => vec![expr],
        ExprKind::Binary { lhs, rhs, .. } | ExprKind::Is { lhs, rhs, .. } => vec![lhs, rhs],
        ExprKind::Between { expr, lo, hi, .. } => vec![expr, lo, hi],
        ExprKind::In { expr, list, .. } => std::iter::once(&**expr).chain(list).collect(),
        ExprKind::Like {
            expr,
            pattern,
            escape,
            ..
        } => [Some(&**expr), Some(&**pattern), escape.as_deref()]
            .into_iter()
            .flatten()
            .collect(),
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => operand
            .as_deref()
            .into_iter()
            .chain(whens.iter().flat_map(|(w, t)| [w, t]))
            .chain(else_.as_deref())
            .collect(),
        ExprKind::FunctionCall {
            args: FunctionArgs::List(list),
            ..
        }
        | ExprKind::InSubqueryMulti { exprs: list, .. } => list.iter().collect(),
        _ => Vec::new(),
    }

match parse(&over) {
                    crate::parser::row::ParseOutcome::Invalid { message, .. } => assert!(
                        message.contains("Expression tree is too large (maximum depth 1000)"),
                        "{message}"
                    ),
                    other => panic!("{term}{op} x {n}: {other:?}"),
                }

match crate::parser::row::parse_select(sql) {
            crate::parser::row::ParseOutcome::Accepted(select) => *select,
            other => panic!("{sql:?} must parse, got {other:?}"),
        }

match &select.columns[0] {
            ResultColumn::Expr { expr, .. } => match &expr.kind {
                ExprKind::FunctionCall { tail, .. } => tail.clone(),
                other => panic!("expected a function call, got {other:?}"),
            },
            other => panic!("expected an expression column, got {other:?}"),
        }

match &expr.kind {
                ExprKind::FunctionCall { tail, .. } => tail.clone(),
                other => panic!("expected a function call, got {other:?}"),
            }

match self.distinct {
            Some(Distinctness::Distinct) => write!(f, " DISTINCT")?,
            Some(Distinctness::All) => write!(f, " ALL")?,
            None => {}
        }

match self.op {
            CompoundOp::UnionAll => write!(f, "UNION ALL SELECT")?,
            CompoundOp::Union => write!(f, "UNION SELECT")?,
        }

match self.distinct {
            Some(Distinctness::Distinct) => write!(f, " DISTINCT")?,
            Some(Distinctness::All) => write!(f, " ALL")?,
            None => {}
        }

match self {
            ResultColumn::Star => write!(f, "*"),
            ResultColumn::TableStar { table } => write!(f, "{table}.*"),
            ResultColumn::Expr { expr, alias } => {
                write!(f, "{expr}")?;
                if let Some(alias) = alias {
                    write!(f, " AS {alias}")?;
                }
                Ok(())
            }
        }

match &self.kind {
            TableRefKind::Name(name) => write!(f, "{name}")?,
            TableRefKind::Subquery(select) => write!(f, "({select})")?,
            TableRefKind::Unnest { expr, column } => {
                write!(f, "UNNEST({expr})")?;
                if let (Some(alias), Some(column)) = (&self.alias, column) {
                    return write!(f, " AS {alias}({column})");
                }
            }
        }

match &self.constraint {
            Some(JoinConstraint::On(expr)) => write!(f, " ON {expr}")?,
            Some(JoinConstraint::Using(cols)) => write!(f, " USING ({})", cols.join(", "))?,
            None => {}
        }

match self.desc {
            Some(false) => write!(f, " ASC")?,
            Some(true) => write!(f, " DESC")?,
            None => {}
        }

match self.nulls_last {
            Some(false) => write!(f, " NULLS FIRST")?,
            Some(true) => write!(f, " NULLS LAST")?,
            None => {}
        }

match &self.kind {
            ExprKind::Literal(lit) => write!(f, "{lit}"),
            ExprKind::Param(p) => write!(f, "{p}"),
            ExprKind::Column {
                catalog,
                table,
                name,
            } => {
                if let Some(catalog) = catalog {
                    write!(f, "{catalog}.")?;
                }
                if let Some(table) = table {
                    write!(f, "{table}.")?;
                }
                write!(f, "{name}")
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                tail,
            } => {
                write!(f, "{name}(")?;
                if *distinct {
                    write!(f, "DISTINCT ")?;
                }
                match args {
                    FunctionArgs::Star => write!(f, "*")?,
                    FunctionArgs::List(list) => {
                        for (i, a) in list.iter().enumerate() {
                            if i > 0 {
                                write!(f, ", ")?;
                            }
                            write!(f, "{a}")?;
                        }
                    }
                }
                write!(f, ")")?;
                if let Some(tail) = tail {
                    if let Some(range) = &tail.range {
                        write!(f, " RANGE {} {}", range.amount, range.unit)?;
                    }
                    if let Some(filter) = &tail.filter {
                        write!(f, " FILTER (WHERE {filter})")?;
                    }
                    if let Some(over) = &tail.over {
                        write!(f, " OVER {over}")?;
                    }
                }
                Ok(())
            }
            ExprKind::Unary { op, expr } => {
                let op = match op {
                    UnaryOp::Not => "NOT ",
                    UnaryOp::Plus => "+",
                    UnaryOp::Minus => "-",
                    UnaryOp::BitNot => "~",
                };
                write!(f, "{op}{expr}")
            }
            ExprKind::Binary { op, lhs, rhs } => {
                write!(f, "{lhs} {} {rhs}", binop_str(*op))
            }
            ExprKind::Is { lhs, rhs, negated } => {
                write!(f, "{lhs} IS {}{rhs}", if *negated { "NOT " } else { "" })
            }
            ExprKind::IsNull { expr, negated } => {
                write!(f, "{expr} {}", if *negated { "NOTNULL" } else { "ISNULL" })
            }
            ExprKind::Between {
                expr,
                lo,
                hi,
                negated,
            } => write!(
                f,
                "{expr} {}BETWEEN {lo} AND {hi}",
                if *negated { "NOT " } else { "" }
            ),
            ExprKind::In {
                expr,
                list,
                negated,
            } => {
                write!(f, "{expr} {}IN (", if *negated { "NOT " } else { "" })?;
                for (i, e) in list.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{e}")?;
                }
                write!(f, ")")
            }
            ExprKind::Like {
                expr,
                pattern,
                glob,
                negated,
                escape,
            } => {
                let op = if *glob { "GLOB" } else { "LIKE" };
                write!(
                    f,
                    "{expr} {}{op} {pattern}",
                    if *negated { "NOT " } else { "" }
                )?;
                if let Some(escape) = escape {
                    write!(f, " ESCAPE {escape}")?;
                }
                Ok(())
            }
            ExprKind::Case {
                operand,
                whens,
                else_,
            } => {
                write!(f, "CASE")?;
                if let Some(operand) = operand {
                    write!(f, " {operand}")?;
                }
                for (cond, res) in whens {
                    write!(f, " WHEN {cond} THEN {res}")?;
                }
                if let Some(else_) = else_ {
                    write!(f, " ELSE {else_}")?;
                }
                write!(f, " END")
            }
            ExprKind::Cast { expr, type_name } => write!(f, "CAST({expr} AS {type_name})"),
            ExprKind::Collate { expr, collation } => write!(f, "{expr} COLLATE {collation}"),
            ExprKind::Paren(inner) => write!(f, "({inner})"),
            ExprKind::Subquery(select) => write!(f, "({select})"),
            ExprKind::Exists { subquery, negated } => {
                if *negated {
                    write!(f, "NOT EXISTS ({subquery})")
                } else {
                    write!(f, "EXISTS ({subquery})")
                }
            }
            ExprKind::InSubquery {
                expr,
                subquery,
                negated,
            } => {
                if *negated {
                    write!(f, "{expr} NOT IN ({subquery})")
                } else {
                    write!(f, "{expr} IN ({subquery})")
                }
            }
            ExprKind::InSubqueryMulti {
                exprs,
                subquery,
                negated,
            } => {
                write!(f, "(")?;
                for (i, e) in exprs.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{e}")?;
                }
                write!(f, ")")?;
                if *negated {
                    write!(f, " NOT IN ({subquery})")
                } else {
                    write!(f, " IN ({subquery})")
                }
            }
        }

match args {
                    FunctionArgs::Star => write!(f, "*")?,
                    FunctionArgs::List(list) => {
                        for (i, a) in list.iter().enumerate() {
                            if i > 0 {
                                write!(f, ", ")?;
                            }
                            write!(f, "{a}")?;
                        }
                    }
                }

match op {
                    UnaryOp::Not => "NOT ",
                    UnaryOp::Plus => "+",
                    UnaryOp::Minus => "-",
                    UnaryOp::BitNot => "~",
                }

match self {
            Literal::Integer(v) => write!(f, "{v}"),
            Literal::Float(v) => write!(f, "{v}"),
            Literal::Str(s) => write!(f, "'{}'", s.replace('\'', "''")),
            Literal::Blob(bytes) => {
                write!(f, "X'")?;
                for b in bytes {
                    write!(f, "{b:02X}")?;
                }
                write!(f, "'")
            }
            Literal::Null => write!(f, "NULL"),
            Literal::True => write!(f, "TRUE"),
            Literal::False => write!(f, "FALSE"),
        }

match &self.source {
            InsertSource::DefaultValues => write!(f, " DEFAULT VALUES"),
            InsertSource::Values(rows) => {
                write!(f, " VALUES ")?;
                for (i, row) in rows.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "(")?;
                    for (j, expr) in row.iter().enumerate() {
                        if j > 0 {
                            write!(f, ", ")?;
                        }
                        write!(f, "{expr}")?;
                    }
                    write!(f, ")")?;
                }
                Ok(())
            }
            InsertSource::Select(select) => write!(f, " {select}"),
        }

match &clause.action {
                UpsertAction::DoNothing => write!(f, " DO NOTHING")?,
                UpsertAction::DoUpdate {
                    assignments,
                    where_clause,
                } => {
                    write!(f, " DO UPDATE SET ")?;
                    for (i, assignment) in assignments.iter().enumerate() {
                        if i > 0 {
                            write!(f, ", ")?;
                        }
                        // The parser yields one column per assignment (a
                        // tuple assignment is expanded).
                        write!(
                            f,
                            "{} = {}",
                            assignment.columns.join(", "),
                            assignment.value
                        )?;
                    }
                    if let Some(where_clause) = where_clause {
                        write!(f, " WHERE {where_clause}")?;
                    }
                }
            }

match self {
            ColumnConstraint::NotNull => write!(f, "NOT NULL"),
            ColumnConstraint::PrimaryKey {
                desc,
                autoincrement,
            } => {
                write!(f, "PRIMARY KEY")?;
                match desc {
                    Some(false) => write!(f, " ASC")?,
                    Some(true) => write!(f, " DESC")?,
                    None => {}
                }
                if *autoincrement {
                    write!(f, " AUTOINCREMENT")?;
                }
                Ok(())
            }
            ColumnConstraint::Unique => write!(f, "UNIQUE"),
            ColumnConstraint::Default(value) => write!(f, "DEFAULT {value}"),
            ColumnConstraint::Check { expr, .. } => write!(f, "CHECK ({expr})"),
            ColumnConstraint::Collate(name) => write!(f, "COLLATE {name}"),
        }

match desc {
                    Some(false) => write!(f, " ASC")?,
                    Some(true) => write!(f, " DESC")?,
                    None => {}
                }

match self {
            DefaultValue::Literal(expr) => write!(f, "{expr}"),
            DefaultValue::Paren(expr) => write!(f, "({expr})"),
        }

match self {
            TableConstraint::PrimaryKey(cols) => {
                write!(f, "PRIMARY KEY (")?;
                write_indexed_columns(f, cols)?;
                write!(f, ")")
            }
            TableConstraint::Unique(cols) => {
                write!(f, "UNIQUE (")?;
                write_indexed_columns(f, cols)?;
                write!(f, ")")
            }
            TableConstraint::Check { expr, .. } => write!(f, "CHECK ({expr})"),
        }

match self.desc {
            Some(false) => write!(f, " ASC")?,
            Some(true) => write!(f, " DESC")?,
            None => {}
        }

match parse_select(sql) {
            ParseOutcome::Accepted(select) => select.to_string(),
            other => panic!("expected accepted select, got {other:?}"),
