match letter {
        b'N' if word.eq_ignore_ascii_case("NULL") => return TokenKind::Null,
        b'T' if word.eq_ignore_ascii_case("TRUE") => return TokenKind::True,
        b'F' if word.eq_ignore_ascii_case("FALSE") => return TokenKind::False,
        _ => {}
    }

match self.peek_char(src) {
                Some(c) if c.is_whitespace() => {
                    self.bump(src);
                }
                Some('-') => {
                    // Lookahead for `--` line comment without consuming
                    // a lone `-` (the Minus operator).
                    if self.peek_at(src, 1) == Some('-') {
                        self.bump(src);
                        self.bump(src);
                        while let Some(c) = self.peek_char(src) {
                            if c == '\n' {
                                break;
                            }
                            self.bump(src);
                        }
                        continue;
                    }
                    break;
                }
                Some('/') => {
                    if self.peek_at(src, 1) == Some('*') {
                        self.bump(src);
                        self.bump(src);
                        loop {
                            match self.peek_char(src) {
                                None => {
                                    return Some("unterminated block comment".to_string());
                                }
                                Some('*') => {
                                    self.bump(src);
                                    if self.peek_char(src) == Some('/') {
                                        self.bump(src);
                                        break;
                                    }
                                }
                                Some(_) => {
                                    self.bump(src);
                                }
                            }
                        }
                        continue;
                    }
                    break;
                }
                _ => break,
            }

match self.peek_char(src) {
                                None => {
                                    return Some("unterminated block comment".to_string());
                                }
                                Some('*') => {
                                    self.bump(src);
                                    if self.peek_char(src) == Some('/') {
                                        self.bump(src);
                                        break;
                                    }
                                }
                                Some(_) => {
                                    self.bump(src);
                                }
                            }

match c {
            '0'..='9' => self.scan_number(src),
            '.' => {
                // Lookahead: `.5` is a float; a lone `.` is Dot.
                if matches!(self.peek_at(src, 1), Some('0'..='9')) {
                    self.scan_number(src)
                } else {
                    self.bump(src);
                    TokenKind::Dot
                }
            }
            '\'' => self.scan_string(src),
            '"' => self.scan_quoted_identifier(src, '"', '"'),
            '[' if self.subscripts && self.after_expr => {
                self.bump(src);
                self.open_brackets = self.open_brackets.saturating_add(1);
                TokenKind::LBracket
            }
            ']' if self.open_brackets > 0 => {
                self.bump(src);
                self.open_brackets = self.open_brackets.saturating_sub(1);
                TokenKind::RBracket
            }
            // #827: elsewhere in the column dialect, `[` opening a string,
            // number, NULL or `]` is a list literal (`['a', 'b']`); any
            // other `[` still quotes an identifier.
            '[' if self.subscripts && self.opens_list(src) => {
                self.bump(src);
                self.open_brackets = self.open_brackets.saturating_add(1);
                TokenKind::LBracket
            }
            '[' => self.scan_quoted_identifier(src, '[', ']'),
            '`' => self.scan_quoted_identifier(src, '`', '`'),
            '?' => self.scan_param_question(src),
            ':' => self.scan_param_named(src, ':'),
            '@' => self.scan_param_named(src, '@'),
            '$' => self.scan_param_named(src, '$'),
            c if c == 'x' || c == 'X' => self.scan_maybe_blob(src, c),
            c if is_ident_start(c) => self.scan_identifier_or_keyword(src),
            _ => self.scan_operator(src),
        }

match self.peek_char(src) {
                    None => {
                        return TokenKind::Error(format!(
                            "unterminated blob literal starting with {x}'"
                        ));
                    }
                    Some('\'') => {
                        break;
                    }
                    Some(_) => {
                        self.bump(src);
                    }
                }

match u8::from_str_radix(pair, 16) {
                    Ok(b) => bytes.push(b),
                    Err(_) => {
                        let msg = format!("invalid blob byte: {pair:?}");
                        self.bump(src); // closing '
                        return TokenKind::Error(msg);
                    }
                }

match self.peek_char(src) {
                None => return TokenKind::Error("unterminated string literal".to_string()),
                Some('\'') => {
                    let quote_pos = self.pos;
                    self.bump(src); // consume this quote
                    if self.peek_char(src) == Some('\'') {
                        let seg = src.get(seg_start..quote_pos).unwrap_or("");
                        let buf = acc.get_or_insert_with(String::new);
                        buf.push_str(seg);
                        buf.push('\'');
                        self.bump(src); // consume the second quote
                        seg_start = self.pos;
                    } else {
                        let seg = src.get(seg_start..quote_pos).unwrap_or("");
                        return TokenKind::String(match acc {
                            Some(mut buf) => {
                                buf.push_str(seg);
                                buf
                            }
                            None => seg.to_string(),
                        });
                    }
                }
                Some(_) => {
                    self.bump(src);
                }
            }

match acc {
                            Some(mut buf) => {
                                buf.push_str(seg);
                                buf
                            }
                            None => seg.to_string(),
                        }

match self.peek_char(src) {
                None => {
                    return TokenKind::Error(format!(
                        "unterminated quoted identifier starting with {open:?}"
                    ));
                }
                Some(c) if c == close => {
                    let close_pos = self.pos;
                    self.bump(src); // consume this closing delimiter
                    if escapes && self.peek_char(src) == Some(close) {
                        let seg = src.get(seg_start..close_pos).unwrap_or("");
                        let buf = acc.get_or_insert_with(String::new);
                        buf.push_str(seg);
                        buf.push(close);
                        self.bump(src); // consume the doubled delimiter
                        seg_start = self.pos;
                    } else {
                        let seg = src.get(seg_start..close_pos).unwrap_or("");
                        return TokenKind::Identifier(match acc {
                            Some(mut buf) => {
                                buf.push_str(seg);
                                buf
                            }
                            None => seg.to_string(),
                        });
                    }
                }
                Some(_) => {
                    self.bump(src);
                }
            }

match acc {
                            Some(mut buf) => {
                                buf.push_str(seg);
                                buf
                            }
                            None => seg.to_string(),
                        }

match digits.parse::<u32>() {
                Ok(n) => TokenKind::Param(Box::new(Param::Numbered(n))),
                Err(_) => TokenKind::Error(format!("parameter number out of range: {digits}")),
            }

match i64::from_str_radix(hex, 16) {
                Ok(n) => TokenKind::Integer(n),
                Err(_) => match u64::from_str_radix(hex, 16) {
                    // SQLite hex literals above `i64::MAX` wrap to their
                    // two's-complement value (`0xFFFFFFFFFFFFFFFF` is -1).
                    Ok(n) => TokenKind::Integer(i64::from_ne_bytes(n.to_ne_bytes())),
                    Err(e) => TokenKind::Error(format!("invalid hex literal: {e}")),
                },
            }

match u64::from_str_radix(hex, 16) {
                    // SQLite hex literals above `i64::MAX` wrap to their
                    // two's-complement value (`0xFFFFFFFFFFFFFFFF` is -1).
