match value {
            RecordValue::Null => out.push(TAG_NULL),
            RecordValue::Bool(b) => out.extend_from_slice(&[TAG_BOOL, u8::from(*b)]),
            RecordValue::Int(i) => {
                out.push(TAG_INT);
                out.extend_from_slice(&i.to_le_bytes());
            }
            RecordValue::UInt(u) => {
                out.push(TAG_UINT);
                out.extend_from_slice(&u.to_le_bytes());
            }
            RecordValue::Float(f) => {
                out.push(TAG_FLOAT);
                out.extend_from_slice(&f.to_le_bytes());
            }
            RecordValue::Str(s) => {
                out.push(TAG_STR);
                length_prefixed(&mut out, s.as_bytes())?;
            }
            RecordValue::Bytes(b) => {
                out.push(TAG_BYTES);
                length_prefixed(&mut out, b)?;
            }
            RecordValue::Decimal(d) => {
                out.push(TAG_DECIMAL);
                out.extend_from_slice(&d.to_le_bytes());
            }
            // The entry count, then per entry the key and its value (a
            // NULL tag, or a string tag and the string).
            RecordValue::Map(entries) => {
                out.push(TAG_MAP);
                out.extend_from_slice(&u32::try_from(entries.len()).ok()?.to_le_bytes());
                for (key, value) in entries {
                    length_prefixed(&mut out, key.as_bytes())?;
                    optional_str(&mut out, value.as_deref())?;
                }
            }
            // The element count, then per element a NULL tag, or a string
            // tag and the string.
            RecordValue::List(items) => {
                out.push(TAG_LIST);
                out.extend_from_slice(&u32::try_from(items.len()).ok()?.to_le_bytes());
                for item in items {
                    optional_str(&mut out, item.as_deref())?;
                }
            }
        }

match value {
