match rng.below(10) {
                0..=5 => {
                    let n = 1 + usize::try_from(rng.below(6)).unwrap();
                    append(&mut w, next..next + n);
                    next += n;
                }
                6 => w.seal_head().unwrap(),
                7 => {
                    w.flush().unwrap();
                }
                8 => {
                    w.flush_all().unwrap();
                }
                // Past the page size, so flushes cut sealed pages.
                _ if rng.below(3) == 0 => {
                    append_fast(&mut w, next..next + 4500);
                    next += 4500;
