                    let values = match (is_dictionary_encoded, &dictionary) {
                        (true, Some(dict)) => {
                            decode_data(&page_body, &data_page_header, max_def_level, dict)?
                        }
                        (true, None) => return Err(FileError::MissingDictionaryPage),
                        (false, _) => decode_plain(&page_body, &data_page_header, max_def_level)?,
                    };
                    out.extend(values);
                }
                PageType::Dictionary(dictionary_page_header) => {
                    if dictionary.is_some() {
                        return Err(FileError::UnexpectedDictionaryPage);
                    }
                    let dictionary_body = pages.body(compressed, header.uncompressed_page_size)?;
                    dictionary = Some(decode_dictionary(
                        &dictionary_body,
                        dictionary_page_header.num_values,
                    )?);
                }
            }

match (is_dictionary_encoded, &dictionary) {
                        (true, Some(dict)) => {
                            decode_data(&page_body, &data_page_header, max_def_level, dict)?
                        }
                        (true, None) => return Err(FileError::MissingDictionaryPage),
                        (false, _) => decode_plain(&page_body, &data_page_header, max_def_level)?,
                    }

match header.page_type {
                PageType::Data(data_page_header) => {
                    let Some(dictionary) = dictionary.as_deref() else {
                        return Ok(None);
                    };
                    let page_body = pages.body(compressed, header.uncompressed_page_size)?;
                    match data_page_header.encoding {
                        page::Encoding::PlainDictionary | page::Encoding::RleDictionary => {
                            reader::read_dictionary_fixed(
                                &page_body,
                                &data_page_header,
                                max_def_level,
                                dictionary,
                                &mut values,
                                &mut present,
                            )?
                        }
                        page::Encoding::Plain => reader::read_plain_fixed(
                            &page_body,
                            &data_page_header,
                            max_def_level,
                            &decode,
                            &mut values,
                            &mut present,
                        )?,
                        _ => return Ok(None),
                    }
                }
                PageType::Dictionary(dictionary_page_header) => {
                    if dictionary.is_some() {
                        return Err(FileError::UnexpectedDictionaryPage);
                    }
                    let body = pages.body(compressed, header.uncompressed_page_size)?;
                    dictionary = Some(reader::decode_dictionary_fixed(
                        &body,
                        dictionary_page_header.num_values,
                        &decode,
                    )?);
                }
            }

match header.page_type {
                PageType::Data(data_page_header) => {
                    let Some(dict) = dictionary.as_mut() else {
                        return Ok(None);
                    };
                    let dictionary_encoded = matches!(
                        data_page_header.encoding,
                        page::Encoding::PlainDictionary | page::Encoding::RleDictionary
                    );
                    let page_body = pages.body(compressed, header.uncompressed_page_size)?;
                    if dictionary_encoded {
                        indices.extend(reader::read_dictionary_index_column(
                            &page_body,
                            &data_page_header,
                            max_def_level,
                        )?);
                        continue;
                    }
                    let Some(decode_plain) = decode_plain else {
                        return Ok(None);
                    };
                    for value in decode_plain(&page_body, &data_page_header, max_def_level)? {
                        let Some(value) = value else {
                            indices.push(None);
                            continue;
                        };
                        let index =
                            u32::try_from(dict.len()).map_err(|_| FileError::InvalidMetadata {
                                field: "dictionary entries",
                                value: i64::try_from(dict.len()).unwrap_or(i64::MAX),
                            })?;
                        dict.push(value);
                        indices.push(Some(index));
                    }
                }
                PageType::Dictionary(dictionary_page_header) => {
                    if dictionary.is_some() {
                        return Err(FileError::UnexpectedDictionaryPage);
                    }
                    let dictionary_body = pages.body(compressed, header.uncompressed_page_size)?;
                    dictionary = Some(decode_dictionary(
                        &dictionary_body,
                        dictionary_page_header.num_values,
                    )?);
                }
            }

match header.page_type {
                // #621: DuckDB and pyarrow dictionary-encode nested leaves
                // (a map's keys) by default.
                PageType::Dictionary(_) if levels_only => {}
                PageType::Dictionary(dictionary_page_header) => {
                    if dictionary.is_some() {
                        return Err(FileError::UnexpectedDictionaryPage);
                    }
                    let body = pages.body(compressed, header.uncompressed_page_size)?;
                    let count =
                        usize::try_from(dictionary_page_header.num_values).map_err(|_| {
                            FileError::InvalidMetadata {
                                field: "dictionary_page.num_values",
                                value: i64::from(dictionary_page_header.num_values),
                            }
                        })?;
                    let mut buf: &[u8] = &body;
                    let mut bit_pos = 0usize;
                    dictionary = Some(
                        (0..count)
                            .map(|_| {
                                reader::read_plain_scalar(&mut buf, physical_type, &mut bit_pos)
                            })
                            .collect::<reader::Result<_>>()?,
                    );
                }
                PageType::Data(data_page_header) => {
                    let dictionary_encoded = match data_page_header.encoding {
                        Encoding::Plain => false,
                        Encoding::PlainDictionary | Encoding::RleDictionary => true,
                        other => return Err(FileError::UnsupportedNestedEncoding(other)),
                    };
                    let page_body = pages.body(compressed, header.uncompressed_page_size)?;
                    let (rep_levels, def_levels, mut value_bytes) = reader::split_rep_def_levels(
                        &page_body,
                        &data_page_header,
                        leaf.max_rep_level,
                        leaf.max_def_level,
                    )?;

                    let num_values =
                        usize::try_from(data_page_header.num_values).map_err(|_| {
                            FileError::InvalidMetadata {
                                field: "data_page.num_values",
                                value: i64::from(data_page_header.num_values),
                            }
                        })?;
                    let defined = |i: usize| {
                        def_levels.get(i).copied().unwrap_or(leaf.max_def_level)
                            == leaf.max_def_level
                    };
                    if levels_only {
                        // The levels below are all this read keeps.
                    } else if dictionary_encoded {
                        let dict = dictionary
                            .as_ref()
                            .ok_or(FileError::MissingDictionaryPage)?;
                        let present = (0..num_values).filter(|&i| defined(i)).count();
                        let mut indices =
                            reader::read_dictionary_indices(value_bytes, present)?.into_iter();
                        for i in 0..num_values {
                            if !defined(i) {
                                out.values.push(None);
                                continue;
                            }
                            let index = indices.next().ok_or(ReadError::UnexpectedEof)?;
                            let entry = usize::try_from(index)
                                .ok()
                                .and_then(|i| dict.get(i))
                                .ok_or(ReadError::DictionaryIndexOutOfRange(index))?;
                            out.values.push(Some(entry.clone()));
                        }
                    } else {
                        let mut bit_pos = 0usize;
                        for i in 0..num_values {
                            if defined(i) {
                                let scalar = reader::read_plain_scalar(
                                    &mut value_bytes,
                                    physical_type,
                                    &mut bit_pos,
                                )?;
                                out.values.push(Some(scalar));
                            } else {
                                out.values.push(None);
                            }
                        }
                    }
                    if rep_levels.is_empty() {
                        out.rep_levels.extend(std::iter::repeat_n(0, num_values));
                    } else {
                        out.rep_levels.extend(rep_levels);
                    }
                    if def_levels.is_empty() {
                        out.def_levels
                            .extend(std::iter::repeat_n(leaf.max_def_level, num_values));
                    } else {
                        out.def_levels.extend(def_levels);
                    }
                }
            }

match data_page_header.encoding {
                        Encoding::Plain => false,
                        Encoding::PlainDictionary | Encoding::RleDictionary => true,
                        other => return Err(FileError::UnsupportedNestedEncoding(other)),
                    }

match (rep, rows.last_mut()) {
                (0, _) => rows.push(Some(vec![(k, v)])),
                (_, Some(Some(entries))) => entries.push((k, v)),
                _ => return Err(not_a_map()),
            }

match items.values.get(i).and_then(Option::as_ref) {
                Some(reader::LeafScalar::Str(s)) if def == present => Some(s.clone()),
                _ if def < present => None,
                _ => return Err(not_a_list()),
            }

match (rep, rows.last_mut()) {
                (0, _) => rows.push(Some(vec![item])),
                (_, Some(Some(list))) => list.push(item),
                _ => return Err(not_a_list()),
            }

match items.values.get_mut(i).and_then(Option::take) {
                Some(reader::LeafScalar::Str(s)) if def == present => Some(s),
                _ if def < present => None,
                _ => return Err(not_a_list()),
            }

match header.page_type {
                PageType::Dictionary(dictionary_page_header) => {
                    if dict.is_some() {
                        return Err(FileError::UnexpectedDictionaryPage);
                    }
                    let body = pages.body(compressed, header.uncompressed_page_size)?;
                    let count =
                        usize::try_from(dictionary_page_header.num_values).map_err(|_| {
                            FileError::InvalidMetadata {
                                field: "dictionary_page.num_values",
                                value: i64::from(dictionary_page_header.num_values),
                            }
                        })?;
                    let mut buf: &[u8] = &body;
                    let mut bit_pos = 0usize;
                    let mut first: HashMap<Arc<str>, u32> = HashMap::with_capacity(count);
                    let mut unique: Vec<Arc<str>> = Vec::with_capacity(count);
                    let mut remap: Vec<u32> = Vec::with_capacity(count);
                    for _ in 0..count {
                        let reader::LeafScalar::Str(entry) = reader::read_plain_scalar(
                            &mut buf,
                            footer::PhysicalType::ByteArray,
                            &mut bit_pos,
                        )?
                        else {
                            return Err(not_a_list());
                        };
                        let next = u32::try_from(unique.len()).map_err(|_| not_a_list())?;
                        let code = *first.entry(Arc::clone(&entry)).or_insert(next);
                        if code == next {
                            unique.push(entry);
                        }
                        remap.push(code);
                    }
                    dict = Some((unique, remap));
                }
                PageType::Data(data_page_header) => {
                    let Some((_, remap)) = dict.as_ref() else {
                        return Ok(None);
                    };
                    if !matches!(
                        data_page_header.encoding,
                        Encoding::PlainDictionary | Encoding::RleDictionary
                    ) {
                        return Ok(None);
                    }
                    let page_body = pages.body(compressed, header.uncompressed_page_size)?;
                    let (rep_levels, def_levels, value_bytes) = reader::split_rep_def_levels(
                        &page_body,
                        &data_page_header,
                        leaf.max_rep_level,
                        leaf.max_def_level,
                    )?;
                    let num_values =
                        usize::try_from(data_page_header.num_values).map_err(|_| {
                            FileError::InvalidMetadata {
                                field: "data_page.num_values",
                                value: i64::from(data_page_header.num_values),
                            }
                        })?;
                    let defined = if def_levels.is_empty() {
                        num_values
                    } else {
                        def_levels.iter().filter(|&&d| d == present).count()
                    };
                    let mut codes =
                        reader::read_dictionary_indices(value_bytes, defined)?.into_iter();
                    // A page's levels are walked as they decode, so no
                    // chunk-wide level or code vector is ever held.
                    for i in 0..num_values {
                        let def = def_levels.get(i).copied().unwrap_or(present);
                        let rep = rep_levels.get(i).copied().unwrap_or(0);
                        if def < element {
                            if rep != 0 {
                                return Err(not_a_list());
                            }
                            row_valid.push(def.saturating_add(1) == element);
                            offsets.push(u32::try_from(indices.len()).map_err(|_| not_a_list())?);
                            continue;
                        }
                        if rep == 0 {
                            row_valid.push(true);
                            offsets.push(0);
                        } else if row_valid.is_empty() {
                            return Err(not_a_list());
                        }
                        if def == present {
                            let code = codes.next().ok_or_else(not_a_list)?;
                            let code = *remap.get(code as usize).ok_or_else(not_a_list)?;
                            indices.push(code);
                            element_valid.push(true);
                        } else if def < present {
                            indices.push(0);
                            element_valid.push(false);
                        } else {
                            return Err(not_a_list());
                        }
                        let end = u32::try_from(indices.len()).map_err(|_| not_a_list())?;
                        if let Some(last) = offsets.last_mut() {
                            *last = end;
                        }
                    }
                }
            }

match header.page_type {
                PageType::Data(data_page_header) => {
                    let Some((_, entries)) = dictionary.as_ref() else {
                        return Ok(None);
                    };
                    let page_body = pages.body(compressed, header.uncompressed_page_size)?;
                    if matches!(
                        data_page_header.encoding,
                        page::Encoding::PlainDictionary | page::Encoding::RleDictionary
                    ) {
                        indices.extend(reader::read_dictionary_index_column(
                            &page_body,
                            &data_page_header,
                            max_def_level,
                        )?);
                        continue;
                    }
                    for value in
                        reader::read_string_column(&page_body, &data_page_header, max_def_level)?
                    {
                        let Some(value) = value else {
                            indices.push(None);
                            continue;
                        };
                        let next = entries.saturating_add(fallback.len());
                        let index =
                            u32::try_from(next).map_err(|_| FileError::InvalidMetadata {
                                field: "dictionary entries",
                                value: i64::try_from(next).unwrap_or(i64::MAX),
                            })?;
                        fallback.push(value);
                        indices.push(Some(index));
                    }
                }
                PageType::Dictionary(dictionary_page_header) => {
                    if dictionary.is_some() {
                        return Err(FileError::UnexpectedDictionaryPage);
                    }
                    let entries =
                        usize::try_from(dictionary_page_header.num_values).map_err(|_| {
                            FileError::InvalidMetadata {
                                field: "dictionary_page.num_values",
                                value: i64::from(dictionary_page_header.num_values),
                            }
                        })?;
                    let body = pages.body(compressed, header.uncompressed_page_size)?;
                    dictionary = Some((body, entries));
                }
            }

match header.page_type {
                PageType::Data(data_page_header) => {
                    if dictionary.is_none()
                        || !matches!(
                            data_page_header.encoding,
                            page::Encoding::PlainDictionary | page::Encoding::RleDictionary
                        )
                    {
                        return Ok(None);
                    }
                }
                PageType::Dictionary(dictionary_page_header) => {
                    if dictionary.is_some() {
                        return Err(FileError::UnexpectedDictionaryPage);
                    }
                    let dictionary_body = pages.body(compressed, header.uncompressed_page_size)?;
                    dictionary = Some(decode_dictionary(
                        &dictionary_body,
                        dictionary_page_header.num_values,
                    )?);
                }
            }

match self.column_meta(column_index)?.physical_type {
            footer::PhysicalType::Int64 => {
                let is_millis = matches!(
                    self.file.converted_type(column_index),
                    Some(footer::ConvertedType::TimestampMillis)
                );
                let raw = self.read_int64_column(column_index)?;
                if !is_millis {
                    return Ok(raw);
                }
                raw.into_iter()
                    .map(|v| {
                        v.map(|v| v.checked_mul(1000).ok_or(FileError::TimestampOutOfRange))
                            .transpose()
                    })
                    .collect()
            }
            footer::PhysicalType::Int96 => {
                let raw = self.read_int96_column(column_index)?;
                raw.into_iter()
                    .map(|v| {
                        v.map(|v| int96_to_epoch_micros(v).ok_or(FileError::TimestampOutOfRange))
                            .transpose()
                    })
                    .collect()
            }
            other => Err(FileError::UnsupportedTimestampPhysicalType(other)),
        }

match self.column_meta(column_index)?.physical_type {
            footer::PhysicalType::Int32 => {
                let raw = self.read_int32_column(column_index)?;
                Ok(raw
                    .into_iter()
                    .map(|v| {
                        v.map(|v| crate::storage::parquet::decimal::Decimal {
                            unscaled: v as i128,
                            scale,
                        })
                    })
                    .collect())
            }
            footer::PhysicalType::Int64 => {
                let raw = self.read_int64_column(column_index)?;
                Ok(raw
                    .into_iter()
                    .map(|v| {
                        v.map(|v| crate::storage::parquet::decimal::Decimal {
                            unscaled: v as i128,
                            scale,
                        })
                    })
                    .collect())
            }
            footer::PhysicalType::FixedLenByteArray => {
                let raw = self.read_fixed_len_byte_array_column(column_index)?;
                raw.into_iter()
                    .map(|v| {
                        v.map(|bytes| {
                            // More than 16 bytes would lose the high bits in
                            // an i128 (#632): beyond DECIMAL(38), refused.
                            if bytes.len() > 16 {
                                return Err(FileError::InvalidMetadata {
                                    field: "DECIMAL fixed_len_byte_array length",
                                    value: i64::try_from(bytes.len()).unwrap_or(i64::MAX),
                                });
                            }
                            Ok(crate::storage::parquet::decimal::Decimal {
                                unscaled: crate::storage::parquet::decimal::from_be_bytes(&bytes),
                                scale,
                            })
                        })
                        .transpose()
                    })
                    .collect()
            }
            other => Err(FileError::UnsupportedDecimalPhysicalType(other)),
        }

match self {
            Self::Dict { valid, .. } | Self::Str { valid, .. } => valid.len(),
        }

match self {
            Self::Dict {
                dict,
                by_ptr,
                by_text,
                seen,
                indices,
                valid,
            } => {
                valid.push(item.is_some());
                let Some(s) = item else {
                    indices.push(0);
                    return Some(());
                };
                let code = match by_ptr.get(&s.as_ptr()) {
                    Some(&code) => code,
                    None => {
                        let next = u32::try_from(dict.len()).ok()?;
                        let code = *by_text.entry(Arc::clone(&s)).or_insert(next);
                        if code == next {
                            dict.push(Arc::clone(&s));
                        }
                        by_ptr.insert(s.as_ptr(), code);
                        seen.push(s);
                        code
                    }
                };
                indices.push(code);
            }
            Self::Str {
                offsets,
                data,
                valid,
            } => {
                valid.push(item.is_some());
                if let Some(s) = item {
                    data.push_str(&s);
                }
                offsets.push(u32::try_from(data.len()).ok()?);
            }
        }

match by_ptr.get(&s.as_ptr()) {
                    Some(&code) => code,
                    None => {
                        let next = u32::try_from(dict.len()).ok()?;
                        let code = *by_text.entry(Arc::clone(&s)).or_insert(next);
                        if code == next {
                            dict.push(Arc::clone(&s));
                        }
                        by_ptr.insert(s.as_ptr(), code);
                        seen.push(s);
                        code
                    }
                }

match self {
            Self::Dict {
                dict,
                indices,
                valid,
                ..
            } => Column::Dict {
                dict,
                indices,
                valid: Bitmap::from_bools(valid.into_iter()),
            },
            Self::Str {
                offsets,
                data,
                valid,
            } => Column::Str {
                offsets,
                data,
                valid: Bitmap::from_bools(valid.into_iter()),
            },
        }

match page {
                DictTestPage::Codes(codes) => {
                    let body = encode_dictionary_indices(codes, bit_width);
                    let header = build_dictionary_encoded_data_page_header(
                        codes.len() as i32,
                        body.len() as i32,
                    );
                    num_rows += codes.len() as i64;
                    (header, body)
                }
                DictTestPage::Plain(body, n) => {
                    num_rows += i64::from(*n);
                    (build_page_header(*n, body.len() as i32), body.to_vec())
                }
            }

match rg.read_decimal_column(0) {
            Err(FileError::InvalidMetadata { field, value }) => {
                assert_eq!(field, "DECIMAL fixed_len_byte_array length");
                assert_eq!(value, 17);
            }
            other => panic!("expected InvalidMetadata, got {other:?}"),
        }

match page_size("compressed_page_size", -1) {
            Err(FileError::InvalidMetadata { field, value }) => {
                assert_eq!(field, "compressed_page_size");
                assert_eq!(value, -1);
            }
            other => panic!("expected InvalidMetadata, got {other:?}"),
        }

match self {
            ReadError::Encoding(e) => write!(f, "{e}"),
            ReadError::UnexpectedEof => write!(f, "unexpected end of page data"),
            ReadError::InvalidValueCount(n) => write!(f, "invalid page value count: {n}"),
            ReadError::InvalidUtf8 => write!(f, "BYTE_ARRAY value is not valid UTF-8"),
            ReadError::DictionaryIndexOutOfRange(i) => {
                write!(f, "dictionary index {i} out of range")
            }
            ReadError::UnsupportedNestedPhysicalType(t) => {
                write!(f, "unsupported physical type in a nested column: {t:?}")
            }
        }

match physical_type {
        PhysicalType::Int32 => Ok(LeafScalar::Int32(read_plain_i32(buf)?)),
        PhysicalType::Int64 => Ok(LeafScalar::Int64(read_plain_i64(buf)?)),
        PhysicalType::Float => Ok(LeafScalar::Float(read_plain_f32(buf)?)),
        PhysicalType::Double => Ok(LeafScalar::Double(read_plain_f64(buf)?)),
        PhysicalType::ByteArray => Ok(LeafScalar::Str(read_plain_string(buf)?.into())),
        PhysicalType::Boolean => {
            let byte = *buf.first().ok_or(ReadError::UnexpectedEof)?;
            let bit = (byte >> (*bit_pos % 8)) & 1;
            *bit_pos = bit_pos.checked_add(1).ok_or(ReadError::UnexpectedEof)?;
            if (*bit_pos).is_multiple_of(8) {
                *buf = buf.get(1..).ok_or(ReadError::UnexpectedEof)?;
            }
            Ok(LeafScalar::Bool(bit == 1))
        }
        other => Err(ReadError::UnsupportedNestedPhysicalType(other)),
    }

match read_plain_scalar(&mut buf, PhysicalType::Boolean, &mut bit_pos).unwrap() {
                LeafScalar::Bool(b) => bits.push(b),
                other => panic!("expected a boolean, got {other:?}"),
            }

match build_node(schema, idx, def_level, rep_level, child_depth) {
                Some(child) => children.push(child),
                None => break,
            }

match self {
            ThriftError::UnexpectedEof => write!(f, "unexpected end of input"),
            ThriftError::InvalidVarint => write!(f, "varint too long"),
            ThriftError::InvalidLength(n) => write!(f, "length or size out of range: {n}"),
            ThriftError::UnknownType(t) => write!(f, "unknown thrift compact type: 0x{t:02x}"),
            ThriftError::DepthExceeded => {
                write!(f, "thrift values nested deeper than {MAX_DEPTH} levels")
            }
        }

match bool_value {
                Some(v) => Ok(Value::Bool(v)),
                None => Ok(Value::Bool(self.read_byte()? == CTYPE_BOOLEAN_TRUE)),
            }

match ctype {
                CTYPE_BOOLEAN_TRUE => Some(true),
                CTYPE_BOOLEAN_FALSE => Some(false),
                _ => None,
            }

match nibble {
        0x01 => Ok(CTYPE_BOOLEAN_TRUE), // bool element; value bit follows as a real byte via read_bool path
        CTYPE_BYTE | CTYPE_I16 | CTYPE_I32 | CTYPE_I64 | CTYPE_DOUBLE | CTYPE_BINARY
        | CTYPE_LIST | CTYPE_SET | CTYPE_MAP | CTYPE_STRUCT => Ok(nibble),
        other => Err(ThriftError::UnknownType(other)),
    }

match &fields[0].1 {
            Value::Struct(inner_fields) => {
                assert_eq!(inner_fields, &vec![(1, Value::Bool(true))]);
            }
            other => panic!("expected nested struct, got {other:?}"),
        }

match &fields[0].1 {
            Value::Map(entries) => {
                assert_eq!(entries.len(), 1);
                assert_eq!(entries[0].0.as_str(), Some("a"));
                assert_eq!(entries[0].1, Value::I32(1));
            }
            other => panic!("expected map, got {other:?}"),
        }

match self {
            WriteError::Io(e) => write!(f, "parquet write: {e}"),
            WriteError::Encode(e) => write!(f, "parquet metadata: {e}"),
            WriteError::InvalidSchema(why) => write!(f, "invalid parquet schema: {why}"),
            WriteError::InvalidOptions(why) => write!(f, "invalid parquet writer options: {why}"),
            WriteError::ColumnCount { expected, found } => {
                write!(f, "batch has {found} columns, schema has {expected}")
            }
            WriteError::TypeMismatch { column } => {
                write!(f, "column '{column}': values do not match the column type")
            }
            WriteError::LengthMismatch {
                column,
                expected,
                found,
            } => write!(f, "column '{column}': {found} values, expected {expected}"),
            WriteError::NullInRequired { column } => {
