            let [b0, ..] = bytes;
            let mut v: i64 = 0;
            for byte in bytes {
                v = (v << 8) | byte as i64;
            }
            if b0 & 0x80 != 0 {
                v = v.wrapping_sub(1 << 48); // sign-extend 48-bit; magnitude is tiny relative to i64
            }
            Ok((Value::Integer(v), 6))
        }
        6 => {
            let b = take_array(buf, pos)?;
            Ok((Value::Integer(i64::from_be_bytes(b)), 8))
        }
        7 => {
            let b = take_array(buf, pos)?;
            let value = f64::from_be_bytes(b);
