                MixedValue::Int(_) | MixedValue::Float(_) | MixedValue::Bool(_) => None,
            }

match acc {
            None => (*v, *v),
            Some((lo, hi)) => (lo.min(*v), hi.max(*v)),
        }

match col {
        FieldColumn::Dict { dict, indices } => {
            let mut idx = indices.clone();
            idx.extend(std::iter::repeat_n(None, pad(idx.len())));
            OwnedColumn::Dict {
                dict: dict.iter().map(|s| Arc::<str>::from(*s)).collect(),
                indices: idx,
            }
        }
        FieldColumn::Str(strs) => {
            let mut spans: Vec<Option<Span>> = strs
                .iter()
                .map(|s| s.and_then(|s| span_in(bytes, s.as_bytes())))
                .collect();
            spans.extend(std::iter::repeat_n(None, pad(spans.len())));
            OwnedColumn::Str(spans)
        }
        FieldColumn::Int(v) => {
            let mut v = v.clone();
            v.extend(std::iter::repeat_n(None, pad(v.len())));
            OwnedColumn::Int(v)
        }
        FieldColumn::Float(v) => {
            let mut v = v.clone();
            v.extend(std::iter::repeat_n(None, pad(v.len())));
            OwnedColumn::Float(v)
        }
        FieldColumn::Bool(v) => {
            let mut v = v.clone();
            v.extend(std::iter::repeat_n(None, pad(v.len())));
            OwnedColumn::Bool(v)
        }
        FieldColumn::Mixed(values) => {
            let mut v: Vec<Option<MixedValue>> = values
                .iter()
                .map(|value| {
                    value.and_then(|value| match value {
                        FieldValue::Str(s) => span_in(bytes, s.as_bytes()).map(MixedValue::Str),
                        FieldValue::Int(i) => Some(MixedValue::Int(i)),
                        FieldValue::Float(f) => Some(MixedValue::Float(f)),
                        FieldValue::Bool(b) => Some(MixedValue::Bool(b)),
                    })
                })
                .collect();
            v.extend(std::iter::repeat_n(None, pad(v.len())));
            OwnedColumn::Mixed(v)
        }
    }

match value {
                        FieldValue::Str(s) => span_in(bytes, s.as_bytes()).map(MixedValue::Str),
                        FieldValue::Int(i) => Some(MixedValue::Int(i)),
                        FieldValue::Float(f) => Some(MixedValue::Float(f)),
                        FieldValue::Bool(b) => Some(MixedValue::Bool(b)),
                    }

match std::str::from_utf8(line) {
            Ok(s) => s,
            Err(_) => {
                // Non-UTF8 line: store raw only
                batch.push_line(line, None, None, None, None);
                return;
            }
        }

match self.parse_pri(line_str) {
            Some(p) => p,
            None => {
                // No PRI: store as-is
                batch.push_line(line, None, None, None, Some(line_str));
                return;
            }
        }

match day_str.and_then(|d| d.parse().ok()) {
            Some(d) if (1..=31).contains(&d) => d,
            _ => return (None, s),
        }

match time_str.and_then(|t| self.parse_time(t)) {
            Some(t) => t,
            None => return (None, s),
        }

match s.find(char::is_whitespace) {
            Some(i) => {
                let word = s.get(..i).unwrap_or("");
                let rest = s.get(i..).unwrap_or("").trim_start();
                (Some(word), rest)
            }
            None => (Some(s), ""),
        }

match batch.fields.get("tag") {
            Some(crate::storage::stream::FieldColumn::Dict { dict, .. }) => {
                assert_eq!(dict.as_slice(), ["nginx"]);
            }
            other => panic!("{other:?}"),
        }

match clocks.iter_mut().find(|(id, _)| *id == me) {
        Some((_, slot)) => *slot = ns,
        None => clocks.push((me, ns)),
    }

match lit {
            Literal::Int(n) => Value::Int(n),
            Literal::Float(n) => Value::Float(n),
            Literal::Str(s) => Value::Str(s),
        }

match collation {
        Collation::Binary => a.as_bytes().cmp(b.as_bytes()),
        Collation::NoCase => a
            .as_bytes()
            .iter()
            .map(u8::to_ascii_lowercase)
            .cmp(b.as_bytes().iter().map(u8::to_ascii_lowercase)),
        Collation::RTrim => {
            let a = a.trim_end_matches(' ');
            let b = b.trim_end_matches(' ');
            a.as_bytes().cmp(b.as_bytes())
        }
    }

match other {
            AccColumn::Values(_) => AccColumn::Values(Vec::with_capacity(capacity)),
            AccColumn::Ints { .. } => AccColumn::Ints {
                data: Vec::with_capacity(capacity),
                nulls: Vec::with_capacity(capacity),
            },
            AccColumn::Strs { .. } => AccColumn::Strs {
                codes: Vec::with_capacity(capacity),
                strings: Interner::default(),
            },
        }

match self {
            AccColumn::Values(values) => values.len(),
            AccColumn::Ints { data, .. } => data.len(),
            AccColumn::Strs { codes, .. } => codes.len(),
        }

match self {
            AccColumn::Values(values) => values.get(g).cloned().unwrap_or(Value::Null),
            AccColumn::Ints { data, nulls } => match (data.get(g), nulls.get(g)) {
                (Some(&v), Some(false)) => Value::Int(v),
                _ => Value::Null,
            },
            AccColumn::Strs { codes, strings } => codes
                .get(g)
                .and_then(|&c| strings.get(c))
                .map_or(Value::Null, |s| Value::Str(s.to_string().into())),
        }

match self {
            AccColumn::Values(values) => values
                .get(g)
                .map_or_else(|| hash_one_value(&Value::Null), hash_one_value),
            AccColumn::Ints { data, nulls } => match (data.get(g), nulls.get(g)) {
                (Some(&v), Some(false)) => hash_one_value(&Value::Int(v)),
                _ => hash_one_value(&Value::Null),
            },
            AccColumn::Strs { codes, strings } => {
                strings.hash(codes.get(g).copied().unwrap_or(NULL_CODE))
            }
        }

match (self, v) {
            (AccColumn::Values(values), _) => values.get(g) == Some(v),
            (AccColumn::Ints { data, nulls }, Value::Int(x)) => {
                nulls.get(g) == Some(&false) && data.get(g) == Some(x)
            }
            (AccColumn::Ints { nulls, .. }, Value::Null) => nulls.get(g) == Some(&true),
            (AccColumn::Strs { codes, strings }, Value::Str(s)) => codes
                .get(g)
                .and_then(|&c| strings.get(c))
                .is_some_and(|t| t == s.as_ref()),
            (AccColumn::Strs { codes, .. }, Value::Null) => codes.get(g) == Some(&NULL_CODE),
            _ => false,
        }

match (self, other) {
            (
                AccColumn::Ints { data, nulls },
                AccColumn::Ints {
                    data: od,
                    nulls: on,
                },
            ) => {
                let null = nulls.get(g);
                null.is_some()
                    && null == on.get(r)
                    && (null == Some(&true) || data.get(g) == od.get(r))
            }
            (
                AccColumn::Strs { codes, strings },
                AccColumn::Strs {
                    codes: oc,
                    strings: os,
                },
            ) => match (codes.get(g), oc.get(r)) {
                (Some(&NULL_CODE), Some(&NULL_CODE)) => true,
                (Some(&a), Some(&b)) if a != NULL_CODE && b != NULL_CODE => {
                    strings.get(a).is_some() && strings.get(a) == os.get(b)
                }
                _ => false,
            },
            _ => self.eq_value(g, &other.value(r)),
        }

match (codes.get(g), oc.get(r)) {
                (Some(&NULL_CODE), Some(&NULL_CODE)) => true,
                (Some(&a), Some(&b)) if a != NULL_CODE && b != NULL_CODE => {
                    strings.get(a).is_some() && strings.get(a) == os.get(b)
                }
                _ => false,
            }

match (&mut *self, v) {
            (AccColumn::Values(values), _) => {
                values.push(v.clone());
                true
            }
            (AccColumn::Ints { data, nulls }, Value::Int(x)) => {
                data.push(*x);
                nulls.push(false);
                true
            }
            (AccColumn::Ints { data, nulls }, Value::Null) => {
                data.push(0);
                nulls.push(true);
                true
            }
            (AccColumn::Strs { codes, strings }, Value::Str(s)) => match strings.code(s) {
                Some(code) => {
                    codes.push(code);
                    true
                }
                None => false,
            },
            (AccColumn::Strs { codes, .. }, Value::Null) => {
                codes.push(NULL_CODE);
                true
            }
            _ => false,
        }

match strings.code(s) {
                Some(code) => {
                    codes.push(code);
                    true
                }
                None => false,
            }

match (&mut *self, other) {
            (
                AccColumn::Ints { data, nulls },
                AccColumn::Ints {
                    data: od,
                    nulls: on,
                },
            ) => {
                data.push(od.get(r).copied().unwrap_or(0));
                nulls.push(on.get(r).copied().unwrap_or(true));
            }
            (AccColumn::Values(values), AccColumn::Values(ov)) => {
                values.push(ov.get(r).cloned().unwrap_or(Value::Null));
            }
            _ => self.push_value(&other.value(r)),
        }

match self {
            AccColumn::Values(values) => values.swap(i, j),
            AccColumn::Ints { data, nulls } => {
                data.swap(i, j);
                nulls.swap(i, j);
            }
            AccColumn::Strs { codes, .. } => codes.swap(i, j),
        }

match self {
            AccColumn::Values(values) => values,
            typed => (0..typed.len()).map(|g| typed.value(g)).collect(),
        }

match (self, other) {
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Null, Value::Null) => true,
            (Value::Map(a), Value::Map(b)) => a == b,
            (Value::List(a), Value::List(b)) => a == b,
            (Value::Bytes(a), Value::Bytes(b)) => a == b,
            (
                Value::Decimal {
                    unscaled: a,
                    scale: sa,
                },
                Value::Decimal {
                    unscaled: b,
                    scale: sb,
                },
            ) => decimal_canonical(*a, *sa) == decimal_canonical(*b, *sb),
            _ => false,
        }

match (a2, b2) {
        (Some(x), Some(y)) => x.cmp(&y),
        _ => decimal_to_f64(a, sa).total_cmp(&decimal_to_f64(b, sb)),
    }

match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Float(x), Value::Float(y)) => x.total_cmp(y),
        (Value::Int(x), Value::Float(y)) => as_float(*x).total_cmp(y),
        (Value::Float(x), Value::Int(y)) => x.total_cmp(&as_float(*y)),
        (
            Value::Decimal {
                unscaled: x,
                scale: sx,
            },
            Value::Decimal {
                unscaled: y,
                scale: sy,
            },
        ) => decimal_cmp(*x, *sx, *y, *sy),
        (Value::Decimal { unscaled, scale }, Value::Int(i)) => {
            decimal_cmp(*unscaled, *scale, i128::from(*i), 0)
        }
        (Value::Int(i), Value::Decimal { unscaled, scale }) => {
            decimal_cmp(i128::from(*i), 0, *unscaled, *scale)
        }
        (Value::Decimal { unscaled, scale }, Value::Float(y)) => {
            decimal_to_f64(*unscaled, *scale).total_cmp(y)
        }
        (Value::Float(x), Value::Decimal { unscaled, scale }) => {
            x.total_cmp(&decimal_to_f64(*unscaled, *scale))
        }
        _ => return None,
    }

match self {
            Value::Int(v) => write!(f, "{v}"),
            Value::Float(v) => write!(f, "{v}"),
            Value::Bool(v) => write!(f, "{v}"),
            Value::Str(v) => write!(f, "{v}"),
            Value::Null => write!(f, "NULL"),
            // A sketch partial is never shown; its size is all there is to say.
            Value::Bytes(bytes) => write!(f, "<sketch {} bytes>", bytes.len()),
            Value::Decimal { unscaled, scale } => {
                f.write_str(&crate::value::format_decimal(*unscaled, *scale))
            }
            // As DuckDB prints a map: `{a=1, b=NULL}`.
            Value::Map(entries) => {
                write!(f, "{{")?;
                for (i, (k, v)) in entries.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    match v {
                        Some(v) => write!(f, "{k}={v}")?,
                        None => write!(f, "{k}=NULL")?,
                    }
                }
                write!(f, "}}")
            }
            // A JSON array: `["a",null]`.
            Value::List(items) => {
                write!(f, "[")?;
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, ",")?;
                    }
                    match item {
                        Some(s) => write_json_string(f, s)?,
                        None => write!(f, "null")?,
                    }
                }
                write!(f, "]")
            }
        }

match v {
                        Some(v) => write!(f, "{k}={v}")?,
                        None => write!(f, "{k}=NULL")?,
                    }

match item {
                        Some(s) => write_json_string(f, s)?,
                        None => write!(f, "null")?,
                    }

match self {
            Value::Int(v) => Some(*v as f64),
            Value::Float(v) => Some(*v),
            Value::Decimal { unscaled, scale } => Some(decimal_to_f64(*unscaled, *scale)),
            _ => None,
        }

match s {
            ValueSource::Probe(r) => Some(*r),
            ValueSource::Payload(_) => None,
        }

match self {
            Opcode::LoadColumn { .. }
            | Opcode::LoadConst { .. }
            | Opcode::Scan
            | Opcode::ScanSource(_)
            | Opcode::NextSegment { .. }
            | Opcode::Halt
            | Opcode::Limit { .. }
            | Opcode::Sort { .. }
            | Opcode::Combine { .. } => {}
            Opcode::Map { a, b, .. } => out.extend([*a, *b]),
            Opcode::Filter { predicate } => out.push(*predicate),
            Opcode::Reduce { src, .. } => out.extend(src),
            Opcode::GroupReduce { group_by, aggs, .. } => {
                out.extend(group_by.iter());
                out.extend(aggs.iter().filter_map(|(_, src)| *src));
            }
            Opcode::HashBuild {
                key_cols,
                payload_cols,
                ..
            } => {
                out.extend(key_cols.iter());
                out.extend(payload_cols.iter());
            }
            Opcode::HashProbe { key_cols, .. } => out.extend(key_cols.iter()),
            Opcode::Unnest { src, .. } => out.push(*src),
            Opcode::HashProbeGroupReduce {
                key_cols,
                group_by,
                aggs,
                ..
            } => {
                out.extend(key_cols.iter());
                out.extend(group_by.iter().filter_map(|(s, _)| source(s)));
                out.extend(aggs.iter().filter_map(|(_, s)| s.as_ref().and_then(source)));
            }
            Opcode::Window {
                arg,
                partition_by,
                order_by,
                ..
            } => {
                out.extend(arg);
                out.extend(partition_by.iter());
                out.extend(order_by.iter().map(|(r, _)| *r));
            }
            Opcode::Emit { registers } => out.extend(registers.iter()),
            Opcode::Call { args, .. } => out.extend(args.iter()),
            Opcode::InList { src, .. } => out.push(*src),
            Opcode::Select {
                cond, then, else_, ..
            } => {
                out.push(*cond);
                for branch in [then, else_] {
                    out.extend(branch.inputs.iter());
                    branch.ops.iter().for_each(|o| o.read_registers(out));
                }
            }
        }

match v {
        Value::Int(i) => crate::value::Value::Integer(*i),
        Value::Float(f) => crate::value::Value::Real(*f),
        Value::Bool(b) => crate::value::Value::Integer(i64::from(*b)),
        Value::Str(s) => crate::value::Value::Text(s.as_ref().into()),
        Value::Null => crate::value::Value::Null,
        // The row functions have no map type: its rendered text.
        Value::Map(_) | Value::List(_) => crate::value::Value::Text(v.to_string().into()),
        // A sketch partial never reaches a row function.
        Value::Bytes(_) => crate::value::Value::Null,
        // SQLite reads a DECIMAL as REAL (its affinity), so the row
        // functions see the nearest float.
        Value::Decimal { unscaled, scale } => {
            crate::value::Value::Real(decimal_to_f64(*unscaled, *scale))
        }
    }

match v {
        crate::value::Value::Null | crate::value::Value::Blob(_) => Value::Null,
        crate::value::Value::Integer(i) => Value::Int(i),
        crate::value::Value::Real(f) => Value::Float(f),
        crate::value::Value::Text(s) => Value::Str(s.to_string().into()),
    }

match common {
                    None => common = Some(kind),
                    Some(prev) if prev == kind => {}
                    Some(prev) => match prev.common(kind) {
                        Some(next) => {
                            mixed = true;
                            common = Some(next);
                        }
                        None => return Ok(()),
                    },
                }

match prev.common(kind) {
                        Some(next) => {
                            mixed = true;
                            common = Some(next);
                        }
                        None => return Ok(()),
                    }

match Arc::try_unwrap(shared) {
                    Ok(owned) if column.is_empty() => *column = owned,
                    Ok(owned) => column.extend(owned),
                    Err(shared) => column.extend(shared.iter().cloned()),
                }

match op {
                Opcode::Map {
                    op: MapOp::IsNull | MapOp::IsNotNull,
                    ..
                } => {}
                op => op.read_registers(&mut read),
            }

match op {
                Opcode::Unnest { src, .. } => unnested.push(*src),
                op => op.read_registers(&mut read),
            }

match opcodes.as_slice() {
                [combine @ Opcode::Combine { .. }] => Some((Some(*combine), None, None)),
                [combine @ Opcode::Combine { .. }, sort @ Opcode::Sort { .. }] => {
                    Some((Some(*combine), Some(*sort), None))
                }
                [combine @ Opcode::Combine { .. }, limit @ Opcode::Limit { .. }] => {
                    Some((Some(*combine), None, Some(*limit)))
                }
                [combine @ Opcode::Combine { .. }, sort @ Opcode::Sort { .. }, limit @ Opcode::Limit { .. }] => {
                    Some((Some(*combine), Some(*sort), Some(*limit)))
                }
                _ => None,
            }

match vm.group_fold.take() {
            Some(state) if state.folded => fold = Some((first, state)),
            // This slice's key is not codes under the fold's dictionary:
            // hand on what the fold holds, then this slice's own groups.
            state => {
                if let Some(state) = state.filter(|s| s.adopted) {
                    sink(first, finish_dict_fold(batch, state, body, emit)?)?;
                }
                vm.execute(&slice, emit)?;
                sink(start, vm.take_output())?;
            }
        }

match (matches!(a, Value::Null), matches!(b, Value::Null)) {
        (true, true) => Ordering::Equal,
        (true, false) => Ordering::Greater,
        (false, true) => Ordering::Less,
        (false, false) => {
            let decimal = matches!(a, Value::Decimal { .. }) || matches!(b, Value::Decimal { .. });
            let ord = match (a.as_f64(), b.as_f64()) {
                // A decimal compares exactly (#632), never through f64 or
                // as text.
                (Some(_), Some(_)) if decimal => numeric_cmp(a, b).unwrap_or(Ordering::Equal),
                (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(Ordering::Equal),
                // #266: compare `Str`/`Str` directly -- `Value`'s `Display`
                // prints a `Str`'s contents verbatim (no quoting), so this
                // is byte-identical to the `to_string()` fallback below
                // without the two allocations.
                _ => match (a, b) {
                    (Value::Str(x), Value::Str(y)) => x.cmp(y),
                    _ => a.to_string().cmp(&b.to_string()),
                },
            };
            // ORDER BY direction flips the comparison, not the sort itself.
            if descending {
                ord.reverse()
            } else {
                ord
            }
        }
    }

match (a.as_f64(), b.as_f64()) {
                // A decimal compares exactly (#632), never through f64 or
                // as text.
                (Some(_), Some(_)) if decimal => numeric_cmp(a, b).unwrap_or(Ordering::Equal),
                (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(Ordering::Equal),
                // #266: compare `Str`/`Str` directly -- `Value`'s `Display`
                // prints a `Str`'s contents verbatim (no quoting), so this
                // is byte-identical to the `to_string()` fallback below
                // without the two allocations.
                _ => match (a, b) {
                    (Value::Str(x), Value::Str(y)) => x.cmp(y),
                    _ => a.to_string().cmp(&b.to_string()),
                },
            }

match (a.get(col), b.get(col)) {
            (Some(x), Some(y)) => compare_for_order(x, y, descending),
            _ => std::cmp::Ordering::Equal,
        }

match op {
            Opcode::LoadColumn { reg: r, column } if *r == reg => Some(column.to_string()),
            _ => None,
        }

match op {
            Opcode::LoadColumn { column, .. } => Some(column.to_string()),
            _ => None,
        }

match op {
            Opcode::LoadColumn { column, .. } => key_columns.iter().any(|k| k == column.as_ref()),
            _ => false,
        }

match segment.gather_at(&plan.deferred, &positions) {
        Some(gathered) => gathered?,
        // No positional gather: a segment whose `load_columns` is the
        // default full `load()` already holds the deferred columns, so
        // gather from that batch in memory rather than loading it again
        // (measured: a second load doubled the parity `order_by` time
        // for such segments). Only a segment that served a real subset
        // but cannot gather falls back to the eager scan.
        None if plan.deferred.iter().all(|name| {
            batch.columns.contains_key(name) || batch.typed_columns.contains_key(name)
        }) =>
        {
            gather_in_memory(&batch, &plan.deferred, &positions)
        }
        None => return scan_segment_eager(segment, program, spec),
    }

match survivors {
            Some(s) => s.get(ordinal).copied(),
            None => u32::try_from(ordinal).ok(),
        }

match (bound_of(a), bound_of(b)) {
        (None, None) => Ordering::Equal,
        (None, Some(_)) => Ordering::Less,
        (Some(_), None) => Ordering::Greater,
        (Some(x), Some(y)) => compare_for_order(x, y, spec.descending),
    }

match &plan {
            Some(plan) => scan_segment_late(segment, program, plan, spec)?,
            None => scan_segment_eager(segment, program, spec)?,
        }

match self {
            VmError::UnknownColumn { opcode, column } => {
                write!(f, "{opcode}: unknown column: {column}")
            }
            VmError::UnknownRegister { opcode, register } => {
                write!(f, "{opcode}: unknown register: {register}")
            }
            VmError::RegisterLengthMismatch { opcode } => {
                write!(f, "{opcode}: register length mismatch")
            }
            VmError::UnknownJoinTable { opcode, table } => {
                write!(f, "{opcode}: unknown join table: {table}")
            }
            VmError::StepLimitExceeded { opcode, limit } => {
                write!(f, "{opcode}: exceeded step limit of {limit}")
            }
            VmError::UnsupportedOp { opcode, op } => {
                write!(f, "{opcode}: no dispatch for {op}")
            }
            VmError::MissingWindowArgument { opcode, func } => {
                write!(f, "{opcode}: {func:?} requires an argument register")
            }
            VmError::MalformedProgram { opcode, reason } => {
                write!(f, "{opcode}: malformed program: {reason}")
            }
            VmError::SegmentLoad { reason } => write!(f, "segment load failed: {reason}"),
            VmError::NotStreamable { reason } => write!(f, "cannot stream this program: {reason}"),
            VmError::IntegerOverflow { opcode } => write!(f, "{opcode}: integer overflow"),
            VmError::DecimalOverflow { opcode } => {
