match lhs {
            CompareOperand::Const(c) => compare_with(op, len, &ConstRows(c), &rhs),
            CompareOperand::Int(column) => compare_with(op, len, &IntRows(column), &rhs),
            CompareOperand::Float(column) => compare_with(op, len, &FloatRows(column), &rhs),
        }

match kleene(op, x, y) {
                Some(truth) => data.push(truth),
                None => {
                    data.push(false);
                    valid.set(i, false);
                }
            }

match item {
                Value::Str(s) => {
                    set.insert(s.as_ref());
                }
                Value::Null => has_null = true,
                _ => return None,
            }

match column.as_ref() {
            Column::Str {
                offsets,
                data: text_data,
                valid: text_valid,
            } => {
                for i in 0..len {
                    let text = offsets
                        .get(i)
                        .zip(offsets.get(i.saturating_add(1)))
                        .and_then(|(&lo, &hi)| text_data.get(lo as usize..hi as usize));
                    match text {
                        Some(text) if text_valid.get(i) => push(i, answer(set.contains(text))),
                        _ => push(i, None),
                    }
                }
            }
            Column::Dict {
                dict,
                indices,
                valid: code_valid,
            } => {
                let hits: Vec<Option<bool>> = dict
                    .iter()
                    .map(|s| answer(set.contains(s.as_ref())))
                    .collect();
                for (i, &code) in indices.iter().enumerate() {
                    match hits.get(code as usize) {
                        Some(&value) if code_valid.get(i) => push(i, value),
                        _ => push(i, None),
                    }
                }
            }
            _ => return None,
        }

match text {
                        Some(text) if text_valid.get(i) => push(i, answer(set.contains(text))),
                        _ => push(i, None),
                    }

match hits.get(code as usize) {
                        Some(&value) if code_valid.get(i) => push(i, value),
                        _ => push(i, None),
                    }

match (a_col.as_ref(), b_col.as_ref()) {
            (
                Column::Int {
                    data: xs,
                    valid: x_valid,
                },
                Column::Int {
                    data: ys,
                    valid: y_valid,
                },
            ) if op != MapOp::Div => Some((xs, x_valid, ys, y_valid)),
            _ => None,
        }

match (column_num_at(a_col, i), column_num_at(b_col, i)) {
                    (Some((x, _)), Some((y, _))) => {
                        data.push(arith_op(op, x, y));
                        valid_bits.push(true);
                    }
                    _ => {
                        data.push(0.0);
                        valid_bits.push(false);
                    }
                }

match source.next_batch() {
            Some(b) => b,
            None => return Ok(QueryOutput::default()),
        }

match op {
                Opcode::NextSegment { loop_start } => match source.next_batch() {
                    Some(next) => {
                        batch = next;
                        // #265: a new segment's registers start over
                        // (`LoadColumn` re-loads full columns at the top
                        // of the loop body), so any selection pending
                        // from the previous segment is meaningless here.
                        self.selection = None;
                        self.selected_rows = None;
                        pc = *loop_start;
                    }
                    None => pc = pc.saturating_add(1),
                },
                Opcode::Halt => break,
                other => {
                    self.step(&batch, other)?;
                    pc = pc.saturating_add(1);
                }
            }

match source.next_batch() {
                    Some(next) => {
                        batch = next;
                        // #265: a new segment's registers start over
                        // (`LoadColumn` re-loads full columns at the top
                        // of the loop body), so any selection pending
                        // from the previous segment is meaningless here.
                        self.selection = None;
                        self.selected_rows = None;
                        pc = *loop_start;
                    }
                    None => pc = pc.saturating_add(1),
                }

match op {
            Opcode::LoadColumn { reg, column } => {
                if let Some(typed) = batch.typed_columns.get(column.as_ref()) {
                    // #482: no longer eagerly materializes into
                    // `registers` -- only `typed_registers` is populated
                    // here. `Vm::ensure_materialized` lazily builds the
                    // `Vec<Value>` copy, only when something actually
                    // reads this register that way (an opcode not yet
                    // ported to `Column` dispatch, or a typed fast-path
                    // miss) -- this is why a bare `SUM(amount)` (typed
                    // `Reduce`'s fast path never touches `registers` at
                    // all) no longer burns the cost of a copy nothing
                    // reads. `registers.remove` invalidates any stale
                    // materialization left over from a previous segment
                    // reusing this same register number (`NextSegment`
                    // doesn't clear `registers` between iterations).
                    self.registers.remove(reg);
                    self.typed_registers.insert(*reg, Arc::clone(typed));
                } else {
                    let values = batch.columns.get(column.as_ref()).ok_or_else(|| {
                        VmError::UnknownColumn {
                            opcode,
                            column: column.to_string(),
                        }
                    })?;
                    self.registers.insert(*reg, Arc::clone(values));
                    self.typed_registers.remove(reg);
                }
            }
            Opcode::LoadConst { reg, value } => {
                // As long as the live rows: a pending selection's base
                // (compacted with everything else when it resolves), or
                // the already-filtered row count -- not the batch's, which
                // a constant loaded after a `Map` resolved the selection
                // (`id * 3 - 1 ... WHERE`) would outgrow.
                let len = match &self.selection {
                    Some(selection) => selection.base_len,
                    None => self.selected_rows.unwrap_or(batch.num_rows),
                };
                // #681: one value, broadcast lazily by
                // `ensure_materialized` only if something reads it as rows.
                self.registers.remove(reg);
                self.typed_registers.remove(reg);
                self.take_const(*reg);
                self.const_registers.push((*reg, value.clone(), len));
            }
            Opcode::Map { dst, op, a, b } => {
                // #265: reads registers elementwise (no row-index
                // concept), so any pending selection must be resolved
                // (compacted) first rather than taught to this opcode.
                self.resolve_selection(opcode)?;
                if let Some(result) = self.dict_literal_compare(*op, *a, *b, opcode)? {
                    self.registers.insert(*dst, Arc::new(result));
                    self.typed_registers.remove(dst);
                } else if let Some(column) = self.typed_like(*op, *a, *b, opcode)? {
                    // #743: typed-only, like `LoadColumn` (#482) --
                    // `Filter` reads the `Bool` buffer directly, and
                    // `ensure_materialized` builds the `Value`s only
                    // for a reader that needs them.
                    self.registers.remove(dst);
                    self.typed_registers.insert(*dst, Arc::new(column));
                } else if let Some(column) = self
                    .typed_compare(*op, *a, *b)
                    .or_else(|| self.typed_bool_op(*op, *a, *b))
                {
                    // #748: typed-only, as `typed_like` above.
                    self.registers.remove(dst);
                    self.typed_registers.insert(*dst, Arc::new(column));
                } else if let Some(column) = self.typed_arithmetic(*op, *a, *b, opcode)? {
                    // #431: a genuine typed Column result -- also
                    // materialize into `registers` (same pattern as
                    // `LoadColumn`, #429) so a downstream un-migrated
                    // opcode keeps working unchanged.
                    let materialized: Vec<Value> =
                        (0..column.len()).map(|i| column.get(i)).collect();
                    self.registers.insert(*dst, Arc::new(materialized));
                    self.typed_registers.insert(*dst, Arc::new(column));
                } else {
                    self.ensure_materialized(*a);
                    self.ensure_materialized(*b);
                    let (a_vals, b_vals) = (self.reg(*a, opcode)?, self.reg(*b, opcode)?);
                    if a_vals.len() != b_vals.len() {
                        return Err(VmError::RegisterLengthMismatch { opcode });
                    }
                    let result: Vec<Value> = a_vals
                        .iter()
                        .zip(b_vals.iter())
                        .map(|(x, y)| apply_map_op(*op, x, y))
                        .collect::<Result<_>>()?;
                    self.registers.insert(*dst, Arc::new(result));
                    self.typed_registers.remove(dst);
                }
            }
            Opcode::Call { dst, name, args } => {
                // Elementwise, like `Map`: resolve any pending selection
                // first (see the comment on that arm).
                self.resolve_selection(opcode)?;
                for &a in args.iter() {
                    self.ensure_materialized(a);
                }
                let arg_regs: Vec<&[Value]> = args
                    .iter()
                    .map(|&a| self.reg(a, opcode))
                    .collect::<Result<_>>()?;
                // A call with no arguments (`list_value()`, #827) has the
                // filtered row count, as a constant does.
                let num_rows = arg_regs
                    .first()
                    .map_or(self.selected_rows.unwrap_or(batch.num_rows), |r| r.len());
                if arg_regs.iter().any(|r| r.len() != num_rows) {
                    return Err(VmError::RegisterLengthMismatch { opcode });
                }
                // #621: map functions read `Value::Map`, which the row
                // functions' values cannot carry.
                let result: Vec<Value> = if super::map_fns::is_map_function(name) {
                    super::map_fns::call_column(name, &arg_regs, num_rows)
                } else {
                    let mut call_args = vec![crate::value::Value::Null; arg_regs.len()];
                    let mut result = Vec::with_capacity(num_rows);
                    // The late-parse `json_extract` (#307) and
                    // `json_extract_string` (#839), not the row engine's
                    // sqlite3 ones.
                    let late_json_extract = name.eq_ignore_ascii_case("json_extract");
                    let late_json_string = name.eq_ignore_ascii_case("json_extract_string");
                    for row in 0..num_rows {
                        for (slot, reg) in call_args.iter_mut().zip(&arg_regs) {
                            *slot = to_scalar_value(&reg[row]);
                        }
                        let value = if late_json_extract {
                            crate::functions::late_json_extract(&call_args)
                        } else if late_json_string {
                            crate::functions::late_json_extract_string(&call_args)
                        } else {
                            crate::functions::call(name, &call_args)
                        }
                        .map_or(Value::Null, from_scalar_value);
                        result.push(value);
                    }
                    result
                };
                self.registers.insert(*dst, Arc::new(result));
            }
            Opcode::InList {
                dst,
                src,
                list,
                negated,
            } => {
                // Elementwise, like `Map`: resolve any pending selection
                // first (see the comment on that arm).
                self.resolve_selection(opcode)?;
                if let Some(column) = self.typed_in_list(*src, list, *negated) {
                    // Typed-only, as `typed_like`'s result (#743).
                    self.registers.remove(dst);
                    self.typed_registers.insert(*dst, Arc::new(column));
                } else {
                    self.ensure_materialized(*src);
                    let result = in_list_values(self.reg(*src, opcode)?, list, *negated)?;
                    self.registers.insert(*dst, Arc::new(result));
                    self.typed_registers.remove(dst);
                }
            }
            Opcode::Select {
                dst,
                cond,
                then,
                else_,
            } => {
                // Elementwise, like `Map`: resolve any pending selection
                // first (see the comment on that arm).
                self.resolve_selection(opcode)?;
                self.ensure_materialized(*cond);
                let (then_rows, else_rows): (Vec<usize>, Vec<usize>) = {
                    let cond_values = self.reg(*cond, opcode)?;
                    (0..cond_values.len()).partition(|&i| cond_values.get(i).is_some_and(as_bool))
                };
                let num_rows = then_rows.len().saturating_add(else_rows.len());
                let (then_values, then_kind) = self.run_branch(opcode, then, &then_rows)?;
                let (else_values, else_kind) = self.run_branch(opcode, else_, &else_rows)?;
                let kind = match (then_kind, else_kind) {
                    (Some(a), Some(b)) => Some(a.common(b).ok_or(VmError::BranchTypes {
                        opcode,
                        left: a.name(),
                        right: b.name(),
                    })?),
                    (kind, None) | (None, kind) => kind,
                };
                let result = merge_branches(
                    opcode,
                    num_rows,
                    (&then_rows, &then_values),
                    (&else_rows, &else_values),
                    kind,
                )?;
                self.registers.insert(*dst, Arc::new(result));
                self.typed_registers.remove(dst);
            }
            Opcode::Filter { predicate } => self.filter(opcode, predicate)?,
            Opcode::Reduce { func, src, dst } => self.reduce(batch, opcode, func, src, dst)?,
            Opcode::GroupReduce {
                group_by,
                aggs,
                agg_dst,
            } => self.group_reduce(batch, opcode, group_by, aggs, agg_dst)?,
            Opcode::HashBuild {
                key_cols,
                payload_cols,
                table,
            } => self.hash_build(opcode, key_cols, payload_cols, table)?,
            Opcode::HashProbe {
                key_cols,
                table,
                payload_dst,
                kind,
            } => self.hash_probe(opcode, key_cols, table, payload_dst, kind)?,
            Opcode::Unnest { src, dst } => self.unnest(opcode, *src, *dst)?,
            Opcode::HashProbeGroupReduce {
                key_cols,
                table,
                kind,
                group_by,
                aggs,
                agg_dst,
            } => self
                .hash_probe_group_reduce(opcode, key_cols, table, kind, group_by, aggs, agg_dst)?,
            Opcode::Window {
                func,
                arg,
                offset,
                partition_by,
                order_by,
                dst,
            } => self.window(
                batch,
                opcode,
                func,
                arg,
                offset,
                partition_by,
                order_by,
                dst,
            )?,
            Opcode::Emit { registers } => self.emit(opcode, registers)?,
            // Meaningful only as loop markers interpreted by `run` --
            // and `Combine`/`Sort`/`Limit` are the cross-segment
            // sequential phase applied once by `crate::vm::engine::run`,
            // never inside a single segment. `ScanSource` is likewise a
            // no-op here: resolving it into a `Batch` happens above the
            // per-segment `Vm`, in `crate::vm::engine` (#385) -- this
            // ticket (#384) only defines the opcode/type, no emitted
            // program references it yet.
            Opcode::Scan
            | Opcode::NextSegment { .. }
            | Opcode::Halt
            | Opcode::Combine { .. }
            | Opcode::Sort { .. }
            | Opcode::Limit { .. }
            | Opcode::ScanSource { .. } => {}
        }

match (then_kind, else_kind) {
                    (Some(a), Some(b)) => Some(a.common(b).ok_or(VmError::BranchTypes {
                        opcode,
                        left: a.name(),
                        right: b.name(),
                    })?),
                    (kind, None) | (None, kind) => kind,
                }

match self.typed_registers.get(predicate) {
            // #429: a typed Bool predicate register (e.g. loaded
            // straight from a sealed segment's Bool column) reads
            // its bitmap-backed buffer directly, skipping the
            // `Value::Bool(true)` match entirely.
            Some(column) => match column.as_ref() {
                Column::Bool { data, valid } => (0..data.len())
                    .map(|i| valid.get(i) && data.get(i).copied().unwrap_or(false))
                    .collect(),
                other => (0..other.len())
                    .map(|i| matches!(other.get(i), Value::Bool(true)))
                    .collect(),
            },
            None => {
                self.ensure_materialized(*predicate);
                self.reg(*predicate, opcode)?
                    .iter()
                    .map(|v| matches!(v, Value::Bool(true)))
                    .collect()
            }
        }

match self.selection.take() {
            Some(existing) => {
                if existing.base_len != base_len {
                    return Err(VmError::RegisterLengthMismatch { opcode });
                }
                existing.indices
            }
            // #110: size the surviving-index buffer to the actual
            // survivor count up front (not the pre-filter length)
            // -- at 50% selectivity on a 10M-row scan, over-
            // allocating by 2x is real peak-RSS waste for no
            // benefit (the excess capacity is never used).
            None => (0..u32::try_from(base_len).unwrap_or(u32::MAX)).collect(),
        }

match src {
            Some(reg) => {
                // #265: see the comment on `Map`'s same call. Also
                // clears `typed_registers` when it actually
                // resolves a selection, so the typed fast path
                // below only ever fires over an unfiltered (or
                // already-compacted) typed column -- never a
                // stale, wrong-length shadow.
                self.resolve_selection(opcode)?;
                let typed = self
                    .typed_registers
                    .get(reg)
                    .and_then(|column| typed_reduce_values(*func, column));
                match typed {
                    Some(result) => result?,
                    None => {
                        self.ensure_materialized(*reg);
                        reduce_values(*func, self.reg(*reg, opcode)?)?
                    }
                }
            }
            // #452/#474: bare `COUNT(*)` never reads register
            // contents, only the survivor count -- so unlike
            // every other `src`, it must NOT force
            // `resolve_selection`'s per-register compaction
            // (O(live registers x survivors), the dominant cost
            // at high selectivity per #474). Peek (don't take)
            // the pending selection's index count: another
            // `Reduce`/`Map` in the same SELECT list (e.g.
            // `count(*), sum(amt)`) still needs the selection
            // itself to compact its own source register.
            None => {
                let count = match &self.selection {
                    Some(selection) => selection.indices.len(),
                    None => self.selected_rows.unwrap_or(batch.num_rows),
                };
                reduce_count_star(*func, count)
            }
        }

match typed {
                    Some(result) => result?,
                    None => {
                        self.ensure_materialized(*reg);
                        reduce_values(*func, self.reg(*reg, opcode)?)?
                    }
                }

match (fold.as_mut(), dict_group_by.as_deref()) {
            (Some(f), Some(Column::Dict { dict, .. })) => f.adopt(dict, aggs.len()),
            _ => false,
        }

match &selection {
            Some(sel) => sel.base_len,
            None => match key_views
                .first()
                .map(KeyView::len)
                .or(int_group_by.as_ref().map(|c| c.len()))
                .or(dict_group_by.as_ref().map(|c| c.len()))
            {
                Some(len) => len,
                None => match aggs
                    .iter()
                    .find_map(|(_, src)| src.map(|reg| self.reg(reg, opcode).map(<[Value]>::len)))
                {
                    Some(len) => len?,
                    // `COUNT(*)` alone: no key or source column
                    // carries the row count, but every live
                    // register has the post-`Filter` length
                    // (RegisterLengthMismatch guards that), so any
                    // one of them is it; with no register at all
                    // nothing was filtered and the batch's own row
                    // count is exact.
                    None => self
                        .registers
                        .values()
                        .next()
                        .map_or(batch.num_rows, |v| v.len()),
                },
            },
        }

match key_views
                .first()
                .map(KeyView::len)
                .or(int_group_by.as_ref().map(|c| c.len()))
                .or(dict_group_by.as_ref().map(|c| c.len()))
            {
                Some(len) => len,
                None => match aggs
                    .iter()
                    .find_map(|(_, src)| src.map(|reg| self.reg(reg, opcode).map(<[Value]>::len)))
                {
                    Some(len) => len?,
                    // `COUNT(*)` alone: no key or source column
                    // carries the row count, but every live
                    // register has the post-`Filter` length
                    // (RegisterLengthMismatch guards that), so any
                    // one of them is it; with no register at all
                    // nothing was filtered and the batch's own row
                    // count is exact.
                    None => self
                        .registers
                        .values()
                        .next()
                        .map_or(batch.num_rows, |v| v.len()),
                },
            }

match aggs
                    .iter()
                    .find_map(|(_, src)| src.map(|reg| self.reg(reg, opcode).map(<[Value]>::len)))
                {
                    Some(len) => len?,
                    // `COUNT(*)` alone: no key or source column
                    // carries the row count, but every live
                    // register has the post-`Filter` length
                    // (RegisterLengthMismatch guards that), so any
                    // one of them is it; with no register at all
                    // nothing was filtered and the batch's own row
                    // count is exact.
                    None => self
                        .registers
                        .values()
                        .next()
                        .map_or(batch.num_rows, |v| v.len()),
                }

match int_group_by.as_deref() {
            Some(Column::Int { data, valid }) => Some((data.as_slice(), valid)),
            _ => None,
        }

match dict_group_by.as_deref() {
            Some(Column::Dict { indices, valid, .. }) if folding => match fold.as_mut() {
                Some(f) => {
                    let row_group = f.assign(indices, valid, num_rows, physical)?;
                    (row_group, f.keys.len(), Vec::new())
                }
                None => {
                    return Err(VmError::MalformedProgram {
                        opcode,
                        reason: "folding without a fold".to_string(),
                    })
                }
            },
            Some(Column::Dict {
                dict,
                indices,
                valid,
            }) => dict_group_by_single_column(dict, indices, valid, num_rows, physical),
            // #439/#440: hash column-wise (`hash_columns_by_row`, no
            // per-row key materialized), then probe by hash first on
            // a borrowed row view, only clone+allocate a
            // `Vec<Value>` key on a genuine new group -- the old
            // code built and cloned that `Vec` (plus its `String`s)
            // for every input row, even though nearly every row
            // lands in a group that already exists. `group_index`
            // buckets group ids by hash (collisions possible, so
            // each bucket is checked for an exact match) rather
            // than owning a `GroupKey` per entry.
            _ => match int_key {
                Some((data, valid)) => int_group_by_single_column(data, valid, num_rows, physical)?,
                None => group_by_key_views(&key_views, num_rows, physical)?,
            },
        }

match fold.as_mut() {
                Some(f) => {
                    let row_group = f.assign(indices, valid, num_rows, physical)?;
                    (row_group, f.keys.len(), Vec::new())
                }
                None => {
                    return Err(VmError::MalformedProgram {
                        opcode,
                        reason: "folding without a fold".to_string(),
                    })
                }
            }

match int_key {
                Some((data, valid)) => int_group_by_single_column(data, valid, num_rows, physical)?,
                None => group_by_key_views(&key_views, num_rows, physical)?,
            }

match fold.as_mut().filter(|_| folding) {
                Some(f) => {
                    let accs = &mut f.accs[i];
                    accs.resize(num_groups, RunningAgg::default());
                    accs
                }
                None => {
                    local = vec![RunningAgg::default(); num_groups];
                    &mut local
                }
            }

match src {
                // #603: the sketch takes every value as a `Value`, typed
                // column or not.
                Some(reg) if *func == AggFunc::ApproxCountDistinct => {
                    let values = self.reg(*reg, opcode)?;
                    if values.len() != base_len {
                        return Err(VmError::RegisterLengthMismatch { opcode });
                    }
                    for (row, group) in row_group.iter().enumerate() {
                        accs[*group].push_sketch(&values[physical(row)]);
                    }
                }
                // #817: an exact integer distinct count reads a typed `Int`
                // column straight from its packed `data`, anything else as
                // `Value`s (a non-integer is reported at finalize).
                Some(reg) if *func == AggFunc::ExactCountDistinct => {
                    let typed = self
                        .typed_registers
                        .get(reg)
                        .map(Arc::clone)
                        .filter(|c| c.len() == base_len);
                    if let Some(Column::Int { data, valid }) = typed.as_deref() {
                        for (row, group) in row_group.iter().enumerate() {
                            let p = physical(row);
                            if valid.get(p) {
                                accs[*group].push_set_i64(data[p]);
                            }
                        }
                    } else {
                        self.ensure_materialized(*reg);
                        let values = self.reg(*reg, opcode)?;
                        if values.len() != base_len {
                            return Err(VmError::RegisterLengthMismatch { opcode });
                        }
                        for (row, group) in row_group.iter().enumerate() {
                            accs[*group].push_set(&values[physical(row)]);
                        }
                    }
                }
                // #820: a string distinct count collects each group's
                // distinct strings, from a dictionary's codes or a
                // string column's bytes without a `Value` per row.
                Some(reg) if *func == AggFunc::ExactCountDistinctStr => {
                    let typed = self
                        .typed_registers
                        .get(reg)
                        .map(Arc::clone)
                        .filter(|c| c.len() == base_len);
                    match typed.as_deref() {
                        Some(Column::Dict {
                            dict,
                            indices,
                            valid,
                        }) => {
