        _ => Some(Value::Float(arith_op(op, x, y))),
    }

match v {
        Value::Int(i) => Some((i128::from(*i), 0)),
        Value::Decimal { unscaled, scale } => Some((*unscaled, *scale)),
        _ => None,
    }

match op {
        MapOp::Add => x.checked_add(y),
        MapOp::Sub => x.checked_sub(y),
        MapOp::Mul => x.checked_mul(y),
        _ => None,
    }

match op {
        MapOp::Mul => (u1.checked_mul(u2)?, s1.checked_add(s2)?),
        MapOp::Add | MapOp::Sub => {
            let scale = s1.max(s2);
            let l = u1.checked_mul(pow10(u32::from(scale.saturating_sub(s1)))?)?;
            let r = u2.checked_mul(pow10(u32::from(scale.saturating_sub(s2)))?)?;
            let sum = if op == MapOp::Add {
                l.checked_add(r)?
            } else {
                l.checked_sub(r)?
            };
            (sum, scale)
        }
        _ => return None,
    }

match v {
        Value::Null => None,
        other => Some(as_bool(other)),
    }

match (a, b) {
        (Some(x), _) | (_, Some(x)) if x == decided => Some(decided),
        (Some(_), Some(_)) => Some(!decided),
        _ => None,
    }

match self {
            CompareOperand::Int(column) | CompareOperand::Float(column) => Some(column.len()),
            CompareOperand::Const(_) => None,
        }

match self.0.as_ref() {
            Column::Int { data, valid } if valid.get(i) => data.get(i).map(|&x| int_as_f64(x)),
            _ => None,
        }

match self.0.as_ref() {
            Column::Float { data, valid } if valid.get(i) => data.get(i).copied(),
            _ => None,
        }

match rhs {
        CompareOperand::Const(c) => compare_rows(op, len, lhs, &ConstRows(*c)),
        CompareOperand::Int(column) => compare_rows(op, len, lhs, &IntRows(Arc::clone(column))),
        CompareOperand::Float(column) => compare_rows(op, len, lhs, &FloatRows(Arc::clone(column))),
    }

match (lhs.at(i), rhs.at(i)) {
            (Some(x), Some(y)) => data.push(compare_f64(op, x, y)),
            _ => {
                data.push(false);
                valid.set(i, false);
            }
        }

match column {
        Column::Int { data, valid } => {
            if !valid.get(i) {
                return None;
            }
            #[allow(
                clippy::cast_precision_loss,
                reason = "matches Value::as_f64's existing `*v as f64` widening for Int"
            )]
            data.get(i).map(|&x| (x as f64, true))
        }
        Column::Float { data, valid } => {
            if !valid.get(i) {
                return None;
            }
            data.get(i).map(|&x| (x, false))
        }
        _ => None,
    }

match (a, b) {
        (Value::Str(x), Value::Str(y)) => Some(x.cmp(y)),
        (Value::Bool(x), Value::Bool(y)) => Some(x.cmp(y)),
        // A decimal compares exactly (#632).
        (Value::Decimal { .. }, _) | (_, Value::Decimal { .. }) => numeric_cmp(a, b),
        _ => a.as_f64()?.partial_cmp(&b.as_f64()?),
    }

match cmp(MapOp::Eq, &a, &b) {
                Err(VmError::Conversion { to: t, .. }) => assert_eq!(t, to),
                other => panic!("{a:?} = {b:?}: {other:?}"),
            }

match side {
            Side::Column(column) => Opcode::LoadColumn {
                reg,
                column: column.into(),
            },
            Side::Literal(value) => Opcode::LoadConst { reg, value },
        }

match r {
                    Some(s) => {
                        let at = dict.iter().position(|d| &**d == *s).filter(|&at| at > 1);
                        let at = at.unwrap_or_else(|| {
                            dict.push((*s).into());
                            dict.len() - 1
                        });
                        indices.push(u32::try_from(at).unwrap());
                    }
                    None => indices.push(0),
                }

match &acc.extremes {
                    Extremes::Strs(values, _) => {
                        let mut v: Vec<String> = values.iter().map(|s| s.to_string()).collect();
                        v.sort();
                        v
                    }
                    _ => Vec::new(),
                }

match name {
            "part" => 0,
            "ord" => 1,
            "val" => 2,
            other => panic!("unexpected test column: {other}"),
        }

match &r[0] {
                Value::Int(v) => *v,
                other => panic!("expected Value::Int, got {other:?}"),
            }

match best {
                    Some(b) if agg_cmp(v, &b) != want => Some(b),
                    _ => Some(v.clone()),
                }

match acc {
                None => eq,
                Some(prev) => {
                    chain.push(Opcode::Map {
                        dst: eq + 1,
                        op: join,
                        a: prev,
                        b: eq,
                    });
                    eq + 1
                }
            }

match self {
            Column::Int { valid, .. }
            | Column::Float { valid, .. }
            | Column::Bool { valid, .. }
            | Column::Str { valid, .. }
            | Column::Dict { valid, .. }
            | Column::List { valid, .. } => valid.len(),
        }

match self {
            Column::Int { data, valid } => Column::Int {
                data: data.get(range).unwrap_or_default().to_vec(),
                valid: valid.slice(start, end),
            },
            Column::Float { data, valid } => Column::Float {
                data: data.get(range).unwrap_or_default().to_vec(),
                valid: valid.slice(start, end),
            },
            Column::Bool { data, valid } => Column::Bool {
                data: data.get(range).unwrap_or_default().to_vec(),
                valid: valid.slice(start, end),
            },
            // One copy of the slice's bytes, offsets rebased to it.
            Column::Str {
                offsets,
                data,
                valid,
            } => {
                let at = |i: usize| {
                    offsets
                        .get(i)
                        .and_then(|o| usize::try_from(*o).ok())
                        .unwrap_or(0)
                };
                let (lo, hi) = (at(start), at(end));
                let base = offsets.get(start).copied().unwrap_or(0);
                Column::Str {
                    offsets: offsets
                        .get(start..=end)
                        .unwrap_or_default()
                        .iter()
                        .map(|o| o.saturating_sub(base))
                        .collect(),
                    data: data.get(lo..hi).unwrap_or_default().to_string(),
                    valid: valid.slice(start, end),
                }
            }
            Column::List {
                offsets,
                elements,
                valid,
            } => {
                let at = |i: usize| {
                    offsets
                        .get(i)
                        .and_then(|o| usize::try_from(*o).ok())
                        .unwrap_or(0)
                };
                let (lo, hi) = (at(start), at(end));
                let base = offsets.get(start).copied().unwrap_or(0);
                Column::List {
                    offsets: offsets
                        .get(start..=end)
                        .unwrap_or_default()
                        .iter()
                        .map(|o| o.saturating_sub(base))
                        .collect(),
                    elements: Box::new(elements.slice(lo, hi.saturating_sub(lo))),
                    valid: valid.slice(start, end),
                }
            }
            Column::Dict {
                dict,
                indices,
                valid,
            } if dict.len() <= end.saturating_sub(start).saturating_mul(4) => Column::Dict {
                dict: dict.clone(),
                indices: indices.get(range).unwrap_or_default().to_vec(),
                valid: valid.slice(start, end),
            },
            // A dictionary large next to the slice: its strings, copied
            // once each, instead of the whole dictionary per slice.
            Column::Dict {
                dict,
                indices,
                valid,
            } => {
                let mut offsets = Vec::with_capacity(range.len().saturating_add(1));
                let mut data = String::new();
                offsets.push(0);
                for i in range {
                    if valid.get(i) {
                        let code = indices.get(i).and_then(|c| usize::try_from(*c).ok());
                        if let Some(s) = code.and_then(|c| dict.get(c)) {
                            data.push_str(s);
                        }
                    }
                    offsets.push(u32::try_from(data.len()).unwrap_or(u32::MAX));
                }
                Column::Str {
                    offsets,
                    data,
                    valid: valid.slice(start, end),
                }
            }
        }

match self {
            Column::Int { data, .. } => Column::Int {
                data: rows
                    .iter()
                    .map(|&r| data.get(r).copied().unwrap_or(0))
                    .collect(),
                valid,
            },
            Column::Float { data, .. } => Column::Float {
                data: rows
                    .iter()
                    .map(|&r| data.get(r).copied().unwrap_or(0.0))
                    .collect(),
                valid,
            },
            Column::Bool { data, .. } => Column::Bool {
                data: rows
                    .iter()
                    .map(|&r| data.get(r).copied().unwrap_or(false))
                    .collect(),
                valid,
            },
            Column::Dict { dict, indices, .. } if dict.len() <= rows.len().saturating_mul(4) => {
                Column::Dict {
                    dict: dict.clone(),
                    indices: rows
                        .iter()
                        .map(|&r| indices.get(r).copied().unwrap_or(0))
                        .collect(),
                    valid,
                }
            }
            Column::List { .. } => return self.take_list(rows),
            Column::Str { .. } | Column::Dict { .. } => {
                let mut offsets = Vec::with_capacity(rows.len().saturating_add(1));
                let mut data = String::new();
                offsets.push(0);
                for &r in rows {
                    if self.valid_at(r) {
                        match self {
                            Column::Str {
                                offsets: o,
                                data: d,
                                ..
                            } => {
                                let lo = o.get(r).and_then(|x| usize::try_from(*x).ok());
                                let hi = o
                                    .get(r.saturating_add(1))
                                    .and_then(|x| usize::try_from(*x).ok());
                                if let Some(s) = lo.zip(hi).and_then(|(lo, hi)| d.get(lo..hi)) {
                                    data.push_str(s);
                                }
                            }
                            Column::Dict { dict, indices, .. } => {
                                let code = indices.get(r).and_then(|c| usize::try_from(*c).ok());
                                if let Some(s) = code.and_then(|c| dict.get(c)) {
                                    data.push_str(s);
                                }
                            }
                            _ => {}
                        }
                    }
                    offsets.push(u32::try_from(data.len()).unwrap_or(u32::MAX));
                }
                Column::Str {
                    offsets,
                    data,
                    valid,
                }
            }
        }

match self {
                            Column::Str {
                                offsets: o,
                                data: d,
                                ..
                            } => {
                                let lo = o.get(r).and_then(|x| usize::try_from(*x).ok());
                                let hi = o
                                    .get(r.saturating_add(1))
                                    .and_then(|x| usize::try_from(*x).ok());
                                if let Some(s) = lo.zip(hi).and_then(|(lo, hi)| d.get(lo..hi)) {
                                    data.push_str(s);
                                }
                            }
                            Column::Dict { dict, indices, .. } => {
                                let code = indices.get(r).and_then(|c| usize::try_from(*c).ok());
                                if let Some(s) = code.and_then(|c| dict.get(c)) {
                                    data.push_str(s);
                                }
                            }
                            _ => {}
                        }

match self {
            Column::Int { valid, .. }
            | Column::Float { valid, .. }
            | Column::Bool { valid, .. }
            | Column::Str { valid, .. }
            | Column::Dict { valid, .. }
            | Column::List { valid, .. } => valid,
        }

match self {
            Column::Int { data, .. } => data.get(i).copied().map_or(Value::Null, Value::Int),
            Column::Float { data, .. } => data.get(i).copied().map_or(Value::Null, Value::Float),
            Column::Bool { data, .. } => data.get(i).copied().map_or(Value::Null, Value::Bool),
            Column::Str { offsets, data, .. } => {
                str_at(offsets, data, i).map_or(Value::Null, |s| Value::Str(s.into()))
            }
            Column::Dict { dict, indices, .. } => indices
                .get(i)
                .and_then(|&code| dict.get(usize::try_from(code).unwrap_or(usize::MAX)))
                .map_or(Value::Null, |s| Value::Str(s.to_string().into())),
            Column::List {
                offsets, elements, ..
            } => {
                let at = |i: usize| {
                    offsets
                        .get(i)
                        .and_then(|o| usize::try_from(*o).ok())
                        .unwrap_or(0)
                };
                let items = (at(i)..at(i.saturating_add(1)))
                    .map(|j| elements.shared_str(j))
                    .collect();
                Value::List(Arc::new(items))
            }
        }

match self {
            Column::Dict {
                dict,
                indices,
                valid,
            } if valid.get(i) => indices
                .get(i)
                .and_then(|&code| dict.get(usize::try_from(code).unwrap_or(usize::MAX)))
                .cloned(),
            Column::Str {
                offsets,
                data,
                valid,
            } if valid.get(i) => str_at(offsets, data, i).map(Arc::from),
            _ => None,
        }

match v {
                    Value::Float(f) => *f,
                    Value::Int(n) => *n as f64,
                    _ => 0.0,
                }

match part {
            AggPart::Avg(sum_i, count_i) => {
                for (i, op) in [(*sum_i, SlotOp::AvgSum), (*count_i, SlotOp::AvgCount)] {
                    let slot = ops.get_mut(i).ok_or_else(|| VmError::MalformedProgram {
                        opcode: "Combine",
                        reason: format!(
                            "AVG slot {i} is outside the {num_slots}-column emitted row"
                        ),
                    })?;
                    *slot = op;
                }
                cursor = count_i.saturating_add(1);
            }
            // No slot of its own (#496): both operands name slots another
            // part already claimed, so the cursor doesn't move.
            AggPart::Expr(..) => {}
            other => {
                if let Some(slot) = ops.get_mut(cursor) {
                    *slot = match other {
                        AggPart::GroupKey | AggPart::DistinctKey => SlotOp::Key,
                        AggPart::Sum | AggPart::Hidden(HiddenPart::Sum) => SlotOp::Sum,
                        AggPart::Count | AggPart::Hidden(HiddenPart::Count) => SlotOp::Count,
                        AggPart::Min | AggPart::Hidden(HiddenPart::Min) => SlotOp::Min,
                        AggPart::Max | AggPart::Hidden(HiddenPart::Max) => SlotOp::Max,
                        AggPart::ApproxCountDistinct => SlotOp::Sketch,
                        AggPart::ExactCountDistinct => SlotOp::IntSet,
                        AggPart::ExactCountDistinctStr => SlotOp::StrSet,
                        AggPart::Avg(..) | AggPart::Expr(..) => SlotOp::Key,
                    };
                }
                cursor = cursor.saturating_add(1);
            }
        }

match part {
        AggPart::Avg(_, count_i) => count_i.saturating_add(1),
        AggPart::Expr(..) => cursor,
        _ => cursor.saturating_add(1),
    }

match op {
        AggOperand::Slot(i) => slot(*i)?,
        AggOperand::Avg(sum_i, count_i) => finish_avg(&slot(*sum_i)?, &slot(*count_i)?)?,
        AggOperand::Literal(f) => Value::Float(*f),
    }

match op {
        SlotOp::Key => {}
        SlotOp::Sum => *into = merge_sum_partials(into, from)?,
        // `AVG`'s sum is a float (#631): it never fails on overflow.
        SlotOp::AvgSum => {
            if !(matches!(into, Value::Null) && matches!(from, Value::Null)) {
                *into = Value::Float(partial_f64(into)? + partial_f64(from)?);
            }
        }
        // A merged COUNT stays an integer, as a single segment's does
        // (#272): before, it came back as `Float`, so the *type* of
        // `COUNT(*)` depended on how many segments the scan had.
        SlotOp::Count => {
            let total = partial_i64(into)?
                .checked_add(partial_i64(from)?)
                .ok_or_else(|| VmError::MalformedProgram {
                    opcode: "Combine",
                    reason: "partial COUNT overflowed i64".to_string(),
                })?;
            *into = Value::Int(total);
        }
        // MIN/MAX keep their type and compare as one segment does (#631):
        // a segment with no rows contributes `Null`, which never wins.
        SlotOp::Min => keep_partial_extreme(into, from, std::cmp::Ordering::Less),
        SlotOp::Max => keep_partial_extreme(into, from, std::cmp::Ordering::Greater),
        // A register-wise `max`: the same sketch whatever the merge order
        // (#603). `Null` is a segment that saw no rows.
        SlotOp::Sketch => {
            if let Some(from) = decode_sketch(from)? {
                let mut merged = decode_sketch(into)?.unwrap_or_default();
                merged.merge(&from);
                *into = Value::Bytes(merged.encode().into());
            }
        }
        // The union of two sorted sets, still sorted (#817). `Null` is a
        // segment that saw no rows.
        SlotOp::IntSet => {
            if !matches!(from, Value::Null) {
                *into = Value::Bytes(union_int_sets(set_bytes(into)?, set_bytes(from)?)?.into());
            }
        }
        // The same union for strings (#820).
        SlotOp::StrSet => {
            if matches!(into, Value::Null) && !matches!(from, Value::Null) {
                // Nothing to union with: the partial itself (#823), after
                // the check a union would make.
                str_set_len(from)?;
                *into = from.clone();
            } else if !matches!(from, Value::Null) {
                *into = Value::Bytes(union_str_sets(str_set(into)?, str_set(from)?).into());
            }
        }
        // Previously a no-op (db-core#404): with more than one segment,
        // `AVG` silently returned the first segment's local average. The
        // per-segment count is a `Value::Int` in real execution but is
        // only ever divided into by the finalizer, so it is not routed
        // through `Count`'s overflow-checked path.
        SlotOp::AvgCount => *into = Value::Float(partial_f64(into)? + partial_f64(from)?),
    }

match v {
        Value::Null => Ok(None),
        Value::Bytes(bytes) => {
            Hll::decode(bytes)
                .map(Some)
                .ok_or_else(|| VmError::MalformedProgram {
                    opcode: "Combine",
                    reason: "a partial approx_count_distinct is not a valid sketch".to_string(),
                })
        }
        other => Err(VmError::MalformedProgram {
            opcode: "Combine",
            reason: format!("a partial approx_count_distinct is not a sketch: {other}"),
        }),
    }

match v {
        Value::Null => Ok(&[]),
        Value::Bytes(bytes) if bytes.len().is_multiple_of(8) => Ok(bytes),
        other => Err(VmError::MalformedProgram {
            opcode: "Combine",
            reason: format!("a partial exact COUNT(DISTINCT) is not a set of integers: {other}"),
        }),
    }

match v {
        Value::Null => return Ok(Vec::new()),
        Value::Bytes(bytes) => bytes,
        _ => return Err(torn()),
    }

match (a.get(i), b.get(j)) {
            (Some(x), Some(y)) if x < y => {
                i = i.saturating_add(1);
                *x
            }
            (Some(x), Some(y)) if x > y => {
                j = j.saturating_add(1);
                *y
            }
            (Some(x), Some(_)) => {
                i = i.saturating_add(1);
                j = j.saturating_add(1);
                *x
            }
            (Some(x), None) => {
                i = i.saturating_add(1);
                *x
            }
            (None, Some(y)) => {
                j = j.saturating_add(1);
                *y
            }
            (None, None) => break,
        }

match v {
        Value::Null => return Ok(0),
        Value::Bytes(bytes) => bytes,
        _ => return Err(torn()),
    }

match v {
        Value::Null => Ok(0),
        Value::Int(n) => Ok(*n),
        other => Err(VmError::MalformedProgram {
            opcode: "Combine",
            reason: format!("partial COUNT slot holds {other:?}, not an integer"),
        }),
    }

match v {
        Value::Null => Ok(0.0),
        other => other.as_f64().ok_or_else(|| VmError::MalformedProgram {
            opcode: "Combine",
            reason: format!("partial aggregate slot holds {other:?}, not a number"),
        }),
    }

match (into, from) {
        (Value::Null, Value::Null) => Ok(Value::Null),
        (Value::Int(a), Value::Int(b)) => a
            .checked_add(*b)
            .map(Value::Int)
            .ok_or(VmError::IntegerOverflow { opcode: "Combine" }),
        (Value::Null, Value::Int(n)) | (Value::Int(n), Value::Null) => Ok(Value::Int(*n)),
        // Decimals (and an integer at scale 0) add exactly (#632).
        (Value::Null, d @ Value::Decimal { .. }) | (d @ Value::Decimal { .. }, Value::Null) => {
            Ok(d.clone())
        }
        (Value::Decimal { .. }, Value::Decimal { .. } | Value::Int(_))
        | (Value::Int(_), Value::Decimal { .. }) => add_decimals(into, from),
        _ => Ok(Value::Float(partial_f64(into)? + partial_f64(from)?)),
    }

match v {
        Value::Decimal { unscaled, scale } => (*unscaled, *scale),
        Value::Int(i) => (i128::from(*i), 0),
        _ => (0, 0),
    }

match self.num_slots {
            Some(n) => n,
            None => self.start(chunk)?,
        }

match &mut self.index {
            KeyIndex::Int(_) => self.map_rows_int(chunk, n, &order)?,
            KeyIndex::Generic(_) | KeyIndex::Undecided => Some(0),
        }

match &keys[r] {
                Value::Int(key) => table.get_or_insert(*key, self.first_seen.len())?,
                Value::Null => table.null_group_or_insert(self.first_seen.len()),
                _ => return Ok(Some(r)),
            }

match existing {
                Some(g) => {
                    self.first_seen[g] = self.first_seen[g].min(order(r));
                    self.row_group.push(g);
                }
                None => {
                    map.insert(hashes[r], self.first_seen.len());
                    push_new_group(&mut self.acc, chunk, r);
                    self.first_seen.push(order(r));
                    self.row_group.push(NEW_GROUP);
                }
            }

match self.num_slots {
            Some(n) => n,
            None => self.start_partial(partial)?,
        }

match (&mut self.index, keys.first()) {
                (KeyIndex::Int(table), Some(AccColumn::Ints { data, nulls })) => {
                    Some(match (data.get(r), nulls.get(r)) {
                        (Some(&key), Some(false)) => {
                            table.get_or_insert(key, self.first_seen.len())?
                        }
                        _ => table.null_group_or_insert(self.first_seen.len()),
                    })
                }
                _ => None,
            }

match found {
                Some(found) => found,
                None => {
                    if !matches!(self.index, KeyIndex::Generic(_)) {
                        self.demote_to_generic();
                    }
                    let KeyIndex::Generic(map) = &mut self.index else {
                        return Err(VmError::MalformedProgram {
                            opcode: "Combine",
                            reason: "key index not initialized".to_string(),
                        });
                    };
                    let hash = acc_key_hash(keys, r);
                    let acc = &self.acc;
                    let existing = map.candidates(hash).find(|&g| {
                        keys.iter()
                            .enumerate()
                            .all(|(c, column)| acc[c].eq_entry(g, column, r))
                    });
                    match existing {
                        Some(g) => (g, false),
                        None => {
                            let g = self.first_seen.len();
                            map.insert(hash, g);
                            (g, true)
                        }
                    }
                }
            }

match existing {
                        Some(g) => (g, false),
                        None => {
                            let g = self.first_seen.len();
                            map.insert(hash, g);
                            (g, true)
                        }
                    }

match part {
            AggPart::Avg(sum_i, count_i) => {
                let column = acc[*sum_i]
                    .iter()
                    .zip(acc[*count_i].iter())
                    .map(|(sum, count)| finish_avg(sum, count))
                    .collect::<Result<Vec<_>>>()?;
                out.push(column);
                cursor = count_i.saturating_add(1);
            }
