                }
                cursor = cursor.saturating_add(1);
            }
            // The merged set becomes its size (#817).
            AggPart::ExactCountDistinct => {
                if let Some(column) = acc.get_mut(cursor) {
                    out.push(
                        std::mem::take(column)
                            .iter()
                            .map(finish_int_set)
