            let cmp = vm.cursor(instr.p1)?.idx_compare(&key, &collations).ok_or(
                ExecError::MalformedInstruction {
                    opcode: "IdxLE",
                    reason: "cursor slot is not an index cursor, or has no current entry"
                        .to_string(),
